// Forge's job recipes. Generated by scripts/build-recipes.mjs from src/recipes/*.json. Do not edit by hand.
/* ==========================================================================
   4b. JOB RECIPES (10.3)
   Expert knowledge for one kind of job, written once: what a pro adds that
   people forget to say. Forge adds the lines of the recipes a request matches.
   ========================================================================== */
/** @type {{id: string, kind: string, for?: string, when: RegExp, unless?: RegExp, add: string[], avoid?: string[], ask?: string[], role?: string, medium?: string}[]} */
const RECIPES = [
  {id:"app:slot-booking", kind:"app", when:/\b(double[- ]?book\w*|time ?slots?|online booking|booking (form|page|system|tool|calendar|app)|book(ing)? (a |an |the )?(room|desk|lane|court|table|slot|appointment|session|barber|sitter|practice)|appointment (booking|scheduling)|(room|desk|lane|court|class|session) (booking|reservation)s?)/i, add:["Block double booking on the server, including two people taking the same slot at once.","Store times in UTC and show them in the business's own time zone.","Show taken slots as disabled, and hide times that have already passed.","Let a booking be cancelled or moved, freeing the old slot immediately.","End with a confirmation screen showing what, when, and where was booked."], avoid:["bookings for times that have already passed","a slot that shows free after someone else just took it"], ask:["Can customers cancel or change a booking themselves, and up to how long before?","Should customers need an account, or just a name and phone or email?"]},
  {id:"app:capacity-booking", kind:"app", when:/\b(seat (cap|limit)|capacity|open (seats|spots)|spots? (left|remaining|open)|seats? (left|remaining)|sold.?out|max(imum)? (seats|spots|attendees|participants|people)|cap(ped)? (of|at) \d+)/i, add:["Show spots left on each session; at zero, disable booking and label it sold out.","Check remaining capacity in the same database transaction that saves the booking.","Let one booking take several spots, never more than are left.","Return spots to the pool when a booking is cancelled."], ask:["Should full sessions offer a waitlist?"]},
  {id:"app:booking-buffer", kind:"app", when:/\b(buffer|travel time|drive time|between (appointments|bookings|jobs|clients|parties|visits)|across (two )?different (client )?locations)/i, add:["Treat each booking as start, plus duration, plus buffer when checking for overlaps.","Tell the customer why a time is unavailable instead of silently hiding it.","Let the owner block off personal time and days off.","Recheck the buffer when a booking's length or time is edited."], ask:["Is the buffer a fixed amount, or does it depend on distance or service length?"]},
  {id:"app:recurring-events", kind:"app", when:/\b(recurring|repeating|biweekly|bi-weekly|every (other )?(week|month)|auto(matically)?[- ]generat\w* (visits|appointments|bookings))/i, unless:/\b(rotat\w+|whose turn)\b/i, add:["Store the repeat rule once and generate dates from it, not endless copied records.","Allow skipping or moving one occurrence without changing the whole series.","When the rule changes, update only future dates; leave past history untouched.","Show the next few upcoming dates so the owner can check the pattern."]},
  {id:"app:rotation-schedule", kind:"app", when:/\b(rotat(e|es|ing|ion)|whose (turn|week)|take turns|on.?call|carpool)/i, unless:/\b(secret|key|credential)s? rotation|\brotation polic/i, add:["Compute whose turn it is from a start date and the ordered list, so it never drifts.","Allow a one-off swap between two people without breaking the rest of the rotation.","Show who is up now and who is next, prominently.","Handle someone joining or leaving the rotation partway through."], ask:["When two people swap, do they just trade those turns, or does everyone after shift?"]},
  {id:"app:rental-availability", kind:"app", when:/\b(rent(ing)? out|equipment (reservation|rental)s?|rental (shop|company|business|yard|history)|event rental|unit rentals|supply rental|leasing company|reserv(ed|ations?) for (a |an |which )?(event|date)|multi.?day)/i, add:["Check availability by overlapping date ranges, not single days.","For items with quantities, subtract units already reserved on the overlapping dates.","Make return a separate step; an item stays unavailable until checked back in.","Flag overdue returns, showing who has the item and how to reach them.","Derive status (available, out, overdue) from reservation dates instead of setting it by hand."], ask:["Do items need time between rentals for cleaning, inspection, or delivery?"]},
  {id:"app:lending-checkout", kind:"app", when:/\b(borrow\w*|lend(s|ing)?|loan(s|ed)?|tool library|checked[- ]out|check[- ]?out (to|by)|which (tables?|apprentices?|people) ha(s|ve) (which|each))\b/i, unless:/\b(cart|stripe|payments?|online store|shopping)\b/i, add:["Keep a loan history: item, borrower, date out, due date, date returned.","Mark an item unavailable while out, and block a second checkout of it.","Highlight overdue items and sort them to the top.","Return an item with one tap from either the item or the borrower view.","Search items by name and show who has each one right now."]},
  {id:"app:price-calculator", kind:"app", when:/\b(price|cost|quote|credit|job) (calculator|estimator|builder)|\b(estimates?|calculates?) (the )?(price|cost|time|quote)|\bpric(e|ing) (table|tiers?|depends)|\bquote (form|request|tool)s?|\btier(ed)? (pricing|discount)|\b(cost per|per.unit|discount (applies|at))/i, add:["Keep prices and multipliers in an editable table, not hard-coded in the logic.","Show the breakdown line by line, then the total, updating as options change.","Store money as integer cents and round only the final displayed figure.","Save the quoted price on the order, so later price changes don't alter it.","Label the result an estimate if the final price can change."], avoid:["floating-point money math that shows values like 19.999999"], ask:["Who updates the prices, and how often?"]},
  {id:"app:expense-split", kind:"app", when:/\b(split(ting|s)? (the )?(bills?|costs?|expenses?|rent|utilities)|bill splitter|splitwise|who owes|owes? (who|whom|what)|shared (apartment )?(costs|expenses)|split (it )?(evenly|between))/i, add:["Record who paid and who shares each expense; compute balances, never store them.","Show a settle-up list with the fewest payments that clear every balance.","Handle amounts that don't divide evenly by assigning leftover cents explicitly.","Record paybacks as settlement entries instead of deleting expenses.","Let an expense exclude people who weren't part of it."], ask:["Even splits only, or sometimes by shares, percentages, or exact amounts?"]},
  {id:"app:budget-tracker", kind:"app", when:/\b(budget(s|ing)?|planned vs\.? actual|personal finance|spending tracker|track (my )?spending|net worth|remaining budget)\b/i, unless:/\b(split|who owes|tight (ai )?budget|token)\b/i, add:["Compute spent, remaining, and over-budget from logged expenses, never typed totals.","Show planned, actual, and difference per category, with overspend clearly flagged.","Update every total immediately when an expense is edited or deleted.","Make the budget's period explicit: one event, one trip, or each month.","Store money as integer cents and show one currency consistently."], ask:["Is this one budget for a single event, or one that repeats every month?"]},
  {id:"app:personal-log", kind:"app", when:/\b(log(ging)? (my|which|each|every|daily|how)|track(ing)? (my|which|how)|keep a log|bake log|life list|\w+ log app|log app|session notes|want a (simple |quick )?(log|journal|diary))/i, unless:/\b(business|company|startup|clinic|studio|shop|our|team|internal|staff|customers|employees|platform)\b/i, add:["Put 'add entry' first on screen, with today's date prefilled.","Show history newest first, with edit and delete on every entry.","Confirm before deleting an entry, or offer undo.","Show a friendly empty state explaining how to add the first entry.","Compute totals, averages, and durations from entries instead of storing them."], ask:["Just you on one device, or synced across devices or with other people?"]},
  {id:"app:habit-streak", kind:"app", when:/\b(habits?|streaks?|daily goal|goal ring|contribution graph|green squares|keep flaking)\b/i, add:["Compute streaks from logged dates in the user's local time zone, not server time.","Keep today open until midnight, so a streak only breaks after a full missed day.","Let the user fix a missed or wrong day by tapping it on a calendar.","Show the current streak and best streak separately."]},
  {id:"app:chore-chart", kind:"app", when:/\b(chores?|allowance|chore chart|sticker chart|earn(s)? (stars|points|stickers))\b/i, add:["Give each child their own chart, simple enough to tap without help.","Compute earned stars or money from completed chores, and log rewards spent.","Reset recurring chores automatically on the chosen day, keeping last week's record.","Use large tap targets, an icon beside each chore, and a cheerful done animation."], ask:["Who checks chores off: the kids, a parent, or both?"]},
  {id:"app:inventory-stock", kind:"app", when:/\b(inventor(y|ies)|stock (count|level)s?|in stock|low.?stock|restock|reorder|running low|parts? (list|inventory))\b/i, add:["Change stock through logged adjustments (sold, received, corrected) so counts can be traced.","Give each item its own low-stock threshold and flag items at or below it.","Warn before stock would go below zero.","Add quick plus and minus buttons that work well on a phone.","Search by name, filter by category, and offer a low-stock-first sort."], ask:["Should stock drop automatically when an order is made, or only when changed by hand?"]},
  {id:"app:signup-sheet", kind:"app", when:/\b(sign.?up sheets?|sign.?ups?\b|volunteer (slots|shifts|sign)|who'?s bringing|potluck|claim(ed|s)? (an? )?(item|slot|shift|chapter))/i, unless:/\b(email sign.?up|newsletter|waitlist|subscribers?)\b/i, add:["Let people claim an item or slot with just a name, no account.","Mark a slot taken the moment it's claimed, so two people can't take it.","Let people remove their own entry, and let the organizer edit or remove any.","Show what's still needed at the top and what's covered below.","Show per-slot limits, such as two people per shift, and when a slot is full."], ask:["How do you stop someone removing another person's sign-up?"]},
  {id:"app:rsvp-event", kind:"app", when:/\brsvps?\b|\b(guest list|invite page|party page|event page)\b/i, add:["Collect name, yes/no/maybe, and number of guests; show running totals to the host.","Update an existing RSVP when the same name or email resubmits, instead of duplicating it.","Put date, time, place with a map link, and what to bring above the form.","Add an add-to-calendar link.","Show the guest list only to the host unless they choose to share it."], ask:["Should guests see who else is coming?"]},
  {id:"app:waitlist-landing", kind:"app", when:/\bwait.?list\b|\b(email (signup|sign-up|capture|list)|join (the )?(list|waitlist)|coming soon page)\b/i, unless:/\b(buyer|puppy|litter|patients?|class(es)? (is |are )?full|restaurant)\b/i, add:["Validate the email, block duplicates, and show a clear thank-you state.","Store signups where the owner can see and export them as CSV.","Lead with one headline saying what it is and who it's for, then the email field.","Add a hidden honeypot field or rate limit against spam bots.","Say in one line how the email will be used."]},
  {id:"app:landing-page", kind:"app", when:/\b(landing page|sales page|marketing (page|site)|one.?page (site|website))\b/i, unless:/\b(hundreds|dozens|bulk|\d{2,}) (of )?(\w+ )?(landing )?pages\b|will.?call/i, add:["Fit the headline, one-line benefit, and main button in the first phone screen.","Repeat the main call to action after testimonials and at the bottom.","Use the owner's real testimonials and facts; mark any placeholder text clearly.","Set page title, meta description, and a share image for link previews.","Compress and size images so the page loads fast on mobile data."], avoid:["invented testimonials, logos, or numbers presented as real"]},
  {id:"app:portfolio-gallery", kind:"app", when:/\b(portfolio|galler(y|ies)|showcase (my|our) (work|art|photos)|lookbook)\b/i, unless:/\b(crypto|stock|investment) portfolio\b/i, add:["Serve resized images and lazy-load them, so big photos don't slow the page.","Open work in a lightbox with swipe and arrow-key navigation.","Give every image descriptive alt text.","Keep contact or booking one tap away on every page.","Let the owner add, reorder, and remove pieces without touching code."], ask:["Will you update the work yourself, and how often?"]},
  {id:"app:access-control", kind:"app", when:/\b(password.?protected|members.?only|private (page|gallery|galleries|area|notes)|client portal|paywall|roles?( and | & )permissions|admin vs|who (can|should) (see|view|edit)|only (they|members|staff|admins?|the owner) can)\b/i, add:["Enforce access in server or database rules, never only by hiding buttons.","Define each role and what it may view, create, edit, and delete.","Make direct links to private content fail for logged-out or wrong users.","Hash passwords; never store or display them in plain text.","Let the owner revoke someone's access."]},
  {id:"app:directory", kind:"app", when:/\b(director(y|ies)|member list|staff (bios|list)|vendor (list|map|cards)|tools directory)\b/i, add:["Search by name with results updating as you type, plus category filters.","Show a clear no-results message with a way to clear the filters.","Give each entry its own detail page with a shareable URL.","Keep phone and email hidden unless the person agreed to show them.","Sort alphabetically by default, with category tags visible on each card."]},
  {id:"app:contacts-crm", kind:"app", when:/\b(crm|contacts? (list|book)|client list|customer list|business cards|donors?|leads? (list|tracker)|track (my )?(clients|customers|leads))\b/i, add:["Search contacts by name, company, phone, or email from one box.","Keep a dated activity history per contact: calls, notes, jobs, payments.","Show a next follow-up date and a list of follow-ups due today.","Warn about duplicates by matching email or phone before saving.","Allow CSV import and export so existing contacts aren't retyped."], ask:["Will more than one person use this, and should everyone see every contact?"]},
  {id:"app:pipeline-board", kind:"app", when:/\b(pipeline|sales funnel|deal stages|applicant tracking|ats\b|moves? through (the )?(stages|process))/i, unless:/\b(ci|cd|ci\/cd|data pipeline|deploy\w*|build pipeline)\b/i, add:["Move cards by drag and drop, and also by a stage menu for phones and keyboards.","Record when each card enters a stage, so time in stage can be shown.","Show the count per column, and total value if cards carry money.","Keep closed cards (won, lost, hired, rejected) out of the way but searchable.","Save card order within each column."]},
  {id:"app:task-board", kind:"app", when:/\b(to-?dos?|task (list|board|app|manager|tracker)|project (management|tracker)|kanban|asana|trello|monday)\b/i, unless:/\b(pipeline|leads?|clients? pipeline)\b/i, add:["Add a task in one step; pressing Enter saves it.","Show overdue tasks clearly and sort by due date, undated tasks last.","Hide completed tasks behind a toggle instead of deleting them.","When several people use it, add assignees and an 'assigned to me' filter.","Persist drag-and-drop order and column changes immediately."]},
  {id:"app:issue-tracker", kind:"app", when:/\b(bug tracker|issue tracker|track(ing)? (bugs|issues|incidents)|support tickets?|help ?desk|maintenance requests?|repair (requests|jobs)|postmortems?)\b/i, add:["Give each issue a status flow and record who changed it and when.","Filter by status, severity, and assignee, with 'my open issues' as a default view.","Sort by severity, then age, so the oldest critical issue is on top.","Keep a comment thread per issue instead of overwriting the description.","Let reporters follow status updates without edit access."]},
  {id:"app:dashboard-metrics", kind:"app", when:/\b(dashboards?|kpis?|metrics|mrr|analytics|ctr|churn|profit not just revenue)\b/i, add:["Compute rates and totals (MRR, CTR, percentages) from raw records, never typed in.","Show each number with its date range and change from the previous period.","Handle zero and empty data without dividing by zero or showing NaN.","Put the three to five key numbers on top; details and tables below.","Label mock or sample data clearly as such."], ask:["What decision will you make from this dashboard, and how often will you check it?"]},
  {id:"app:related-records", kind:"app", when:/\b(linked (to|with|records?)|relationships?|relational|entit(y|ies)|data model|line items|related (lists?|records|items|visits)|relation propert(y|ies))\b/i, add:["Define entities, their fields, and one-to-many links before building screens.","On a parent's page, list its related records with an add button that pre-links them.","Decide what deleting a parent does (block, archive, or cascade) and warn first.","Copy values that must not change later, like price at order time, onto the child.","Show links both ways: customer to orders, and order back to customer."]},
  {id:"app:mvp-first-slice", kind:"app", when:/\b(complete|full(-| )?blown|full|whole|all.?in.?one|everything|the works|all of it|run my whole)\b.{0,80}\b(system|platform|app|tool|suite)\b/i, unless:/\b(complete beginner|full (code|control)|not a full|full.?day|full custom design|whole (site|app idea))\b/i, add:["Build only the agreed first slice; list other features as later, not half-built screens.","Shape the data model so later features can attach without a rewrite.","Make the first slice work end to end, including empty, error, and edit states.","End with a short, prioritized list of suggested next steps."], avoid:["placeholder pages or dead buttons for features outside this pass"]},
  {id:"app:order-ahead-menu", kind:"app", when:/\b(order(ing)?[- ]ahead|online order(ing)?|ordering menu|add to cart|\bcart\b|pickup orders?|pickup only)/i, add:["Keep the cart through reloads, with item count and total in a sticky bar on phones.","Recalculate prices on the server before accepting an order; never trust browser totals.","Let the owner mark items sold out so they can't be ordered.","Offer pickup times only within open hours, and show an order number on confirmation.","Give staff an order queue: new, preparing, ready, picked up."]},
  {id:"app:online-payments", kind:"app", when:/\b(real payments?|payment processing|stripe|subscriptions?|paywall|take (real )?(money|payments)|ecommerce|e-commerce|online store|storefront|members pay)\b/i, unless:/\b(no real payment|mark(ed)? .{0,20}paid|paid (yes|or not)|stripe'?s? (docs|api))/i, add:["Use the payment provider's hosted checkout; never handle card numbers directly.","Mark an order paid only after the provider's webhook confirms it.","Build and test everything in the provider's test mode first.","Treat failed, refunded, and cancelled payments as distinct statuses.","Keep secret API keys on the server, never in browser code."]},
  {id:"app:invoices", kind:"app", when:/\b(invoic(e|es|ing)|receipts?|deposits?|balance due|amount owed|payment schedules?)\b/i, unless:/\b(complete|full(-| )?blown|full|whole|everything|all.?in.?one)\b.{0,200}\binvoic/i, add:["Compute line totals, tax, and grand total from line items, never typed in.","Give each invoice a unique, sequential number that is never reused.","Track status (draft, sent, paid, overdue) and record the paid date.","Use a clean print layout with print CSS that hides app buttons.","Lock invoices once sent, or keep a record of later changes."]},
  {id:"app:voting-poll", kind:"app", when:/\b(vot(e|es|ing)|polls?|upvot\w*|ballots?|felt.?difficulty)\b/i, add:["Allow one vote per person per item, enforced on the server, and let it be changed.","Make clear whether results show live or only after voting closes.","Sort by vote count, highest first, with a defined tie rule.","Let an admin open and close voting and remove spam or duplicate entries."], ask:["How do you stop one person voting many times: accounts, a name, or once per device?"]},
  {id:"app:quiz-flashcards", kind:"app", when:/\b(quiz(zes)?|flash ?cards?|trivia|study cards|test (myself|yourself))\b/i, add:["Shuffle each round, and don't repeat a card until all have been seen.","Show right or wrong immediately, with the correct answer.","Track the score and offer a retry of only the missed ones.","Allow pasting many items at once, one per line, to build a set fast.","Use large buttons on phones and keyboard shortcuts on desktop."]},
  {id:"app:random-picker", kind:"app", when:/\b(random(ly|ize|izer)?|shuffle|raffle|draw (a )?(name|winner|number)|name picker|pair (us|people) up|reshuffle)\b/i, add:["Save the pasted list so it doesn't need retyping next time.","Offer 'no repeats until everyone is picked', with a visible reset.","Show the result huge and readable from across a room.","Use a fair shuffle (Fisher-Yates), not sorting by random numbers.","Handle odd counts and empty lists with a clear message."]},
  {id:"app:timer-counter", kind:"app", when:/\b(timers?|countdown|count down|pomodoro|stopwatch|tally|counter app|days (left|remaining|until)|plus button)\b/i, add:["Compute remaining time from a stored end timestamp, so it stays right when the tab sleeps.","Keep the running state through a page reload.","Show big numbers in a tabular font so digits don't jump.","Play end sounds only after a user tap, since browsers block autoplay.","Give start, pause, and reset keyboard shortcuts."]},
  {id:"app:standings-scoring", kind:"app", when:/\b(leaderboard|standings|scoreboard|scor(e|es|ing) (app|sheet|board)|rankings?|results board|league table|totals? points)\b/i, add:["Recompute standings from match or score entries every time; never edit totals directly.","Define tiebreakers explicitly and show them.","Allow correcting a wrong score, with standings updating automatically.","Make the board readable on a big screen and highlight recent changes."]},
  {id:"app:door-checkin", kind:"app", when:/\b(check.?ins?|attendance|roll call|will.?call|marks? (them )?arrived|present\/absent|sign.?in sheet)\b/i, unless:/\bmood\b/i, add:["Search by name as you type, and check someone in with one tap.","Show a running count of checked in versus expected.","Prevent double check-in, and allow undo for a wrong tap.","Use large buttons that work on a phone or tablet at the door.","Record the time of each check-in for later attendance reports."]},
  {id:"app:queue-lineup", kind:"app", when:/\b(queue|lineup|line.?up order|wait times?|first.?come|walk.?ins?|signup order)\b/i, unless:/\b(order queue|review queue|job queue)\b/i, add:["Order the queue by server timestamp so nobody can cut in line.","Show each person's position and an estimated wait.","Let staff mark people served, skipped, or no-show, and reorder when needed.","Cap the list and show clearly when it's full."]},
  {id:"app:reference-look", kind:"app", when:/\b(like|looks? like|feel(s)? like|similar to|vibe|style of|inspired by|reference)\b.{0,80}\b(notion|linear|stripe|headspace|calm|apple|trello|airbnb|spotify|duolingo|strava|vercel|robinhood|pinterest|yelp|shopify|raycast|posthog|airtable|doordash|opentable|peloton|whoop|seatgeek|waze|zendesk|hubspot|salesforce|splitwise|github|canny|linktree|instagram|uber|slack|figma)\b/i, add:["List the concrete traits to copy: spacing, type sizes, corner radius, colors, motion.","Copy layout patterns and feel, not the brand's logo, name, or icons.","Set those traits as shared design tokens used on every screen.","Keep text contrast readable, even with soft or pastel palettes."], avoid:["the reference brand's logo, name, or copyrighted illustrations"], ask:["Which one or two things about that app's look matter most to you?"]},
  {id:"app:restyle-existing", kind:"app", when:/\b(restyle|redesign|re-?skin|make it look|new look|change the (look|style|colou?rs|theme)|looks? (bland|boring|generic|ugly|dated)|instead of a (bland|boring) default)\b/i, add:["Change styles only; keep every feature, route, and piece of data working.","Define colors, fonts, spacing, and radius as shared tokens, then apply them everywhere.","Restyle empty, loading, error, and form states too, not just the main screen.","Keep text contrast at WCAG AA or better."], avoid:["rewriting app logic while restyling","dropping features to simplify the layout"]},
  {id:"app:intake-form", kind:"app", when:/\b(intake|questionnaire|surveys?|application form|branch(es|ing)|skip logic|routes? (new )?(client )?(inquir\w+|requests))\b/i, add:["Validate required fields inline, and keep answers if submission fails.","Show only questions that apply, and clear hidden answers when a branch changes.","End with a confirmation saying what happens next and when.","Give staff a submissions list with status: new, contacted, done.","Ask only for sensitive details that are truly needed, and limit who sees them."]},
  {id:"app:approval-workflow", kind:"app", when:/\b(approv(e|al|als)|reimburse\w*|sign.?off|submit(ted)? for review|lock(s|ed)? (once|after) (it'?s )?submitted|once a week is submitted)\b/i, add:["Define statuses (draft, submitted, approved, rejected) and who may move between them.","Lock submitted items; a rejection returns them with a reason.","Record who approved or rejected, and when.","Give approvers a pending queue, oldest first.","Stop people from approving their own submissions."]},
  {id:"app:simple-for-users", kind:"app", when:/\b(not techy|not tech.?savvy|huge buttons|big buttons|large buttons|grandpa|grandma|elderly|projector|front of the (class|room)|im (8|9|10|11|12)|he'?s (7|8|9|10|11)|for my (little )?(kids?|son|daughter|brother|sister))\b/i, add:["Use large text and tap targets of at least 48 pixels, with high contrast.","Keep one main action per screen, with buttons labelled in words, not only icons.","Confirm each action with a clear visible message, and make mistakes easy to undo.","Avoid hidden gestures, tiny menus, and timeouts."]},
  {id:"app:first-time-builder", kind:"app", when:/\b(never coded|never touched code|first (ever )?app|complete beginner|absolute beginner|nervous about tech\w*|first time in (her|his|my) life|doesn'?t know how to code)\b/i, add:["Build the smallest working version first and show it before adding more.","Explain each change in one or two plain sentences, with no jargon.","Offer the next small step as a choice, not a list of tasks.","Avoid any setup, installs, or keys the person must handle themselves."]},
  {id:"app:shared-live-data", kind:"app", when:/\b(both (of us|people)|me and my (partner|roommates?|wife|husband)|shared (list|calendar)|same list|sync(ed|s)? (between|across)|real.?time|updates? live|live.?ish|as others book)\b/i, add:["Store data in a shared database, not browser storage, so everyone sees the same thing.","Push changes to other open screens live, without a refresh.","When two people edit at once, never lose a newly added item.","Show a quiet offline or reconnecting notice instead of failing silently."], ask:["How should others join: an invite link, a shared code, or real accounts?"]},
  {id:"app:collection-catalog", kind:"app", when:/\b((record|book|game|card|plant|vinyl|album) collection|my collection|life list|games i own|vinyl|cookbooks?|books i'?ve read)\b/i, add:["Offer search, category filters, and sorts by name, date added, rating, or count.","Show a photo or cover grid with a toggle to a compact list.","Warn when adding an item that already exists.","Show simple stats: total items and counts by category."]},
  {id:"app:progress-chart", kind:"app", when:/\b((chart|graph|trend|line)\w*[^.]{0,30}over time|(see|track|show)s? (their |my |his |her )?progress|progress (over|chart|graph)|personal bests?|best times?|trending (up|down)|improvement|line (chart|showing)|rating after each)\b/i, add:["Plot entries by date with real date spacing on the axis.","Know whether lower or higher is better for each measure, like race times.","Compute personal bests from entries and flag a new one when it's set.","Until there are two entries, show a message instead of an empty chart.","Show exact values on hover or tap."]},
  {id:"app:listings-board", kind:"app", when:/\b(listings|listing (board|grid|cards?|page)|adoptable|marketplace|for sale|browse (items|listings|pets))\b/i, add:["Show status badges (available, pending, sold), with an option to hide unavailable items.","Filter by the fields buyers decide on, like price range and type, kept in the URL.","Give each listing a page with photos, details, and an inquiry button.","Save inquiries in a list for the owner, linked to the listing.","Let only the owner create, edit, and mark listings sold."]},
  {id:"app:credits-passes", kind:"app", when:/\b(class pass|punch cards?|credits? (balance|system|work)|monthly credits|pass credits|deducts? (from|credits))\b/i, unless:/\b(credit cards?|trade.?in)\b/i, add:["Keep a ledger of credit changes and compute the balance from it.","Deduct credits and save the booking together, so one never happens without the other.","Refund credits on cancellation within the allowed window.","Show the reset or expiry rule, such as monthly on the 1st."]},
  {id:"app:time-tracking", kind:"app", when:/\b(time (tracking|tracker|entries)|timesheets?|clock.?(in|out)|hours (logged|worked)|billable hours|logged hours|hour logs?)\b/i, add:["Store start and end timestamps; compute durations, rounding only in reports.","Catch overlapping entries and timers left running overnight.","Group hours by client and project, with weekly totals.","Lock submitted weeks; later edits need a manager to unlock."]},
  {id:"app:clickable-prototype", kind:"app", when:/\b(prototype|clickable|client demo|pitch|mock data|sample data|fake data)\b/i, unless:/\bno (fake|mock|sample) data\b/i, add:["Use realistic sample data that fits the domain, not lorem ipsum.","Make every visible button lead somewhere, even a clear 'coming soon' state.","Keep sample data in one file so a real backend can replace it later.","Mark sample data so nobody mistakes it for real."]},
  {id:"app:existing-backend", kind:"app", when:/\b(my own (custom )?(backend|api|database|postgres)|existing (backend|api|database|postgres|tables|schema)|already (have|built)\b.{0,40}\b(backend|api|database|postgres)|frontend.?only|don'?t want a new (database|one))/i, add:["Don't create a new database or backend; connect only to the existing one.","Read the base URL and keys from environment variables, never hard-coded.","Keep all API calls in one client module, typed to the existing data shapes.","Handle loading, empty, and error responses on every screen."], ask:["Can you share the API docs or table schema so the screens match the real data?"]},
  {id:"app:code-ownership", kind:"app", when:/\b(own the code|code ownership|export (the )?code(base)?|own (editor|setup)|keep (coding|developing)|locked into|lock.?in|portab\w+|own the codebase)\b/i, add:["Use a standard framework and folder layout that runs outside the builder.","Include a README with setup, environment variables, and run commands.","Keep secrets in environment variables, listed in an example env file.","Connect the project to a Git repository from the start."]},
  {id:"app:bulk-pages", kind:"app", when:/\b(hundreds|dozens) of .{0,40}pages\b|\b\d{2,} (individual |similar |near.?identical |landing |product )+pages\b|\b(programmatic seo|bulk (pages|generat\w+)|from a spreadsheet|templated pages|city\/service)/i, add:["Build one template and generate pages from a data file, one row per page.","Give each page a unique title, meta description, URL slug, and heading from its row.","Make each page's content meaningfully different, not just a swapped place name.","Generate a sitemap listing every page."], avoid:["near-duplicate pages that search engines treat as thin content"]},
  {id:"app:plan-first", kind:"app", when:/\b(plan (it |this |everything )?(out )?first|plan (this|it) out|plan mode|planning (phase|first)|before (any )?(code|coding|building)|think through the data model)\b/i, add:["Write the plan first: users, screens, data entities with fields, and main flows.","List open questions and assumptions, and wait for answers before building.","Split the build into small steps, each ending in something that works.","Mark what's in this version and what's deliberately left out."]},
  {id:"app:health-data", kind:"app", when:/\b(patients|patient (records?|enrollment|intake|data|queue|visits?)|medical|medications?|blood pressure|clinic|health records?|phi|hipaa|injur(y|ies)|care plans?|prescriptions?)\b/i, unless:/\b(vet|veterinary|pets?|dogs?|cats?)\b/i, add:["Use clearly fake demo data unless told the data is real.","Restrict health notes to the people who need them, enforced on the server.","Keep medical advice and diagnoses out of the app's text.","Flag readings against ranges the user sets, not built-in medical thresholds."], ask:["Will this hold real patient data, or demo data only?"]},
  {id:"app:admin-internal-tool", kind:"app", when:/\b(admin (panel|dashboard|page)|internal (tool|dashboard)|back.?office|feature flags?|audit log)\b/i, add:["Require login and limit the whole tool to the team.","Log who changed what, and when, for every edit.","Require typed confirmation before destructive or production changes.","Use tables with sort, filter, search, and pagination for long lists."]},
  {id:"app:display-menu-board", kind:"app", when:/\b(qr (code )?menu|menu (page|board)|on tap|specials board|staff picks)\b/i, add:["Design for phones first: large readable text, no zooming needed.","Let the owner edit items, prices, and availability without code.","Mark sold-out items instead of deleting them.","Keep images small so it loads fast on weak connections."]},
  {id:"app:calculator-tool", kind:"app", when:/\b(calculator|converter|convert(s|ing)? .{0,20}\bto\b)/i, unless:/\b(price|cost|quote|estimat\w+|credit|currenc\w+)\b/i, add:["Update results as the user types, with no submit button.","Handle empty, zero, negative, and non-numeric input with a clear message.","Round results sensibly and show units beside every number.","Remember the last inputs between visits."]},
  {id:"app:floor-plan-picker", kind:"app", when:/\b(floor ?plan|floor grid|seat(ing)? (chart|map|picker|plan)|seat map|venue map|plot map|stall (map|positions)|garden (beds|plots)|tap a stall|pick (a )?(seat|table|desk))\b/i, add:["Draw the layout from stored positions and sizes, so the owner can rearrange it.","Color each spot by status with a legend, and never rely on color alone.","Show details on tap, with spots large enough to tap on a phone.","Offer a list view of the same spots for small screens and screen readers."]},
  {id:"app:photo-uploads", kind:"app", when:/\b(upload (an? )?(photo|picture|image|headshot|receipt)|photos? (if easy|optional)|optional (photo|headshot)|before.?(and|\/).?after (photos|pics|gallery|galleries)|headshot)\b/i, add:["Resize and compress photos on upload so storage and pages stay light.","Accept phone photo formats, including HEIC, and fix rotation.","Show a preview, and allow replacing or removing a photo.","Keep photos optional unless they're truly required."]},
  {id:"app:due-dates", kind:"app", when:/\b(expir(y|es|ing|ation)|overdue|renewals?|rotation polic\w*|sunset dates?|vaccines?|best before|remind(er|ers)?|always forget|keep forgetting|tired of forgetting|next due|how often (it|they) needs?|upcoming (birthdays|dates)|birthday (reminder|list|tracker)s?|friends'? birthdays|need(s)? (to be )?reset)\b/i, add:["Compute the next due date from the last done date plus the interval.","Compute days left when displayed; never store a days-left number.","Group items as overdue, due soon, and fine, sorted soonest first.","Mark done with one tap, logging it as history and rolling the due date forward.","Show the actual date beside relative text like 'in 3 days'."], ask:["Do you want real notifications by email or phone, or is seeing it in the app enough?"]},
  {id:"app:order-queue", kind:"app", when:/\b(custom orders?|order queue|work orders?|orders? (sorted )?by due date|fall behind)\b/i, add:["Sort open orders by due date, most urgent first, with overdue ones highlighted.","Show days until due on each order, computed from the date.","Move orders through clear statuses, and keep finished ones in a searchable archive.","Let one order hold the customer's request details, contact, and any deposit paid.","Warn when a new due date lands on an already crowded day."]},
  {id:"app:rule-gated-action", kind:"app", when:/\b(eligib\w+|certif(ied|ication)s?|compatib\w+|duty.?hours?|service area|zip codes?|safety.?training|required (\w+ )?(checkbox|flag)|blocked (entirely )?(if|unless|when)|checks? (if|whether) .{0,40}before|(block|blocks) (shipping|booking))\b/i, add:["Enforce each rule on the server, not only by hiding options in the form.","Say exactly why an action is blocked and what would make it allowed.","Keep the rules (lists, limits, tables) as editable data, not hard-coded.","Recheck the rule when related data changes, such as an edited booking or expired certificate."], ask:["Should an admin be able to override a block, and should that be logged?"]},
  {id:"app:design-fidelity", kind:"app", when:/\b(figma|design system|match(ing)? (the |my |our )?design|pixel.?perfect|brand guidelines|design fidelity)\b/i, add:["Pull exact colors, spacing, type scale, and radius from the design into shared tokens.","Build each named design component once as a reusable component, then compose screens.","Match the design's breakpoints; where none exist, say what was assumed.","List any spot where the build differs from the design, and why."], avoid:["default component-library styling that overrides the design's look"]},
  {id:"app:cost-control", kind:"app", when:/\b(token (cost|usage|spend|costs)|pay by token|cost.?conscious|keeps? my (token )?costs? down|burn(ing)? credits|tight (ai )?budget|file locking|locking files)\b/i, add:["Change only the files the request names; leave everything else untouched.","Make small, targeted edits instead of regenerating whole files.","Ask before large refactors, new dependencies, or touching many files.","Summarize which files changed after each edit."]},
  {id:"code:bug-fix", kind:"code", when:/\b(bugs?|buggy|broken|isn'?t working|doesn'?t work|not working|stopped working|wrong (result|output|value|price|line|order)|wrong somehow|off by one|won'?t (load|show|work|save)|doesn'?t actually|(not|never) show(s|ing)? up|fix(es|ed|ing)?)\b/i, unless:/\b(flak(y|iness)|race condition|memory leak|oom|n\s?\+\s?1|cors|onboarding docs|pr description|changelog|code comments|readme)\b/i, add:["Reproduce the bug first and state the exact input or steps that trigger it.","Explain the root cause in one or two sentences before editing code.","Make the smallest change that fixes the cause, not just the symptom.","Add a regression test that fails before the fix and passes after.","Search for the same mistake elsewhere in the codebase and report it."], avoid:["rewriting unrelated code while fixing","silencing the error instead of fixing its cause"], ask:["What exactly happens, and what did you expect to happen instead?"]},
  {id:"code:crash-exception", kind:"code", when:/\b(crash(es|ed|ing)?|exceptions?|panic(s|ked)?|segfaults?|segmentation fault|traceback|stack trace|cannot read propert\w*|is not a function|undefined is not|null ?pointer\w*|nil pointer|keyerror|indexerror|index out of range|out of range|typeerror|referenceerror|nameerror|recursionerror|object not found)\b|\bthrows? (an? |the )?(\w+ ?)?(error|exception|\d{3})\b/i, add:["Read the full error and stack trace; name the exact line and the value that was missing or wrong.","Trace where that value comes from and why it can be null, empty or out of range.","Fix it at the source, or fail early with a clear message.","Add a test using the input that caused the crash."], avoid:["an empty catch that hides the error","wrapping everything in try/catch to make the crash disappear"], ask:["Can you paste the full error message and stack trace?"]},
  {id:"code:flaky-test", kind:"code", when:/\bflak(y|iness|es)\b|\b(fails?|failing) (about |like |roughly )?\d+ (out of|in) \d+|\b(randomly|intermittent(ly)?|sometimes) (fail|pass|red)|\bintermittent\b/i, add:["Run the test many times in a loop to measure the failure rate before and after the fix.","Look for fixed sleeps, real timers, test order dependence, shared state, network calls and randomness.","Replace fixed waits with waiting for the actual condition, element or event.","Use fake timers and a fixed clock or seed for time-dependent and random code.","Run the test alone and in the full suite to catch leaked state."], avoid:["adding retries or skipping the test as the fix","raising timeouts without finding the cause"]},
  {id:"code:race-condition", kind:"code", when:/\brace conditions?|\bconcurren(t|cy)\b|\bat the same time\b|\bsimultaneous\w*|\b(processed|processing|runs?|running|charged|sent|submits?|fires?) (twice|multiple times)|\bduplicate (jobs?|emails?|work|charges?|orders?)|\bmulti-?thread\w*|\bdeadlocks?|\bdouble[- ]?(submit|click|charge|processing)|\boverwrit\w* each other/i, add:["Describe the exact interleaving of two operations that produces the bad result.","Fix with an atomic step: unique constraint, row lock, SELECT FOR UPDATE SKIP LOCKED, or compare-and-set.","Make the operation idempotent with an idempotency key, so a repeat does no harm.","For conflicting saves, keep a version number and reject stale writes.","Write a test that runs the conflicting operations concurrently and checks the result."], avoid:["sleeps or delays that hide the race"]},
  {id:"code:backend-performance", kind:"code", when:/\b(slow|sluggish|too slow|takes? (forever|ages)|speed (it |this )?up|optimi[sz]e|performance|latency|bottleneck|hot path|timeouts?)\b/i, unless:/\b(n\s?\+\s?1|lighthouse|web vitals|slow (connections?|internet|networks?)|bad internet)\b/i, add:["Measure first: profile or time it, and report numbers before and after.","Find the biggest single cost (query, loop, I/O, allocation) before changing code.","Run independent I/O in parallel instead of one after another.","Keep results identical; check with a test or a diff on the same input."], avoid:["adding a cache before knowing the cause","micro-optimizing code that isn't on the hot path"]},
  {id:"code:db-query-performance", kind:"code", when:/\bn\s?\+\s?1\b|\bn plus one\b|\beager[- ]load\w*|\bdataloader\b|\bexplain analyze\b|\b(sql|query|queries|orm)\b.{0,60}\b(slow|terrible|optimi[sz]e|killing|seconds|timeouts?|joins)\b|\b(slow|optimi[sz]e)\b.{0,40}\b(query|queries|database|db)\b/i, add:["Log the queries for one request; count and time them before and after.","Run EXPLAIN ANALYZE on slow queries and read where the time goes.","Batch related rows with eager loading, one IN query, or a per-request DataLoader.","Add indexes matching WHERE, JOIN and ORDER BY columns; replace per-row subqueries with joins.","Keep the API response exactly the same; add a test that asserts the query count."], avoid:["SELECT * on wide tables","indexing every column"]},
  {id:"code:memory-leak", kind:"code", when:/\bmemory leaks?|\bleak(s|ing)? memory|\boom\b|\boom[- ]killed|\bout of memory|\bmemory (usage )?(climbs|grows|keeps|increas\w*)|\bheap (snapshot|grows|out)|\brestart(ed)? every (couple|few)/i, add:["Take heap snapshots some time apart under load and diff what grows.","Check unbounded caches and maps, listeners never removed, timers never cleared, and growing global arrays.","Bound caches with a max size or TTL, and remove listeners on cleanup.","Confirm with a load run that memory levels off after the fix."], ask:["Does memory grow with traffic, or steadily even when the app is idle?"]},
  {id:"code:web-performance", kind:"code", when:/\b(page ?loads?|load(ing)? times?|lighthouse|core web vitals|lcp|bundle size|slow (pages?|site|website)|slow (connections?|networks?|internet)|bad internet|first paint)\b/i, add:["Measure with Lighthouse or real-user data and report LCP, INP and CLS before and after.","Code-split routes and heavy components; remove or replace large unused dependencies.","Serve sized, compressed, lazy-loaded images with width and height set.","Cache static assets with hashed filenames and long cache headers.","For slow networks, show cached content first and retry failed requests with backoff."]},
  {id:"code:add-tests", kind:"code", when:/\b(add|write|need|get|more|missing)\b.{0,40}\b(unit |integration |e2e |end to end )?tests?\b|\btest coverage\b|\bcoverage (is|on|threshold|check|up)\b|\b(zero|no) tests\b/i, unless:/\bflak(y|iness)\b|\bmake (the )?tests pass\b|\btests? (are |is )?(failing|broke)/i, add:["Match the existing test framework, file location, naming and helpers.","Cover edge cases: empty, zero, negative, null, boundaries, rounding and invalid input.","Test behavior through the public interface, not private details.","One behavior per test, with a name that states the expected result.","If a test exposes a bug, report it instead of quietly changing the code."], avoid:["tests that run code without asserting results","mocking the unit under test"]},
  {id:"code:refactor", kind:"code", when:/\brefactor\w*|\bclean (it |this |that )?up\b|\bclean ?up (this|the|our)\b|\bbreak (it |this )?up\b|\bsplit (it|this|up)\b|\b\d{3,} lines\b|\bmessy\b|\bspaghetti|\btangled\b|\bgod (class|component|function)|\brestructur\w*|\bconsolidat\w*|\ba million things\b|\bhard to (read|follow|maintain)/i, unless:/\b(pr description|commit message|whitespace changes|readme)\b/i, add:["Keep behavior exactly the same; no new features or fixes mixed in.","If tests are missing, first write characterization tests that pin current behavior.","Change in small steps and run tests after each one.","Split by responsibility: validation, calculation, data access, and side effects like email.","List bugs you notice separately instead of fixing them silently."], avoid:["changing public names or signatures without updating every caller","formatting churn across untouched code"]},
  {id:"code:dead-code-cleanup", kind:"code", when:/\b(unused (exports?|imports?|columns?|code|functions?|files?|dependenc\w*)|dead code|commented[- ]out|never used|nobody uses|no longer used|orphan(ed)?)\b/i, add:["Prove each item is unused: search references, dynamic imports, strings, configs, scripts and tests.","Treat public APIs, entry points and framework-loaded code as used unless proven otherwise.","Remove in small separate commits, each easy to revert.","Run the build, type check and full tests after removing."], avoid:["deleting code only because no static import was found"]},
  {id:"code:typescript-types", kind:"code", when:/\b(convert|migrat\w*|port|move)\b.{0,30}\b(typescript|ts)\b|\badd (types|typing|type hints|type annotations)\b|\bany types?\b|\buses of .?any\b|\bget rid of (the )?.?any\b|\buntyped\b/i, add:["Infer types from real usage and data; use unknown plus narrowing instead of any.","Type the boundaries first: parameters, return values, API requests and responses.","Convert file by file so the project builds after each step.","Don't change runtime behavior while adding types.","Validate external data at runtime where a type alone can't be trusted."], avoid:["as casts, @ts-ignore or non-null assertions to silence errors"]},
  {id:"code:compile-type-error", kind:"code", when:/\b(type errors?|ts\d{4}|squiggl\w*|red underline|won'?t compile|doesn'?t compile|compile errors?|compiler errors?|borrow checker|cannot borrow|is not assignable|does not exist on type|missing type definitions|could not find a declaration file|unreachable code)/i, add:["Quote the exact error and explain in plain words what the compiler is protecting against.","Fix the types or ownership design, not just the message.","Make sure the editor and the build use the same config and compiler version.","For untyped packages, add a small local declaration file for the parts you use."], avoid:["any, casts, @ts-ignore or unsafe blocks without a comment explaining why"]},
  {id:"code:dependency-upgrade", kind:"code", when:/\b(upgrad\w*|bump(ed|ing|s)?|updat\w*)\b.{0,40}\b(dependenc\w*|packages?|deps|versions?|librar\w*|framework)\b|\bdependabot\b|\brenovate\b|\bmajor version\b|\bnpm audit\b|\bvulnerable (transitive )?dep\w*|\boutdated (packages?|deps|dependencies)|\bunmaintained\b|\babandoned\b/i, add:["Read the changelog and migration guide for every major version crossed.","Upgrade one major version at a time and run build and tests after each.","Search the code for every API the release notes mark as changed or removed.","Commit the updated lockfile and list anything you couldn't safely upgrade, with the reason."], avoid:["npm audit fix --force or --legacy-peer-deps to hide conflicts","upgrading unrelated packages in the same change"]},
  {id:"code:security-audit", kind:"code", when:/\bsecurity (audit|review|pass|holes?|issues?|report|team|wants)|\bpen ?test\w*|\bvulnerab\w*|\bcves?\b|\bowasp\b|\bmore secure\b|\bharden\w*|\binsecure\b|\bexploit\w*/i, add:["Check injection, broken auth, missing authorization per route, exposed secrets, unsafe uploads and missing rate limits.","Rank findings by severity and ease of exploit; fix critical ones first.","Describe a concrete attack for each finding, not a vague risk.","Add a test for each fix that shows the attack now fails.","List findings you didn't fix and why."]},
  {id:"code:sql-injection", kind:"code", when:/\bsql injection|\bsqli\b|\braw sql\b|\bstring[- ]?(concatenat|interpolat|built)\w*.{0,30}\b(sql|query)|\btemplate literals?.{0,40}\b(sql|query)|\bcodeql\b/i, add:["Use parameterized queries or ORM bind parameters for every user-supplied value.","Identifiers like sort columns can't be parameters; map them through an allowlist.","Search other routes for the same pattern and fix them too.","Add a test sending a value like ' OR 1=1 -- and assert it is harmless."]},
  {id:"code:secrets-exposed", kind:"code", when:/\b(api[- ]?keys?|secrets?|tokens?|credentials?|passwords?)\b.{0,40}\b(exposed|leak\w*|hard[- ]?coded|committed|in (the )?(code|repo|js|script|frontend|browser)|pasted|rotat\w*)|\b(exposed|leak\w*|hard[- ]?coded|committed)\b.{0,40}\b(api[- ]?keys?|secrets?|tokens?|credentials?)\b|\.gitignore|\bsecret scanning\b|\.env file/i, unless:/\bpassword hash/i, add:["Move secrets to environment variables or a secret manager; never ship them in client-side code.","Treat any committed or shared secret as leaked: rotate it, since deleting it from history isn't enough.","Ignore .env and key files in .gitignore and commit a .env.example with placeholders.","Add a secret scanner in pre-commit or CI to block future leaks.","For browser apps, call the third-party API through a small server function that holds the key."]},
  {id:"code:env-config", kind:"code", when:/\benv(ironment)?[ -]?var(iable)?s?\b|\bhard[- ]?coded (urls?|ports?|hosts?|org)|\bconfig(uration)? (files?|validation|loading)\b|\bfail fast\b|\b(dev|development)\/(staging|prod)|\bacross environments\b/i, add:["Load and validate all config once at startup with a schema; exit naming each missing or invalid variable.","Give each setting a type, and a default only where a default is safe.","Keep .env.example in sync with every variable the code reads.","Never put server secrets in client-exposed variables such as NEXT_PUBLIC_ or VITE_ ones."]},
  {id:"code:auth-login", kind:"code", when:/\b(log ?in|sign ?in|sign ?up|auth(entication)?|password reset|reset password|forgot password|nextauth|auth\.js|remember me)\b/i, unless:/\b(newsletter|volunteer|waitlist|mailing list) (signup|sign-up|sign up)/i, add:["Hash passwords with argon2 or bcrypt; never log or return them.","Return the same error for an unknown email and a wrong password.","Rate limit login and password reset per IP and per account.","Keep sessions in httpOnly, Secure, SameSite cookies, not localStorage.","Reset tokens: random, single-use, short expiry, stored hashed; end other sessions after a reset."], avoid:["rolling your own crypto","telling users whether an email is registered"], ask:["Email and password only, or also sign-in with Google or other providers?"]},
  {id:"code:jwt-tokens", kind:"code", when:/\bjwts?\b|\brefresh tokens?\b|\baccess tokens?\b|\bbearer tokens?\b/i, add:["Short-lived access tokens with rotating refresh tokens; reusing an old refresh token revokes the chain.","Verify signature, allowed algorithm, expiry, issuer and audience on every request.","Keep a server-side way to revoke tokens, such as a token version per user.","Web: refresh token in an httpOnly cookie. Mobile: in the device's secure storage.","During a migration, accept old and new auth until every client has moved."]},
  {id:"code:roles-permissions", kind:"code", when:/\b(roles?|permissions?|rbac|authori[sz]ation|is_admin|admin[- ]only|access control|multi[- ]?tenan\w*|row[- ]level security|rls|impersonat\w*|allowlist)\b/i, unless:/\bworkflow permissions|\bgithub_token\b|\bpermissions? (on|for) (the )?(workflow|action)/i, add:["Check permissions on the server for every request; hiding buttons is not security.","Put access checks in one central place and deny by default.","Block reading another user's or tenant's record by changing an id in the URL.","For multi-tenant data, scope every query by tenant, enforced in the database with row-level security.","Test every role against every action, including the forbidden ones."], ask:["Which roles exist, and what should each one be able to do?"]},
  {id:"code:rate-limiting", kind:"code", when:/\brate[- ]?limit\w*|\bthrottl\w*|\bbrute[- ]?force\w*|\bspam\b|\banti-?spam\b|\bhammer(ed|ing)\b|\bflood\w*/i, add:["Key limits by the right identity: user or API key when known, IP otherwise.","Use a shared store like Redis when more than one instance runs.","Return 429 with a Retry-After header and a clear message.","Place the limiter so it doesn't break auth, health checks or webhooks; test each.","Use stricter limits on expensive or sensitive routes like login and exports."]},
  {id:"code:input-validation", kind:"code", when:/\bvalidat\w*|\bsanitiz\w*|\bbad input\b|\btrusts? whatever|\bmalformed\b|\bmissing fields?\b|\b500 instead of (a )?400\b/i, unless:/\benv(ironment)?[ -]?var/i, add:["Validate at the API boundary with a schema; reject unknown fields.","Return 400 with field-level messages for bad input, never a 500.","Mirror the rules on the client for quick feedback, but let the server decide.","Trim and normalize input, such as email case, before validating.","Test missing, empty, wrong type, too long, whitespace-only and boundary values."]},
  {id:"code:error-handling", kind:"code", when:/\berror handling\b|\btry[ \/-]?catch\b|\bunhandled (exceptions?|rejections?|errors?)|\bcrash(es)? the (whole )?(server|process|app|page|actor system)|\berror boundar\w*|\bwhite screen|\bfragile\b|\braw stack trace|\bsupervision\b/i, add:["Use one central error handler instead of try/catch in every function.","Separate expected errors (bad input, not found) from bugs; map each to a clear status or message.","Log the full error with context on the server; show users a short, safe message.","Never swallow errors silently; handle them or rethrow with context.","Isolate failures so one bad request, component or worker can't take down the rest."]},
  {id:"code:logging-monitoring", kind:"code", when:/\b(add|set ?up|need|structured|proper|standardi[sz]e\w*)\b.{0,20}\blogging\b|\bmonitoring\b|\balert(ing|s)?\b|\bobservab\w*|\bdistributed tracing|\bopentelemetry|\b(no|zero) visibility|\bfound out .{0,40}from (a )?customer|\bsilently fail\w*/i, add:["Structured JSON logs with level, timestamp, request id and key business fields.","Pass one request or trace id through every service and log line.","Redact passwords, tokens and personal data from logs.","Alert on what users feel: error rate, latency, failed or missing job runs, not every error line.","Each alert says what broke and the first thing to check."]},
  {id:"code:github-actions-ci", kind:"code", when:/\bgithub actions?\b|\.github\/workflows|\bworkflows?\b.{0,20}\.ya?ml|\bci (pipeline|workflow|config|runs|takes)|\bmatrix build|\breusable workflows?|\bset ?up (a )?(simple )?ci\b|\brelease (notes|process)\b|\bautomatic(ally)? (posts?|comments?|labels?|assigns?)\b/i, add:["Pin third-party actions to a version or commit SHA and set minimal permissions per job.","Cache dependencies through the setup action, keyed on the lockfile.","Use concurrency groups to cancel outdated runs on the same branch.","Don't expose secrets to fork pull requests; avoid pull_request_target that checks out PR code.","Lint workflows with actionlint and confirm conditional jobs actually run."]},
  {id:"code:ci-failing", kind:"code", when:/\b(ci|build|check|pipeline|workflow|action|e2e[- ]tests?|lint)\b.{0,30}\b(fail\w*|red|broken|blocked|stuck)\b|\bmake (it|this) pass ci\b|\bred x\b/i, unless:/\bflak(y|iness)\b/i, add:["Read the failing log and quote the exact error line before changing anything.","Reproduce locally with the same command, runtime version and a clean install.","Fix each failing cause separately, and say which change fixes which failure."], avoid:["disabling checks, skipping tests or lowering thresholds to get green"], ask:["Can you paste the failing step's log or a link to the run?"]},
  {id:"code:deployment", kind:"code", when:/\bdeploy(ing|ment|ments|ed|s)?\b|\bhost(ing)? (it|this)\b|\bon my laptop\b|\bgo live\b|\bkubernetes\b|\bk8s\b|\brolling deploys?|\bzero[- ]downtime/i, add:["Deploy from CI after tests pass, never from a laptop.","Keep secrets and config in the host's environment settings, not the repo.","Run database migrations as a separate, backward-compatible step before switching traffic.","Add a health-check endpoint, and on SIGTERM finish in-flight requests before exiting.","Document a one-command rollback to the previous version."], ask:["Do you have a hosting provider in mind, or should I choose a simple one?"]},
  {id:"code:docker", kind:"code", when:/\bdocker\w*|\bcontainer images?\b|\bcompose\.ya?ml/i, add:["Copy the lockfile and install dependencies before copying source, so layers cache.","Pin base image versions; use slim images and multi-stage builds.","Run as a non-root user and keep secrets out of image layers and build args.","Add a .dockerignore for .git, node_modules, .env and build output.","Use healthchecks so dependent services wait until the database is ready."]},
  {id:"code:db-migration", kind:"code", when:/\b(db|database|schema|tables?|columns?|data)\b.{0,30}\bmigrat\w*|\bmigrat\w*.{0,30}\b(db|database|schema|tables?|columns?|data|postgres|sqlite|mysql)\b|\bmigrations? (fails?|history|files?|conflicts?)\b|\binconsistentmigrationhistory\b|\boutgrowing (sqlite|mysql)\b|\b(add|drop|rename) (a |the )?columns?\b|\bsoft[- ]delete|\bbackfill\w*|\bshard\w*/i, add:["Make schema changes backward-compatible: add, backfill, switch reads, then drop in a later deploy.","Back up first, and test the migration and its rollback on a copy of real data.","Backfill large tables in batches, not one long locking transaction.","Check row counts and key totals match before and after."], avoid:["dropping or renaming columns the running code still reads"]},
  {id:"code:framework-migration", kind:"code", when:/\b(migrat\w*|mov\w*|switch\w*|port\w*|convert\w*) (off|from|away from)\b|\bend[- ]of[- ]life\b|\bdeprecated .{0,30}in favou?r of\b|\bbig bang rewrite|\bfully gone\b/i, add:["Migrate incrementally so old and new run side by side and the app stays shippable.","Inventory every usage first and track the remaining count down to zero.","Keep the existing test suite passing at every step; it is the safety net.","Note behavior differences between old and new, and test them directly.","Remove the old dependency and config only after the last usage is gone."]},
  {id:"code:api-endpoint", kind:"code", when:/\b(add|build|create|implement|new|write|design)\b.{0,40}\b(api|endpoints?|routes?|rest|graphql|resolvers?)\b|\bapi (versioning|responses?|is inconsistent)|\bresponse envelope|\bserializers?\b|\binternal fields\b|\bopenapi\b|\bswagger\b/i, add:["Validate path, query and body with a schema at the start of the handler.","Check authentication, and that the caller may access this specific resource.","Return explicit fields through a serializer, never raw database rows with internal fields.","Use one response and error shape, with correct status codes, across endpoints.","Add integration tests for success, bad input, unauthorized, forbidden and not found."]},
  {id:"code:file-upload", kind:"code", when:/\bupload\w*|\battachments?\b|\bmultipart\b|\bpresigned\b|\bs3 buckets?/i, add:["Check file type by content (magic bytes), not just the extension or client MIME type.","Enforce a size limit before reading the whole file.","Store files under generated names in object storage or outside the web root.","Upload large files straight to storage with short-lived presigned URLs.","Serve user files with a safe Content-Type and Content-Disposition header."], avoid:["trusting the original filename or path"]},
  {id:"code:payments", kind:"code", when:/\bstripe\b|\bpayments?\b|\bsubscriptions?\b|\bpaypal\b|\bcheckout (session|page)\b|\bbilling\b|\bcharge (the )?cards?\b/i, unless:/\bevent types?\b|\bwebhook subscriptions?|\bfiltered subscriptions?|\bpayment[- ]calc/i, add:["Compute amounts on the server; never trust prices or totals sent by the client.","Treat the provider's webhook as the source of truth; verify its signature on the raw body.","Make webhook handling idempotent by storing processed event ids.","Store payment and subscription status in your database, updated only from verified events.","Test in test mode, triggering success, failure and cancellation events with the provider's CLI."], avoid:["storing card numbers yourself","marking an order paid from the client redirect alone"]},
  {id:"code:webhooks", kind:"code", when:/\bwebhooks?\b/i, unless:/\bstripe\b/i, add:["Receiving: verify the signature on the raw body, dedupe by event id, respond 2xx fast.","Do slow work in a background job after acknowledging the webhook.","Sending: sign payloads with an HMAC and a timestamp header.","Retry failed deliveries with exponential backoff and jitter, then mark the endpoint as failing.","Log every delivery attempt with status code and response time."]},
  {id:"code:email-sending", kind:"code", when:/\bemails?\b|\bnodemailer\b|\bsmtp\b|\bnewsletters?\b|\bmailer\b|\bsendgrid\b|\bmailgun\b|\boutlook\b/i, unless:/\bemail (and|&|\+|,) ?password|\bemail field\b|\bdifferent emails\b|\b(log ?in|sign ?in|sign ?up) (page|form)\b/i, add:["Send through a transactional email service or SMTP, with SPF, DKIM and DMARC set for the domain.","Send from a background job with retries, so a slow mail server never blocks the request.","Respect notification preferences and include an unsubscribe link on non-essential mail.","HTML email: table layout, inline CSS, plain-text part; Outlook ignores flexbox and grid.","Escape user input in email bodies and never put it into headers."], avoid:["SMTP passwords in the code"]},
  {id:"code:scheduled-jobs", kind:"code", when:/\bcron\b|\bcron ?jobs?\b|\bscheduled (jobs?|tasks?)|\bevery (hour|night|day|morning|monday|week)\b|\bnightly\b|\bbackground jobs?\b|\bjob queue\b|\bqueue consumers?\b|\bworkers?\b.{0,20}\b(queue|jobs?)\b|\bbullmq\b|\bsidekiq\b|\bcelery\b/i, add:["Make each job idempotent so a retry or double run does no harm.","Use a lock or a queue so only one instance runs a job when scaled out.","Log start, end, item counts and errors; alert when a run fails or doesn't happen.","Retry with backoff, cap attempts, and keep permanently failed jobs for inspection.","Exit non-zero on failure so the scheduler and monitoring see it."]},
  {id:"code:accessibility", kind:"code", when:/\baccessibility\b|\binaccessible\b|\ba11y\b|\bwcag\b|\bscreen readers?\b|\baria\b|\bkeyboard (nav\w*|only|users?)\b|\bcolou?r contrast\b/i, add:["Use semantic HTML: real buttons and links, labeled inputs, headings in order, landmarks.","Every control works by keyboard, with a visible focus outline and logical tab order.","Text contrast at least 4.5:1; meaningful alt text, or empty alt for decorative images.","Announce form errors and dynamic updates; link errors to fields with aria-describedby.","Test with a keyboard and a screen reader, not only an automated checker."]},
  {id:"code:dark-mode", kind:"code", when:/\bdark (mode|theme)\b|\blight\/dark\b|\btheme (toggle|switch\w*)\b|\btheming\b|\bcolou?r schemes?\b/i, add:["Define colors as CSS custom properties and switch them with a data-theme attribute.","Default to the system setting via prefers-color-scheme, then remember the user's choice.","Apply the saved theme in an inline script in the head, to avoid a flash of the wrong theme.","Check contrast, borders, shadows, images and form controls in both themes.","Make the toggle a real button with an accessible label."]},
  {id:"code:responsive-mobile", kind:"code", when:/\b(on|for) (my |a |the |his |her |their |friends? )?(phones?|mobile|iphones?|tablets?)\b|\bresponsive\b|\bsmall screens?\b|\bhamburger\b|\bbreakpoints?\b|\bmedia quer\w*|\bmobile (menu|view|layout|too)\b/i, unless:/\breact native\b|\bflutter\b|\bswiftui\b|\bkotlin\b|\bandroid app\b|\bios app\b|\bunity\b|\bpush notifications?\b/i, add:["Include the viewport meta tag.","Replace fixed pixel widths with max-width, percentages, flexbox or grid.","Write mobile-first styles with min-width media queries.","Tap targets at least 44px, and no horizontal scrolling at 320px wide.","Test in device emulation and on a real phone, including Safari."]},
  {id:"code:browser-compat", kind:"code", when:/\bsafari\b|\bworks (fine |perfect(ly)? )?in chrome\b|\blooks perfect in chrome\b|\bcross[- ]browser\b|\bfirefox\b|\bbrowser support\b/i, add:["Identify the exact feature involved and check its support on caniuse.","Check date parsing: Safari rejects non-ISO date strings that Chrome accepts.","For squished flex or grid images, set aspect-ratio or explicit sizes and min-width: 0.","Test the fix in every supported browser, not only the broken one."]},
  {id:"code:cors", kind:"code", when:/\bcors\b|\baccess-control-allow\w*|\bpreflight\b|\bpostman\b/i, add:["Read the exact console error and the preflight response headers in the network tab.","Allow the specific frontend origin; a wildcard origin can't be used with credentials.","Answer OPTIONS preflight requests before auth middleware runs.","Match credentials on both sides: credentials 'include' and Access-Control-Allow-Credentials true.","Check the request Content-Type and body format match what the server parses."]},
  {id:"code:caching", kind:"code", when:/\bcach(e|es|ing|ed)\b|\bstale[- ]while[- ]revalidate\b|\bmemoi[sz]\w*|\bcdn\b/i, unless:/\bgithub actions?\b|\bci\b|\bdocker\w*|\bnode_modules\b|\blru\b/i, add:["Decide the cache key and what invalidates it before writing code.","Set a TTL on every entry and cap the cache size.","Never put per-user data in a shared cache unless the user is part of the key.","Prevent stampedes: one refresh at a time while others get the stale value.","Measure the hit rate so you can tell it works."]},
  {id:"code:search", kind:"code", when:/\bsearch\b.{0,40}\b(typos?|fuzzy|partial|case|relevan\w*|returns nothing|no results|index\w*)\b|\bfuzzy\b|\belasticsearch\b|\bfull[- ]text\b|\bsearch (box|bar|feature)\b/i, add:["Normalize case, accents and extra whitespace on both the query and the indexed text.","Try the database's full-text or trigram search before adding a separate search service.","Rank exact and prefix matches above fuzzy ones; allow fewer typos in short words.","Show a clear empty state with suggestions, not a blank result.","Keep the index in sync on create, update and delete, with a full reindex job as backup."]},
  {id:"code:pagination", kind:"code", when:/\bpaginat\w*|\binfinite scroll\b|\bload more\b|\bpage \d shows\b|\bnext page\b/i, add:["Use cursor (keyset) pagination on a stable, unique sort key for large or changing data.","Cap page size on the server.","Check boundaries: no overlap or gap between pages, and a correct last page.","Return a next cursor or hasNextPage so the UI knows when to stop.","Keep sort, filter and page in the URL so views can be shared and reloaded."]},
  {id:"code:realtime", kind:"code", when:/\bwebsockets?\b|\bsocket\.io\b|\breal[- ]?time\b|\blive (updates?|cursors?)\b|\bpresence\b|\bmultiplayer\b|\bwebrtc\b|\bphoenix channels?\b|\bcollaborative\b/i, add:["The server is the authority; validate every message from clients.","Authenticate the socket connection itself, not only the page.","Handle disconnects and reconnects, resyncing state after reconnecting.","Plan for several server instances with shared pub/sub.","Test with two clients, a slow network and a dropped connection."]},
  {id:"code:offline-sync", kind:"code", when:/\boffline\b|\bsync when (back )?online\b|\bservice workers?\b|\bpwa\b|\bwithout (signal|internet)\b/i, add:["Cache the last loaded data locally and show it with a last-updated note.","Queue changes locally with unique ids and replay them when back online.","Pick a conflict rule, last write wins or merge per field, and state it.","Show clear offline and retry states instead of blank screens.","Test with the network throttled and fully off, including app restarts."]},
  {id:"code:feature-flags", kind:"code", when:/\bfeature flags?\b|\ba\/?b test\w*|\bbeta access\b|\bsoft[- ]launch\b|\bstaged (rollout|percentage)|\bkill switch\b|\bpercentage rollout\b|\blaunchdarkly\b/i, add:["Evaluate flags in one place, with a typed list of flag names and safe defaults.","Assign users stickily by hashing the user id, so they don't switch variants.","Fall back to defaults if the flag source is unreachable.","Give each flag an owner and a removal date so it doesn't become permanent.","Roll out by percentage, with a quick way to turn the flag off."]},
  {id:"code:frontend-state-bug", kind:"code", when:/\bre-?render\w*|\buseeffect\b|\bsetstate\b|\bstale (state|closures?)\b|\bhydration\b|\bcomputed (props?|propert\w*|values?)\b|\breactive statements?\b|\b(doesn'?t|does not|isn'?t|not|never) (update|rerun|re-run|refresh)\w*/i, add:["Explain which value the UI reads and why it doesn't see the change.","Update state immutably with new arrays and objects instead of mutating in place.","Check effect dependencies and cleanup for stale closures and duplicate fetches.","Derive values from existing state instead of copying them into extra state."]},
  {id:"code:loading-states", kind:"code", when:/\bloading (states?|spinners?|indicators?)\b|\bspinners?\b|\bblank (screen|page|for a)\b|\bempty states?\b|\bflicker\w*|\bskeletons?\b/i, unless:/\b(cli|terminal|command[- ]line)\b/i, add:["Handle four states: loading, error with retry, empty, and loaded.","Avoid flicker: combine related requests, keep old content while refetching, or delay the spinner briefly.","Reserve space for content so the layout doesn't jump.","Ignore responses from outdated requests when inputs change quickly."]},
  {id:"code:forms", kind:"code", when:/\bforms?\b|\bwizard\b|\bmulti[- ]?step\b|\bonboarding flow\b/i, add:["Give each input a visible label, the right type and an autocomplete attribute.","Validate on blur and on submit, showing errors next to the field.","Disable submit while sending to stop double submits, and keep the user's input on error.","Show success only after the server confirms it.","Multi-step: keep data in one store, validate each step, and allow going back without losing input."]},
  {id:"code:destructive-actions", kind:"code", when:/\b(delete|deleting|deletes|remove|archive|archiving)\b.{0,40}\b(confirm\w*|undo|accident\w*|recoverable|permanent\w*|no way to)\b|\bbulk[- ]delete\b|\bundo\b|\bsoft[- ]delete\b/i, add:["Prefer undo, a soft delete with a short window, for frequent actions; confirm only irreversible ones.","The confirmation names the item and the consequence, with a clearly labeled destructive button.","Do the delete on the server with permission checks, inside one transaction.","Soft delete: filter deleted rows from every query and purge after the retention period."]},
  {id:"code:drag-and-drop", kind:"code", when:/\bdrag(ging)? ?(and|&|n|'n'|-n-|-and-) ?drop\b|\bdnd\b|\breorder\w*|\bsortable\b/i, add:["Store an explicit position field and save it after each drop.","Use a maintained drag-and-drop library that supports keyboard and touch.","Update the UI immediately and roll back if saving fails.","Use fractional or spaced positions so a move updates one row, not all of them."]},
  {id:"code:i18n", kind:"code", when:/\bi18n\b|\binternationali[sz]\w*|\blocali[sz](e|ation)\b|\btranslations?\b|\bmulti[- ]?(language|lingual)\b|\bmulti[- ]?currency\b|\brtl\b/i, add:["Move text into message files keyed by id; don't build sentences by joining strings.","Use ICU message format for plurals and placeholders.","Format dates, numbers and currency with Intl and the user's locale.","Detect the locale, allow switching, and remember the choice.","Leave room for longer text and right-to-left layouts."]},
  {id:"code:dates-timezones", kind:"code", when:/\btime ?zones?\b|\butc\b|\bdst\b|\bdaylight saving\b|\bdates?\b.{0,30}\b(wrong|off|bug|pars\w*|format\w*|thing)\b|\bpars\w* dates?\b|\bmoment(\.js)?\b|\bdate-fns\b|\bhours? off\b/i, unless:/\bout of date\b|\bup to date\b/i, add:["Store and send timestamps as UTC ISO 8601; convert to local time only for display.","Keep the user's IANA time zone when local time matters, like events and reminders.","Parse user input with explicit formats, never the built-in Date parser on free text.","Test around DST changes, month ends, leap days and midnight."]},
  {id:"code:money-calc", kind:"code", when:/\bcurrenc\w*|\bmoney (values?|amounts?|calc\w*|math|fields?)\b|\bpric(e|ing) (calc\w*|logic)\b|\bpayment[- ]calc\w*|\btax(es)?\b|\bdiscounts?\b|\brounding\b/i, add:["Store money as integer minor units or a decimal type, never floating point.","Keep the currency code with every amount.","Round once, at a defined step, using a stated rounding rule.","Test zero, negative, very large and rounding-boundary amounts."]},
  {id:"code:docs-readme", kind:"code", when:/\breadme\b|\bdocumentation\b|\bdocs\b|\bjsdoc\b|\bdocstrings?\b|\bchangelog\b|\brunbook\b|\bpostmortem\b|\bpr descriptions?\b/i, unless:/\bdocs-only\b/i, add:["Check every command, path and option against the actual repo before writing it.","Open with what it does and a copy-paste quickstart that works on a clean machine.","Document configuration, environment variables, and common errors with their fixes.","Keep examples short and runnable; remove outdated parts instead of adding caveats.","Changelogs and PR descriptions: group by added, changed, fixed, and say why, from the actual diff."]},
  {id:"code:ai-instructions-file", kind:"code", when:/\bagents\.md\b|\bclaude\.md\b|\bcopilot-instructions\b|\.cursor\/rules|\.cursorrules|\bcursor rules\b|\b(repo(sitory)?|custom|project)[- ](custom )?instructions\b|\brules file\b|\binstructions file\b/i, add:["Short, concrete, checkable rules; cut generic advice like 'write clean code'.","State the exact build, test and lint commands, and what counts as done.","Pair each banned pattern with the preferred one: use X, not Y.","List files or areas that need a human's approval before changes.","Keep it to about a page; long files get skimmed or ignored."]},
  {id:"code:vague-ticket", kind:"code", when:/\b(doesn'?t|does not) (say|specify)\b|\bno (other |further |specific )?(details?|specifics|description|repro\w*|text description)\b|\bthat'?s (literally |really )?(all it says|the whole (ticket|thing))|\bentire ticket\b|\buse your judge?ment\b|\bfeels buggy\b|\bgo (find|figure out|dig)\b/i, add:["Investigate before changing code: recent errors and logs, CI history, recent commits, most-used flows.","State your reading of the request and the evidence for it.","Fix only problems you can reproduce or prove; list suspected ones separately.","Report what you checked, what you found, what you fixed, and what you left alone."]},
  {id:"code:autonomous-handoff", kind:"code", when:/\bhand (it |this )?off\b|\btake (your|the) time\b|\bwalk away\b|\bunattended\b|\bovernight\b|\bjust let it run\b|\bkick (this|it) off\b|\bcome back (to|later)\b|\bbabysit\w*|\bpr when (ready|done)\b|\bopen (a )?pr\b|\band pr( it)?\b|\bpr back\b|\bassign(ing)? (you|this|a whole)\b|\bwithout (me )?(guiding|driving|watching)\b/i, add:["Start with a short plan: steps, risks, and a command that proves success.","Work on a branch in small commits, running tests after each step.","Stop and report instead of guessing on destructive, irreversible, security or payment steps.","End with a PR description: what changed, why, how it was tested, and open questions."], avoid:["force-pushing, deleting data, or changing CI and secrets without asking","expanding scope beyond the ticket"]},
  {id:"code:git-ops", kind:"code", when:/\bmerge conflicts?\b|\bconflict markers\b|\brebase\b|\bgit history\b|\bwhitespace changes\b|\bforce[- ]push\w*|\bcherry[- ]pick\w*|\bgit blame\b|\bsplit\w* .{0,30}\brepos?\b|\bpreserve .{0,20}history\b/i, add:["Back up the branch with a tag or copy before rewriting history.","Keep unrelated whitespace and formatting out of the diff; check with git diff -w.","Resolve conflicts by understanding both sides, then build and run tests.","Use --force-with-lease on your own branches and never force-push shared ones.","Extract a folder with its history using git filter-repo."]},
  {id:"code:lint-format", kind:"code", when:/\beslint\w*|\bprettier\b|\blint(er|ing|s)?\b|\bauto[- ]?format\w*|\bformatter\b|\bpre-?commit\b|\bhusky\b|\beditorconfig\b|\bcode style\b|\bconventional commits\b|\bconsole\.log\b/i, add:["Let the formatter own formatting, and turn off lint rules that conflict with it.","Run the same config in a pre-commit hook on staged files and in CI.","Put mass auto-fixes in their own commit, separate from behavior changes.","Fix real lint errors in code; use disable comments only with a stated reason.","Add the bulk reformat commit to .git-blame-ignore-revs."]},
  {id:"code:github-repo-settings", kind:"code", when:/\bbranch protection\b|\brulesets?\b|\bcodeowners\b|\brequired (status )?checks?\b|\bissue templates?\b|\bauto[- ]?label\w*|\blabeler\b|\bdependabot\.ya?ml\b|\bpr templates?\b/i, add:["Keep settings as code where possible: rulesets, CODEOWNERS, labeler and dependabot configs.","Required status check names must exactly match the job names that run.","Apply branch rules to admins too, and test them with a throwaway PR.","In CODEOWNERS the last matching line wins; use team handles, not individuals."]},
  {id:"code:game-dev", kind:"code", when:/\b(games?|platformer|roguelike|unity|godot|pygame|phaser|sprites?|jump physics|collisions?|hitbox\w*|game loop|screen shake)\b/i, add:["Run physics on a fixed timestep and scale movement by delta time.","Resolve collisions one axis at a time; stop fast objects tunneling with substeps or swept checks.","Keep feel values in named constants: gravity, jump velocity, coyote time, jump buffer.","Keep input, update and rendering separate.","Save files to the engine's user data folder, writing a temp file and then renaming it."]},
  {id:"code:chat-bot", kind:"code", when:/\b(discord|twitch|telegram|slack) bots?\b|\bdiscord\.(py|js)\b|\bbot tokens?\b/i, add:["Load the bot token from an environment variable; reset it if it was ever shared or committed.","Enable the gateway intents the bot needs, like message content, in code and the developer portal.","Catch errors per command so one failure doesn't stop the bot.","Store per-server settings keyed by server id.","Respect platform rate limits and add cooldowns to commands."]},
  {id:"code:scraping", kind:"code", when:/\bscrap(e|es|ing)\b|\bbeautifulsoup\b|\bbs4\b|\bcrawl(er|ing)?\b|\bselenium\b/i, add:["Check whether the data loads by JavaScript; look for the JSON API in the network tab first.","Respect robots.txt and the site's terms, and rate limit requests.","Select by stable attributes, and fail loudly when the page structure changes.","Save raw pages while developing so you don't re-fetch on every run."]},
  {id:"code:cli-tool", kind:"code", when:/\bclis?\b|\bcommand[- ]line\b|\bargparse\b|\bclap\b|\bsubcommands?\b|--help\b|\bprogress bars?\b|\bterminal output\b/i, add:["Clear --help with grouped options and real examples.","Exit 0 on success and non-zero on error; errors go to stderr, data to stdout.","Turn off colors and spinners when output isn't a terminal or NO_COLOR is set.","Settings precedence: flags, then environment variables, then config file, then defaults.","Short, actionable error messages instead of stack traces."]},
  {id:"code:data-script", kind:"code", when:/\bscripts?\b|\bautomat(e|ing)\b|\bcsv\b|\bexcel\b|\bspreadsheets?\b|\bbatch (jobs?|process\w*)\b|\bparalleli[sz]\w*/i, unless:/\bgithub actions?\b|\bworkflows?\b|\bcontent scripts?\b|\bglobal scripts\b/i, add:["Make it safe to re-run: same input, same output, no duplicate side effects.","Validate input and report bad rows with line numbers instead of crashing.","Add a --dry-run mode for anything that changes files or data.","Print progress and a summary at the end; exit non-zero on failure.","Stream large files instead of loading everything into memory."]},
  {id:"code:env-mismatch", kind:"code", when:/\bmodule not found\b|\bcannot find module\b|\bno module named\b|\bmissing module\b|\bworks (fine )?(on|in) (my|local)\b|\bworks locally\b|\bfile not found\b|\bvirtual ?env\w*|\bvenv\b|\bdrift\w*|\bstaging\b.{0,30}\bprod\w*/i, add:["Compare both environments exactly: runtime version, env vars, working directory, installed packages.","Print the actual path, version or config value at runtime instead of assuming it.","Pin versions with a lockfile and a version file like .nvmrc or .python-version.","Fix it so a clean install reproduces the working setup."]},
  {id:"code:audit-log", kind:"code", when:/\baudit (logs?|trails?|logging)\b|\btamper\w*|\bwho changed\b|\bbefore\/after values?\b|\bcompliance\b/i, add:["Append-only records: who, what action, which record, when, before and after values, request id.","Write the audit record in the same transaction as the change.","Block updates and deletes on the audit table at the database level.","Leave secrets and passwords out of recorded values."]},
  {id:"code:backups", kind:"code", when:/\bbackups?\b|\bdisaster recovery\b|\brestore (process|drill|from)\b|\bpoint[- ]in[- ]time\b/i, add:["A backup only counts once a restore is tested; script and time the restore.","Keep copies in a separate account or region, encrypted, with a retention policy.","Alert when a backup fails or doesn't run.","Document the restore steps and the acceptable data loss and downtime."]},
  {id:"code:algorithm-from-scratch", kind:"code", when:/\bfrom scratch\b|\b(implement\w*|build\w*|need)\b.{0,40}\b(algorithm|dijkstra\w*|binary search tree|bst|linked list|lru|rope|b-?tree|heap|hash ?map|trie|raft|garbage collector|consensus)\b/i, add:["State the time and space complexity of each operation.","Test edge cases: empty, single item, duplicates, and the largest expected input.","Check results against a simple brute-force version on many random inputs.","Keep the public interface small and document its invariants."]},
  {id:"code:ai-tool-choice", kind:"code", when:/\b(want|wants|need|needs|looking for)\b (an? |just |decent |quick |lightweight |some )*(ai|assistant|agent|tool|pair programmer|ai teammate|code completions?|inline (code )?(completions?|suggestions) (while|as|in|plus)|something (that|for|with|i can|reliable|free|cheap|baked))\b|\bdelegat\w* .{0,40}\bto an ai\b/i, add:["Match the tool to the workflow: inline completion, editor chat, multi-file agent, or GitHub-based PR agent.","Give setup steps for the recommended option, including the instructions file it reads.","Say plainly what it can't do and the limits of any free tier.","Offer one alternative for a different budget or editor."], ask:["Which editor do you use, and do you want to pay or stay free?"]},
  {id:"code:beginner-learning", kind:"code", when:/\bi'?m (1[0-7]|a beginner|new to|just starting|learning)\b|\b(trying to )?learn(ing)? (to code|c|python|java|rust|javascript)\b|\bfirst (discord bot|bot|game|app|project|time)\b|\bschool project\b|\bhomework\b|\bfor (my |a )?(class|course)\b|\bdont (really )?understand\b|\bno idea (why|whats)\b/i, add:["Explain the cause in plain words before showing the fix.","Show the smallest change that fixes it, then why it works.","Define each new term in one sentence the first time it appears.","End with one habit that prevents this kind of bug next time."]},
  {id:"image:logo-mark", kind:"image", when:/\blogo\b|\bmonogram\b|brand mark|\blogomark\b|\bwordmark\b|scale of justice mark/i, unless:/\blogo (sting|intro|animation|reveal)|intro logo|logo (on|onto) (a|the|our)|put (our|my|the) .{0,20}logo (on|onto)|sponsor logos?/i, add:["flat vector mark with one clear silhouette that still reads at favicon size","two or three solid colors, simple geometric construction, even line weight","centered on a plain white background with generous empty margin","shapes that still work printed in a single color"], avoid:["tiny details that vanish when shrunk","photographic texture and 3D bevels","extra invented words or fake lettering"], ask:["Should the business name be part of the logo, and exactly how is it spelled?","Where will it be used most: sign, truck, website, or a tiny social icon?"]},
  {id:"image:sports-mascot-logo", kind:"image", when:/esports|gaming logo|team (logo|mascot)|mascot (logo|head)|mascot for our .{0,20}(team|club)|sports team|athletic/i, unless:/\b(cute|kawaii|friendly|approachable|gentle)\b/i, add:["mascot head in three-quarter view with a fierce forward-facing expression","thick bold outlines and flat cel-shaded color blocks","strong silhouette that reads on a jersey and as a small avatar","two or three team colors plus black and white"], avoid:["thin hairline details","realistic fur or photo texture"], ask:["What are the team colors, and the exact team name if text is included?"]},
  {id:"image:friendly-mascot", kind:"image", when:/\bmascot\b|cute (\w+ )?character|little character|cartoon character/i, unless:/esports|fierce|aggressive|sports team|team (logo|mascot)|consistent|across (three|multiple|several|different)/i, add:["rounded simple body shapes with a large head and big expressive eyes","clean outlines and flat colors that reproduce on cups, signs and stickers","friendly open pose, small smile, one hand waving","full body visible on a plain white background"], avoid:["sharp teeth or angry brows","complex shading that won't print small"], ask:["Will this mascot need to appear again in other poses or scenes?"]},
  {id:"image:badge-crest-emblem", kind:"image", when:/\bbadge\b|\bpatch\b|\bemblem\b|\bseal\b|\bcrest\b|coat of arms|heraldr?y|heraldic|hang tags?/i, unless:/conference badge|name badge|badge (design )?template|attendee/i, add:["circular or shield-shaped badge with a clean outer border ring","one central icon framed by space for text along the rim or a ribbon scroll","bold flat vector shapes in a limited palette, gold and silver as flat yellow and grey","symmetrical layout on a plain background"], avoid:["photographic detail","crowding many small symbols together"], ask:["What text or motto goes on the border or ribbon, spelled exactly?"]},
  {id:"image:single-icon", kind:"image", when:/\bicon\b|pictogram|\bglyph\b/i, unless:/\bicons\b|icon set|app icon|server icon|inventory|class icon|game('?s)? (ui|hud)/i, add:["single centered symbol built from simple geometric shapes","uniform stroke weight and closed shapes, readable at small size","one or two flat colors on a plain background","front-on view with no scene or perspective behind it"], avoid:["background scenery","fine texture or gradients","words or letters"]},
  {id:"image:icon-set", kind:"image", when:/\bicons\b|icon set|set of .{0,20}icons|matching icons|icon variations/i, add:["matching icons on a shared grid with identical stroke width and corner radius","same size and padding for every icon, evenly spaced in a row or grid","one consistent style throughout, all outline or all filled, one palette","each icon a simple, widely recognized metaphor on a plain background"], avoid:["mixed styles or line weights","text labels inside icons"], ask:["List every icon you need, in order."]},
  {id:"image:app-icon", kind:"image", when:/app icon|discord (server )?icon|server icon|favicon|inventory|item icon|class icon|skill icon|\bemote\b/i, add:["one bold symbol centered in a square tile, filling about two thirds of it","solid or two-tone background running edge to edge","dark outline and a bright rim highlight separating the symbol from the background","no text, readable at tiny on-screen size"], avoid:["words or letters","thin hairlines","more than one object"]},
  {id:"image:tattoo-design", kind:"image", when:/\btattoo/i, unless:/\blogo\b|tattoo (shop|parlou?r|studio)/i, add:["clean confident linework with closed shapes","bold blacks and open negative space that hold up as ink spreads over years","flash-sheet style design isolated on plain white paper","overall shape suited to the body placement"], avoid:["skin, body or background scenery","fine hatching and tiny text that blur when healed"], ask:["Where on the body, and roughly how big?","Black and grey, or colour?"]},
  {id:"image:sticker", kind:"image", when:/sticker|die[- ]?cut|\bdecal\b|enamel pin|\bpin design/i, unless:/wall decal|full storefront|storefront window decal/i, add:["thick white die-cut border around the whole design","bold dark outlines and flat colors that print cleanly","one compact silhouette without thin parts sticking out","plain background around the design"], avoid:["soft gradients and fine texture","tiny text"], ask:["One sticker, or a sheet of several? How many?"]},
  {id:"image:apparel-print", kind:"image", when:/t-?shirt|\btee\b|hoodie|sweatshirt|tote bag|jacket back|varsity|merch|screen ?print/i, unless:/\blogo\b/i, add:["standalone print artwork isolated on a plain background","limited spot colors and solid shapes that screen print cleanly","bold lettering large enough to read from a few meters away","composition centered in a tall rectangular print area"], avoid:["photographic gradients","tiny text"], ask:["What garment color will it print on?"]},
  {id:"image:invitation-greeting-card", kind:"image", when:/invitation|\binvite\b|save the date|\brsvp\b|wedding program|(birthday|holiday|christmas|anniversary|greeting|diwali|eid|valentine'?s?|sympathy|thank you|get well|easter|new year) card/i, unless:/\b(pic|photo|img|image|picture)\b|business card|trading card|recipe card/i, add:["clear hierarchy: names or greeting largest, date and place smaller","generous margins with a delicate border or corner ornaments","one display script paired with a clean serif, two or three colors","flat front-on card on a plain surface"], avoid:["filler text","busy backgrounds behind the wording"], ask:["What exact wording goes on it: names, greeting, date, time, place?"]},
  {id:"image:event-poster-flyer", kind:"image", when:/^(?=.*\b(poster|flyer|flier|leaflet|banner)\b)(?=.*\b(event|festival|party|night|concert|show|fair|sale|meetup|celebration|service|open house|market|fiesta|carnival|parade|ceremony|gala|tournament|lineup|fundraiser|drive|reunion|exhibit|screening|graduation|camp|race|marathon)\b)/i, unless:/\b(pic|photo|img|image|picture) for\b|photography|travel poster|propaganda|wpa|movie poster|key art|wanted poster|scientific poster|science fair poster|twitch|photograph|\bshot of\b/i, add:["clear hierarchy: event name biggest, then date and time, then place","one bold focal image with the headline above it or over open space","large high-contrast type readable from across a room","two or three colors plus a neutral, generous margins"], avoid:["filler text","more than two typefaces"], ask:["What exact words must appear: event name, date, time, place?"]},
  {id:"image:image-for-text-overlay", kind:"image", when:/\b(pic|photo|img|image|picture|background|shot)\b.{0,25}\b(for|on)\b.{0,40}\b(flyer|invite|invitation|post|newsletter|poster|card|sign|email|brochure|slideshow|calendar|ad)\b/i, unless:/\bsays\b|that says|with the (word|words|name|phrase)|\btext\b|lettering|spelled/i, add:["one clear focal subject placed off-center","calm uncluttered area of open space for text to be added later","no lettering, signs or words anywhere in the image"], avoid:["random text or fake signage"], ask:["Will text sit over this image? If so, top, bottom or side?"]},
  {id:"image:exact-short-text", kind:"image", when:/\bsays\b|that says|saying|spelled|with the (word|words|name|phrase)|exactly (right|as written)|in (big|bold|huge) letters|name (spelled|written)|print(ed)? (huge|giant|big)|blown up/i, add:["the exact wording in quotation marks, spelled letter for letter","lettering large and centered with clear space around it","one bold legible typeface in high contrast with the background","no other words, letters or signage anywhere in the image"], avoid:["extra or misspelled words","hairline details that blur when enlarged"], ask:["What is the exact wording, including capitals and punctuation?"]},
  {id:"image:dense-text-layout", kind:"image", when:/\bdense\b|lots of (small |little )?(text|facts|rules|clues)|packed with|full list|long list|bunch of|schedule|timetable|agenda|menu board|price list|tap list|wine list|beer list|cocktail menu|nutrition (facts|label)|ingredient list|directory|scoresheet|bracket|standings|spec sheet|syllabus|rubric|rules (sign|poster|card)|reference card|family tree|scientific poster|research poster|science fair poster|sections for/i, add:["strict grid layout with aligned columns and consistent spacing","one clean sans serif in only two or three sizes","dark text on a light plain background, high contrast","bold section headings with thin divider lines between groups"], avoid:["decorative textures behind text","invented filler words"], ask:["Can you paste the exact text, line by line?","Should text be drawn in, or blank boxes left to type into later?"]},
  {id:"image:foreign-script-text", kind:"image", when:/\b(arabic|hebrew|yiddish|chinese|mandarin|cantonese|japanese|korean|hangul|hindi|devanagari|thai|tamil|russian|cyrillic|greek|ukrainian|persian|farsi|urdu|bengali|punjabi|amharic|kanji|vietnamese|polish|turkish|portuguese|spanish|german|french|czech|tagalog|swahili)\b|accent marks|diacritic|quincea/i, add:["the exact supplied text in quotation marks, every character and accent as given","short text set large with ample space around each character","correct reading direction and letter joining for the script","no invented pseudo-characters anywhere else in the image"], avoid:["decorative fake script","dropped or misplaced accent marks"], ask:["Can you paste the exact text, checked by a native reader?"]},
  {id:"image:bilingual-layout", kind:"image", when:/bilingual|both (english|languages)|in (english|french|spanish) and|and english|english (and|&) \w+|side by side/i, unless:/cell side by side/i, add:["two languages in parallel blocks with equal visual weight","matching size and alignment for each translation pair","a thin divider or color shift separating the languages"], avoid:["one language squeezed into small print"], ask:["Can you paste the exact text for each language?"]},
  {id:"image:product-photo-white", kind:"image", when:/product (photo|shot|pic)|listing photo|etsy|amazon|shopify|e-?commerce|online shop|grocery (store )?listing|packshot|private label/i, unless:/lifestyle|in use|styled|flat ?lay|scene|hero shot|campaign|\bad\b|before/i, add:["product centered on a seamless pure white background","soft even studio light from large softboxes, gentle contact shadow beneath","label facing camera, sharp edge to edge, true-to-life color","straight-on eye-level angle, product filling most of the frame"], avoid:["props hiding the product","invented logos or label text"]},
  {id:"image:product-hero-ad", kind:"image", when:/(hero|key visual|campaign|launch|print ad|\bad\b|rebrand).{0,60}(watch|bottle|perfume|serum|sneaker|shoe|can\b|whiskey|backpack|phone|smartwatch|candle|headphones|product)|(watch|bottle|perfume|serum|sneaker|shoe|whiskey|smartwatch|backpack|energy drink).{0,60}(hero|campaign|launch|\bad\b|premium|luxury|expensive)/i, add:["controlled studio light with a rim light tracing the product's edges","one hero product at a slightly low angle, open negative space for copy","deliberate highlights on glass and metal; backlight glowing through any liquid","crisp focus on the product, background softly out of focus"], avoid:["clutter competing with the product","invented brand names on the product"]},
  {id:"image:flat-lay", kind:"image", when:/flat ?lay|top[- ]down|from directly overhead|overhead shot/i, unless:/token|\bmap\b|top down circular/i, add:["shot directly overhead, camera parallel to the surface","objects arranged with even spacing and breathing room","soft diffused light with short gentle shadows","textured base surface such as linen, marble or wood"], avoid:["perspective tilt","overcrowded arrangement"]},
  {id:"image:food-photo", kind:"image", when:/food|pizza|burger|cake|cupcake|sushi|ramen|pasta|steak|taco|croissant|pancakes|cinnamon roll|cookies?|sourdough|loaf|dessert|signature dish|plate of|latte|granola|\bpie\b|tasting menu|cheese/i, unless:/\blogo\b|\bicon\b|menu board|\blist\b|\bcard\b|\bsign\b|label|chart|calendar|nutrition|banner|can design|wrap design/i, add:["soft side or back light raking across the food to show texture and gloss","camera angle matched to the dish: overhead for flat, eye level for tall","fresh garnish, a few crumbs or drips, light steam if hot","neutral surface and simple props, shallow depth of field"], avoid:["plastic-looking oversaturated food","cluttered table"]},
  {id:"image:real-estate-photo", kind:"image", when:/real estate|listing (photo|pic|shot|mockup)|for (the|a|our) (rental )?listing|listing photos|airbnb|vacation rental|realtor|living room|bathroom|bedroom|hotel lobby|lobby photo|interior (photo|shot)|showroom|curb appeal|farmhouse|house pic|front of (the |our |my )?house|just listed/i, unless:/\b(take|turn) (my|our|the|this)|my .{0,20}photo|actual .{0,20}photo|virtually stage|floor plan|yard sign|skyline|color scheme|poster|chart|diagram|schedule|\bmap\b|handshake|agent|gaming|gamer|desk setup|battle ?station|neon/i, add:["wide lens at chest height with perfectly vertical lines","bright balanced exposure, window views visible, lights switched on","tidy staged space, neutral decor, no people or cars","soft daylight, or warm dusk glow for exteriors"], avoid:["fisheye distortion","blown-out windows"]},
  {id:"image:venue-interior-photo", kind:"image", when:/^(?=.*\b(interior|inside|dining room|taproom|lobby|storefront)\b)(?=.*\b(photo|photorealistic|realistic|shot|pic|picture)\b)(?=.*\b(cafe|coffee shop|restaurant|bar|taproom|bookstore|gym|hotel|salon|spa|bakery|brewery|office|shop|boutique|library|studio)\b)/i, unless:/\b(take|turn) (my|our|the|this)|actual .{0,20}photo|virtually stage|renovat|logo|sign\b|menu board|illustrat|cartoon/i, add:["eye-level view from a seated customer's position, wide-normal lens","warm practical lights in frame: pendant lamps, candles or string lights","soft window daylight balancing the warm interior glow","lived-in details on tables and shelves, shallow depth of field"], avoid:["sterile empty showroom look","warped furniture lines"]},
  {id:"image:architecture-render", kind:"image", when:/architect|render of (a|an|the) .{0,30}(house|building)|building we designed|studio crit|isometric city/i, add:["two-point perspective at human eye height, verticals perfectly straight","honest materials: glass reflections, concrete texture, wood grain","low late-afternoon sun casting long clean shadows","a few small human figures for scale, simple landscaping"], avoid:["fantasy lighting effects","warped geometry"]},
  {id:"image:staging-renovation-preview", kind:"image", when:/virtual(ly)? stag|renovat|remodel|redesign(ed)? (room|kitchen|bathroom|bedroom)|before ?(\/|and|&) ?after|landscaped|painted (a |in )?\w+ (green|blue|grey|gray|white)|home gym|set up like|reorganized/i, unless:/physique|muscular|teeth|smile|posture|furniture restoration/i, add:["same room shape, windows, doors and camera position as the original photo","new furniture scaled to the room, shadows touching the floor","realistic finishes, light matching the existing windows","neutral, uncluttered styling"], avoid:["moved walls or windows","floating furniture"], ask:["What must stay exactly the same in the photo?"]},
  {id:"image:headshot", kind:"image", when:/headshot|linkedin (photo|pic|profile|headshot)|profile (photo|pic)|corporate portrait/i, add:["head and shoulders framing, eyes in the upper third, body angled slightly","soft key light from one side with gentle fill, catchlights in the eyes","plain softly out-of-focus neutral backdrop","portrait-lens look, sharp eyes, natural skin texture"], avoid:["plastic airbrushed skin","busy background"], ask:["Describe the person: hair, glasses, skin tone, clothing?"]},
  {id:"image:realistic-portrait", kind:"image", when:/\bportrait (of|photo|shot)\b|portrait photography|environmental portrait|editorial (style )?portrait|national geographic portraits/i, unless:/headshot|\bpet\b|\bdog\b|\bcat\b|renaissance|anime|\boc\b|npc|pixar|cartoon|character|illustrat|painted|fantasy|elf|wizard|knight/i, add:["one directional light source with soft falloff into shadow","natural skin texture with pores and wrinkles, no retouching","subject in their real setting with a few telling objects","eye-level medium shot, shallow depth of field, sharp eyes"], avoid:["waxy smooth skin","stiff posed smile"]},
  {id:"image:candid-people-photo", kind:"image", when:/(candid|authentic|genuine|not (generic )?stock|stock[- ]?ish|realistic|real looking|convincing|photorealistic).{0,80}\b(person|people|man|woman|worker|chef|hands|hikers?|family|instructor|scientist|mechanic|librarian|beekeeper|tailor|potter|glassblower|blacksmith|barista|volunteers|owner|musician|child|kids|couple)\b/i, unless:/illustrat|cartoon|painted|anime/i, add:["candid moment mid-action, subject absorbed in the task, not looking at the camera","natural available light, lived-in workspace with real wear","real-world imperfections: creased clothing, worn tools, natural skin","documentary framing slightly off-center, wide-normal lens"], avoid:["perfect symmetrical stock-photo smiles","warped hands and fingers"]},
  {id:"image:fashion-editorial", kind:"image", when:/lookbook|vogue|fashion|high fashion|model in|runway|editorial (shot|spread)|magazine (cover|spread)/i, unless:/food|ramen|dish/i, add:["model in a strong elongated pose with the garment in motion","one deliberate light style across the frame, hard sun or soft overcast","minimal location with bold color or texture contrast to the outfit","full-length or three-quarter framing, open space at the top"], avoid:["generic catalog posing","distorted hands"]},
  {id:"image:pet-photo", kind:"image", when:/(dog|puppy|cat|kitten|pet)('?s)? (portrait|photo|pic)|(portrait|photo|pic|picture) of (a |my |our )?(\w+ ){0,2}(dog|puppy|cat|kitten|retriever|beagle)|pet (insurance|adoption|grooming)|happy healthy dog/i, unless:/\blogo\b|\bicon\b|sticker|cartoon|illustrat|drawn|renaissance|phone case/i, add:["camera at the animal's eye level, sharp focus on the eyes with catchlights","soft natural light showing individual fur strands","relaxed body, ears forward, mouth softly open","simple background softly blurred"], avoid:["extra legs or merged paws","human-like expressions"], ask:["What breed, coat color and markings?"]},
  {id:"image:memorial-tribute", kind:"image", when:/memorial(?! day)|passed away|\bpassed\b|late (father|mother|mom|dad|husband|wife|grand\w*|brother|sister|son|daughter)|funeral|in loving memory|rest in peace|celebration of life|in memory/i, add:["face and features kept exactly as in the source photo","soft warm natural light, calm dignified expression","gentle muted palette with a simple uncluttered background","shared lighting and scale so everyone looks photographed together"], avoid:["changing facial features or age","over-smoothed airbrushed skin"], ask:["Which photo shows them most the way you remember them?"]},
  {id:"image:photo-restoration", kind:"image", when:/restor(e|ed|ation)\b.{0,40}photo|photo.{0,40}restor|coloriz|colouriz|old (faded|damaged) photo|faded and damaged|creases|scratched photo|torn photo/i, unless:/furniture|restoration (business|shop)|motorcycle/i, add:["faces, expressions and proportions identical to the original","creases, scratches, stains and dust removed","natural period-accurate colors with realistic skin tones","light original film grain kept, no over-sharpening"], avoid:["modernized clothing or hairstyles","waxy smoothed skin"]},
  {id:"image:combine-people-photos", kind:"image", when:/combine|composit|blend(ed)? (them|into)|add (our|my) (friend|brother|sister|dad|mom)|group (photo|shot)|reunion|together in (one|the same)|in the same (picture|photo)|never (got|had|been) .{0,30}together/i, unless:/logo|backdrop design|awning|color scheme|consistent illustrated/i, add:["every face kept exactly as in its own source photo","one shared light direction and color temperature on everyone","consistent scale, eye lines and ground contact with matching shadows","natural spacing and slight overlaps like one real group shot"], avoid:["pasted cutout edges","mismatched sharpness or grain"], ask:["Which photo should set the background and lighting?"]},
  {id:"image:photo-edit-local", kind:"image", when:/^(?=.*\b(my|our|this|the|her|his|their) (actual |current |existing |old )?([\w'-]+ ){0,3}(photo|selfie|headshot|picture|pic)\b)(?=.*\b(change|changed|swap|replace|remove|recolou?r|lowered|rims|altered|instead of|background|stage|show (it|what))\b)/i, unless:/watercolou?r|pixar|cartoon|painting|anime|wanted poster|movie poster|shot on film|combine|reunion|group photo|together/i, add:["only the named element changed, everything else identical to the original","same camera angle, framing, lighting and shadows as the source photo","edited area matched in grain, sharpness and perspective","faces, hands and existing text left untouched"], avoid:["restyling the whole image","changing the person's face"], ask:["Exactly what should change, and what must stay the same?"]},
  {id:"image:transform-person-photo", kind:"image", when:/(turn|turned|make|transform)\w* (my|our|this|the|their|someone'?s?) [^,.]{0,30}(photo|selfie|picture|portrait|sketch|drawing)[^,.]{0,40}\b(into|as)\b|(photo|selfie)[^,.]{0,30}(pixar|cartoon|watercolou?r|anime|oil painting|wanted poster|movie poster|renaissance)|age progression|aged up|what (i|id|i'd|he|he'd|she|she'd|we|we'd|they) [^,.]{0,15}look like|with a beard|years older/i, add:["face shape, eyes, nose, hairline and distinctive marks kept recognizable","same pose, expression, angle and framing as the source","only the requested change applied: style, age or feature"], avoid:["a generic face that no longer looks like the person"]},
  {id:"image:childrens-book-art", kind:"image", when:/picture book|storybook|children'?s book|kids?'? book|bedtime story|story ?book|kid'?s (story|bedroom)|for (my|our) (kids?|daughter|son|niece|nephew)'?s? (story|book|room)/i, add:["soft painterly gouache or watercolor texture with rounded shapes","warm limited palette with one calm focal point","characters with large heads, simple faces and readable emotions","open space at the top or bottom for page text"], avoid:["scary sharp details","photoreal rendering"], ask:["Will the same characters appear on other pages?"]},
  {id:"image:consistent-character", kind:"image", when:/\bconsistent\b.{0,40}(character|version|mascot|party|setting|style|cartoon|illustrat)|same character|across (a|an|the|multiple|three|several|whole|entire|different) .{0,20}(scenes|pages|images|posts|panels|book|series|product photos)|reused|already (generated|established)|character sheet|match the established/i, add:["character identical to the reference: same face, hair, outfit colors and proportions","same art style, line weight and palette as the earlier images","the character's fixed traits restated word for word in every prompt"], avoid:["changing outfit, hair or body proportions between images"], ask:["Can you attach the reference image or list the character's fixed traits?"]},
  {id:"image:book-cover", kind:"image", when:/book cover|novel|memoir|\bebook\b|audiobook|kindle|cover (art|illustration|image|photo) for (my|our|the) .{0,30}book|cookbook|rulebook/i, unless:/album|podcast|comic book cover|book report/i, add:["tall portrait composition with the focal image in the middle or lower two thirds","clear empty space at the top for the title and bottom for the author","one strong silhouette that still reads as a small thumbnail","palette and lighting matched to the genre"], avoid:["random fake lettering"], ask:["Should the title and author name be in the image, or added later?"]},
  {id:"image:square-music-podcast-cover", kind:"image", when:/album|\bep\b|mixtape|soundcloud|playlist cover|cover (art|image) for (my|our) (podcast|band|beats|single)|podcast (cover|art)/i, add:["square composition that still reads as a tiny thumbnail","one striking central image with strong contrast","clear zone for artist and title, or none if text is added later"], avoid:["many small details","fake lettering"], ask:["Should the artist or show name be part of the image?"]},
  {id:"image:video-thumbnail", kind:"image", when:/thumbnail|youtube/i, unless:/documentary|music|jingle|video footage|logo sting|spotify/i, add:["wide 16:9 frame with one large subject filling a third or more","exaggerated expression or action, bright saturated contrasting colors","subject separated from the background by a rim light or outline","clear empty area for a few big words"], avoid:["small details","busy backgrounds"]},
  {id:"image:wide-banner-header", kind:"image", when:/twitch|channel (banner|art)|youtube banner|header (image|pic)|blog header|website (header|banner|hero)|hero (image|photo|pic|shot) for (my|our) .{0,30}(site|website|page)|facebook (cover|page)|cover photo for/i, add:["very wide composition with the subject offset to one side","key elements kept in the central safe area so crops don't cut them","simple edges that can crop or extend without losing anything","open area beside the subject for a headline"], avoid:["important details at the far edges"]},
  {id:"image:retro-poster-style", kind:"image", when:/travel poster|\bwpa\b|propaganda|railway poster|airline .{0,20}poster|national park poster|vintage poster/i, add:["flat screen-printed color shapes in a limited palette of five or six inks","bold simplified scene with layered depth and a strong diagonal","large condensed sans serif or Art Deco title band","subtle paper grain and slight ink misregistration"], avoid:["photographic detail","soft gradients"]},
  {id:"image:key-art-splash", kind:"image", when:/key art|splash art|box art|box cover|game (box|cover)|steam page|cinematic (still|frame|cutscene)|loading screen|title card|movie poster|film poster|villain reveal|boss reveal/i, add:["dramatic low angle with the main figure dominant in the foreground","strong rim light and backlight separating the hero from the background","deep atmosphere: fog, embers or dust, and distant scale cues","clear space at the top or bottom for a title logo"], avoid:["many equal-sized figures competing for attention","fake title lettering"]},
  {id:"image:character-concept", kind:"image", when:/character|\boc\b|\bnpc\b|class select|character select|roster|hero card|party member|playable race|token for my/i, unless:/logo|sticker|mascot|\bconsistent\b|reused|character study|national geographic|cute (\w+ )?character/i, add:["figure in a three-quarter pose with a clear, readable silhouette","costume details that tell the role: gear, wear and materials","one dominant accent color tying the outfit together","simple atmospheric background that doesn't compete with the figure"], avoid:["cropped hands or feet","generic armor with no story"], ask:["Full body or bust, and what pose or action?"]},
  {id:"image:creature-boss-concept", kind:"image", when:/\bboss\b|monster|creature|\bbeast\b|dragon|golem|troll|kaiju|demon|bestiary|summon|guardian|construct|werewolf|phoenix|griffin/i, unless:/\blogo\b|\bicon\b|sticker|\bcute\b|kawaii|\bkids?\b|friendly|for my daughter/i, add:["a small human figure or object nearby to show scale","low camera looking up, creature filling most of the frame","believable anatomy: weight on the limbs, clear joints and musculature","rim light outlining the silhouette against a darker background"], avoid:["creature cropped off the frame edges","muddy unreadable silhouette"]},
  {id:"image:environment-concept", kind:"image", when:/environment|background for (my|our|a)|\barena\b|dungeon|tavern|establishing|worldbuilding|menu background|capital city|floating (city|island|castle)|underwater city|scene for my/i, unless:/\bmap\b|logo|character|\boc\b/i, add:["distinct foreground, midground and background layers for depth","a lit path or focal point leading the eye into the scene","atmospheric haze and light shafts that sell the scale","open stage-like area where characters or interface can sit"], avoid:["flat even lighting","clutter in every corner"]},
  {id:"image:fantasy-map", kind:"image", when:/(fantasy|treasure|campaign|world|continent|kingdom|island|pirate|setting|dungeon|battle) map|map (of|for) (my|our) (campaign|world|kingdom)|map legend|battlemap/i, add:["hand-inked map on aged parchment with a compass rose and scale bar","mountains as small drawn hills, forests as clustered tree symbols","muted sepia and earth tones with soft watercolor washes","few short place names, or blank label areas to fill in later"], avoid:["garbled invented place names"], ask:["Overview map of a region, or a top-down battle map on a grid?","Which place names must appear, spelled exactly?"]},
  {id:"image:diagram-infographic", kind:"image", when:/infographic|diagram|flowchart|flow chart|org chart|timeline|life cycle|cutaway|exploded[- ]view|explainer graphic|comparison chart|chart showing|bar chart|\bgraph\b|dashboard|periodic table|solar system|water cycle|photosynthesis|anatom/i, add:["clean flat vector style on a plain light background","numbered steps or labeled parts joined by straight thin leader lines","accurate textbook proportions and positions for every part shown","bars and segments drawn proportional to the given values","short labels in a bold sans serif, two to four accent colors"], avoid:["invented or misspelled labels","made-up numbers","3D tilted charts"], ask:["List every label, step or number exactly as it should read.","Should labels be drawn in, or left blank to type in later?"]},
  {id:"image:instruction-pictograms", kind:"image", when:/instruction|assembly|how to fold|ikea|safety card|step by step|correct posture/i, add:["simple line drawings with a uniform black stroke on white","numbered panels in reading order, one action per panel","arrows showing the direction of movement","neutral figures without facial features"], avoid:["shading or photo detail","paragraphs of text"]},
  {id:"image:naturalist-illustration", kind:"image", when:/field guide|audubon|botanical|bestiary|naturalist|encyclopedia|seed packet|scientific illustration|apothecary/i, add:["fine ink linework with delicate watercolor washes on off-white paper","subject in clear profile with accurate anatomy","small numbered callouts with thin leader lines","aged paper tone and a restrained natural palette"], avoid:["cartoon proportions"]},
  {id:"image:seamless-pattern", kind:"image", when:/seamless (pattern|tile|repeat)|repeating pattern|wrapping paper|fabric (print|pattern)|surface pattern|wallpaper pattern|\bpattern\b/i, unless:/loop|music|video|border/i, add:["seamless repeat with motifs crossing the tile edges so joins vanish","even motif density with no single focal point","flat colors in a limited palette of three to five","square tile composition"], avoid:["visible seams","a frame or border around the tile"]},
  {id:"image:sign-design", kind:"image", when:/storefront|window (sign|decal)|shop sign|\bsignage\b|marquee|street sign|wayfinding|door sign|yard sign|chalkboard|neon sign/i, add:["flat front-on view of the sign","lettering large and centered, readable from across the street","surface rendered honestly: chalk on slate, painted wood, gilded glass, neon tube or metal","the exact sign wording only, nothing else written"], avoid:["extra invented words"], ask:["What exact words go on the sign?"]},
  {id:"image:packaging-label", kind:"image", when:/\blabel\b|packaging|can design|box design|box back|bottle label|\bjars?\b|\btins\b|coffee bag/i, unless:/\blogo\b|flat ?lay|style graphic but funny/i, add:["flat front-on label artwork in the label's real shape","clear hierarchy: brand at top, product name largest, details small below","spot colors and solid shapes that print cleanly","all text kept inside a safe margin from the edges"], avoid:["invented brand names","tiny unreadable claims"], ask:["Flat label artwork for printing, or the label shown on the product?"]},
  {id:"image:landscape-photo", kind:"image", when:/^(?=.*\b(photo|photograph|photorealistic|realistic|nature photography|shot|pic)\b)(?=.*\b(mountains?|sunset|sunrise|beach|ocean|seascape|forest|storm|foliage|summit|lake|waterfall|prairie|canyon)\b)/i, unless:/\b(logo|icon|sticker|badge|poster style|travel poster|illustrat\w*|painted|painting|cartoon|anime|food|cake|bread|sourdough|product|portrait of|headshot|dog|cat|puppy|listing|living room|house|cabin|people|couple|family|hikers|runner|athlete|worker|owner|fish|fashion|model|signs?|add (our|my)|take (my|our|this))\b/i, add:["strong foreground element leading the eye to the horizon","golden hour or blue hour side light revealing texture","wide lens from a low position, horizon on a third line","natural colors, not oversaturated"], avoid:["HDR halos","oversaturated sky"]},
  {id:"image:action-sports-photo", kind:"image", when:/gym|fitness|workout|athlete|runner|mid-?stride|climb(er|ing)|skiing|ski resort|sports photography|action shot|hiking boots/i, unless:/\blogo\b|\bbadge\b|schedule|decal|\bsign\b|yoga|calm|pt clinic|interior|posture/i, add:["fast shutter freezing motion: flying sweat, chalk dust or snow spray","hard side light carving muscle and texture","low camera angle making the athlete dominant","real gear and real effort in the face"], avoid:["posed stock-photo smiles","warped limbs"]},
  {id:"image:analog-photo-look", kind:"image", when:/polaroid|shot on film|film look|35mm|analog|disposable camera|hand tinted|black and white|\bb&w\b|monochrome|magnum|street photography/i, add:["fine organic film grain with slightly lifted blacks","gentle halation around highlights and a light vignette","unposed moment framed close with a wide-normal lens","available light only"], avoid:["clean digital sharpness","staged poses"], ask:["Colour film or black and white?"]},
  {id:"image:horror-atmosphere", kind:"image", when:/horror|scary|creepy|haunted|spooky|unsettl|halloween|eerie|gothic/i, unless:/\bgore\b|not scary/i, add:["one hard light source with deep shadows hiding most of the scene","something subtly wrong in the frame instead of gore","desaturated sickly palette with one cold accent color","fog or haze swallowing the background"], avoid:["bright even lighting"]},
  {id:"image:anime-illustration", kind:"image", when:/\banime\b|\bmanga\b|kawaii|chibi|\b1girl\b|ghibli|miyazaki/i, unless:/junji|horror manga/i, add:["clean cel-shaded illustration with crisp lineart and two-tone shadows","large expressive eyes with layered highlights","softly hand-painted background separating the character"], avoid:["extra fingers","photoreal skin"]},
  {id:"image:card-game-art", kind:"image", when:/tarot|trading card|card game|playing card|hero card|legendary card|card back|baseball card/i, unless:/greeting|birthday|business card|recipe card/i, add:["tall portrait card composition with a framed art window","central figure with symbolic objects arranged around it","art kept clear of the lower area reserved for name and text","ornate border with blank panels for name and stats"], avoid:["garbled stat text"], ask:["Just the artwork, or the full card with frame and text?"]},
  {id:"image:device-mockup", kind:"image", when:/mockup|mock-up|app (running )?on an? (iphone|phone|laptop|tablet)|app screen|phone screen|blank (coffee )?mug/i, unless:/floor plan|nutrition|label/i, add:["device or object at a slight angle with accurate real proportions","screen or print content flat and sharp, fitted to the surface perspective","clean neutral surroundings, soft daylight reflections on glass"], avoid:["warped screens","gibberish interface text"]},
  {id:"research:quick-answer", kind:"research", when:/\b(quick|fast|simple|short|straight)\b[^.]{0,30}\b(answers?|questions?|facts?|lookup|explanation|check\w*)\b|\bkeep it (simple|short)\b|\bnot (a|the) (whole|full|long) (report|research\w*)|\bnothing deep\b|\btell me straight\b|\b(current|latest|most recent|today'?s)\b[^.]{0,30}\b(rate|price|number|figure)\b|\bunemployment rate\b/i, unless:/\b(thorough|in[- ]depth|comprehensive|deep dive|long and detailed|dissertation)\b/i, add:["Lead with the direct answer in one or two sentences, no preamble.","Name the one most authoritative source behind it.","For numbers that change, give the as-of date, the official publisher, and when it next updates.","Add one line on the main exception or when the answer changes.","If the evidence is uncertain, say so once instead of hedging every sentence."], avoid:["a long report with headers","figures quoted from memory without a date"]},
  {id:"research:product-comparison", kind:"research", when:/\b(best|top|cheapest|safest)\b[^.]{0,40}\b(under|below|less than)\s*\$?\d|\breviews? that (are|arent|aren't)\b|\bwirecutter\b|\bconsumer reports\b|\b(laptops?|telescopes?|headphones|mattress(es)?|vacuums?|cameras?|tvs?|monitors?|stroller)\b[^.]{0,40}\b(best|which|compare|comparing|specs?|aperture)\b|\b(best|which|compare|comparing)\b[^.]{0,40}\b(laptops?|telescopes?|headphones|mattress(es)?|vacuums?|cameras?|tvs?|game engines?)\b|\b(game engines?|ring shopping|engagement rings?)\b/i, add:["Turn the person's use into the few specs that actually matter, and say why each matters.","Prefer independent lab tests and long-term owner reviews over affiliate listicles.","Compare 3 to 5 picks in a table: price, key specs, main weakness, best for.","Give one clear pick per budget or use case, with the reason.","Explain how to spot fake or paid reviews, and note that prices swing."], avoid:["spec sheets copied without saying what matters","marketing numbers taken at face value"], ask:["What will you mainly use it for, and what is your top budget?"]},
  {id:"research:baby-gear-safety", kind:"research", when:/\b(car seats?|strollers?|cribs?|bassinets?|baby (monitors?|carriers?|gates?)|high ?chairs?|booster seats?|playpens?)\b/i, add:["Use government crash-test and ease-of-use ratings, and check the recall database for each model.","Check the weight, height and age limits, and whether it fits the family's vehicle.","Note expiration dates, and why second-hand seats with unknown crash history are risky.","Separate the safety standard every sold model meets from features that add real protection."], avoid:["ranking by social media popularity"], ask:["What car will it go in, and what is your budget?"]},
  {id:"research:car-buy-lease", kind:"research", when:/\b(leas(e|ing)|financ(e|ing)|buy(ing)?)\b[^.]{0,40}\b(cars?|vehicles?|vans?|trucks?|suvs?)\b|\b(cars?|vehicles?|vans?|trucks?|suvs?)\b[^.]{0,40}\b(leas(e|ing)|good price|fair price|asking)\b|\b(used|new|first|electric) (cars?|vehicles?|trucks?|evs?)\b|\bcar (shopping|shopper|buying|loan)\b/i, unless:/\bcar seats?\b/i, add:["Compare total cost over the ownership period: payments, insurance, fuel or charging, maintenance, resale value.","For a lease, check the mileage cap and per-mile overage cost against the person's yearly miles.","For a used car, compare several valuation guides and local listings with similar mileage and trim.","Check reliability data, open recalls, and a vehicle history report before judging the price.","For electric cars, cover home charging, cold-weather range, battery warranty, and incentive eligibility."], avoid:["sticker price or monthly payment alone as the comparison"], ask:["How many miles a year do you drive, and how long will you keep it?"]},
  {id:"research:home-buying", kind:"research", when:/\b(home|house) (inspection|inspector|warranty|buyers?|purchase)s?\b|\bfirst[- ]time (home ?)?buyer|\bbuy(ing)? (a|my first|this|our first|the) (house|home|condo)\b|\bclosing on (a|the|this|my|our) (house|home)\b|\binspection reports?\b/i, add:["Separate safety and structural issues from cosmetic ones, with rough repair cost ranges.","List what a standard inspection excludes and which specialist checks suit the house's age.","For home warranties, read the caps, exclusions, service-call fees, and pre-existing condition clauses.","Note what can still be negotiated before closing: repairs, credits, or price."], avoid:["treating every inspection note as a deal-breaker"], ask:["How old is the house, and when do you close?"]},
  {id:"research:payback-math", kind:"research", when:/\bsolar\b|\b(energy|electric(ity)?|power) (bill|use|usage|savings?|costs?)\b|\buse less electricity\b|\battic fans?\b|\bleed certif\w*|\bheat pumps?\b|\binsulation\b|\bpays? (for )?(it|them)sel(f|ves)\b|\bpays? off\b|\bactually cheaper\b|\bcheaper than buying\b/i, add:["Work savings from real inputs: upfront cost, incentives, running costs, local prices or rates.","Use government calculators and independent tests, not installer or seller estimates.","Show pessimistic, middle, and optimistic payback years, with the assumption behind each.","Include financing cost, maintenance, local net-metering rules, and how long the person will stay."], avoid:["the seller's savings estimate taken at face value"]},
  {id:"research:insurance-and-warranties", kind:"research", when:/\b(insurance|insurer|warrant(y|ies)|umbrella polic\w*|premiums?|deductibles?)\b/i, unless:/\b(denied|denial|deny|appeal)\b|\bmedicare\b|\bmedigap\b/i, add:["Compare expected payout against total premiums over time, using claim or failure-rate data.","List exclusions, waiting periods, caps, deductibles, and what existing coverage already pays.","Use the state insurance regulator's consumer guides and complaint data.","Say who this coverage makes sense for and who could cover the risk from savings."], avoid:["the seller's or agent's pitch used as evidence"], ask:["What coverage do you already have, and could you pay the worst-case cost yourself?"]},
  {id:"research:insurance-claim-denial", kind:"research", when:/\bclaims?\b[^.]{0,60}\b(denied|denial|rejected)\b|\b(denied|denial|rejected)\b[^.]{0,60}\b(claims?|insurer|insurance)\b/i, add:["Quote the exact policy clauses the denial cites, and test the insurer's reading against the wording.","Check definitions, exclusions, and endorsements that add or restore coverage.","Outline the appeal path, its deadlines, and the state regulator's complaint process.","List the documents and proof that would strengthen an appeal.","Mark this as research, not legal advice, and say when a coverage lawyer or public adjuster helps."]},
  {id:"research:medical-treatment", kind:"research", when:/\b(surgery|surgical|surgeon|diagnos\w*|symptoms?|treatments?|headaches?|migraines?|braces|invisalign|scoliosis|knee replacement|chronic|disease|anxiety|speech delay\w*|delayed)\b/i, unless:/\b(dogs?|cats?|pupp(y|ies)|pets?|vet|veterinar\w*|plants?|trees?)\b|\buploaded\b|\bvaccin\w*/i, add:["Prefer clinical practice guidelines, systematic reviews, and large trials over single studies or forums.","Match the evidence to the patient's age and other conditions, and say when studies excluded people like them.","Give outcomes as absolute numbers: complication rates, recovery time, long-term results.","Compare the options side by side, including watchful waiting where that is reasonable.","End with specific questions to ask the doctor; do not diagnose."], avoid:["relative risk without the absolute numbers"]},
  {id:"research:medical-docs-explained", kind:"research", when:/\b(doctors?'? notes?|visit summar(y|ies)|medical (records?|stuff|reports?|notes?)|specialist (reports?|letters?|visit)|lab results?|discharge (papers|instructions)|care logs?|pediatrician letter|after ?care instructions)\b/i, add:["Explain each medical term in one plain sentence, using only what the documents say.","Pull out what is recommended, by whom, and the next steps with dates.","Show where the documents agree, disagree, or leave something open, with page references.","List questions to bring to the next appointment."], avoid:["adding diagnoses or advice the documents do not contain"]},
  {id:"research:meds-supplements", kind:"research", when:/\b(supplements?|melatonin|magnesium|creatine|probiotics?|vitamins?|essential oils?|medications?|meds|otc|over the counter|antihistamines?|dosage|side effects)\b/i, unless:/\bdrugs?'?s? pric\w*|\bper prescription\b/i, add:["Grade the evidence: systematic reviews and controlled trials first, then small or animal studies.","Compare the doses and forms used in trials with what products actually contain.","Cover interactions, who should avoid it, and long-term safety data or its absence.","Say how the product is regulated and which independent purity-testing seals exist.","Compare options in a table: what it treats, how well it works, common side effects, cost."], avoid:["influencer or seller claims used as evidence"], ask:["Do you take other medications or have any health conditions?"]},
  {id:"research:nutrition-fitness-science", kind:"research", when:/\b(diets?|fasting|keto|cooking oils?|nutrition|carbs?|carb loading|protein|calories|cold (plunges?|showers?)|ice baths?|standing desks?|on (my|your) feet|workouts?|exercise science|weight loss|healthiest)\b/i, add:["Weigh meta-analyses and randomized trials above observational studies and news coverage.","Report effect sizes in plain terms, with study length, size, and who was studied.","Separate changes in lab markers from real outcomes like disease, performance, or weight kept off.","Note who funded key studies and where experts genuinely disagree.","Say who should avoid it or check with a doctor first."], avoid:["one study presented as settled"]},
  {id:"research:kids-health", kind:"research", when:/\b(toddlers?|infants?|newborns?|pediatric\w*|screen time|sleep training|vaccin\w*|immuni[sz]ation|milestones?|low fevers?)\b|\bmy (kid|son|daughter|child)'?s? (health|fever|speech|sleep|teeth)\b/i, unless:/\b(car seats?|strollers?|cribs?)\b/i, add:["Lead with guidance from the national pediatric society and public-health agency, with age ranges.","Give the normal range for the child's age, not just the average.","List the red-flag signs that mean calling the doctor promptly.","For vaccines, explain why the schedule's timing was chosen and what evidence exists on spacing doses out.","Keep it calm and practical, ending with questions for the pediatrician."]},
  {id:"research:child-school-decision", kind:"research", when:/\b(held back|hold(ing)? (him|her|them|a kid|my \w+) back|repeat(ing)? (a|the) grade|grade retention|suggested retention|retention (meeting|decision)|tutors?|tutoring|iep|504 plan|special education|curriculums?|reading program|science of reading|balanced literacy|grades dropped)\b/i, add:["Use education research syntheses and evidence clearinghouses, not the program vendors' own studies.","Separate short-term from long-term outcomes, and say which students the studies covered.","List the data and questions to bring to the school before deciding.","For an IEP, compare written goals and service minutes with what progress reports show was delivered.","Note the parent's rights to meetings, evaluations, and written answers under special education law."]},
  {id:"research:choose-school-program", kind:"research", when:/\b(grad(uate)? (school|programs?)|master'?s (program|degree)|online masters?|mba|phd programs?|online (degree|universit\w+|programs?)|bootcamps?|accredit\w*|engineering schools?|which (college|school|university))\b/i, add:["Verify accreditation in the official accreditor database, and say which kind of accreditor it is.","Compare outcomes: graduation rate, job placement, median earnings, and typical debt.","Use net cost after aid, not sticker price.","For grad programs, add funding offers, advisor fit, time to degree, and placement records.","Flag diploma-mill signs, and how employers in the person's field view the credential."], ask:["What field and career goal is this for?"]},
  {id:"research:explain-simply", kind:"research", when:/\b(explain why|why (do|does|is|are|did)|how (does|do)|chemically|scientifically|actually explain|school (report|project)|homework|(\d+(st|nd|rd|th)|fifth|sixth|seventh) grade|my kids? asked?|kids ask|for (a|my|the) lesson)\b/i, unless:/\buploaded\b|\brulebook\b/i, add:["Explain the cause as a step-by-step chain in plain words, not a list of factors.","Use one concrete everyday comparison.","Correct the most common misconception about it.","For a student, give 3 to 5 key facts, each with a source a teacher would accept.","If the answer changes over time, include current data with its date."]},
  {id:"research:personal-finance-basics", kind:"research", when:/\b(529|roth|ira|401\(?k\)?|i ?bonds?|pension|annuity|lump sum|index funds?|refinanc\w*|mortgage|credit scores?|hard inquir\w*|stocks?|savings account|retirement savings|investment options)\b/i, unless:/\b(sector|market size|tam|seed|startup)\b/i, add:["Explain the rules from the official source, such as the tax agency, treasury, or regulator, with the year.","Give current rates or limits with an as-of date and where to check for updates.","Work one simple example with the person's own numbers, such as a break-even point.","Lay out tradeoffs in a table; for a single stock, use the company's filings, not forums.","Give general education, not advice, and suggest a fee-only fiduciary for the personal decision."]},
  {id:"research:taxes", kind:"research", when:/\b(tax(es|ed)?|irs|deductions?|deductible|write[- ]?offs?|home office|1099|w-?2)\b/i, add:["Cite the tax agency's own publications and the relevant rule, with the tax year.","Say what changed recently and which rules are federal versus state.","State the thresholds and tests plainly, then apply them to the person's situation.","For online sales, check each state's sales-tax threshold and marketplace-facilitator rules.","Flag the edge cases where a CPA or enrolled agent should confirm."]},
  {id:"research:tenant-landlord", kind:"research", when:/\b(landlords?|tenants?|rent (increase|raise|hike|control)|rental (units?|propert\w+)|evict\w*|security deposits?|late fee)\b|\braising (my |the )?rent\b/i, add:["Identify the jurisdiction first; rules differ by state, city, and building type.","Cite the statute or local ordinance, with any notice periods, caps, or exemptions.","Check the lease wording against what the law allows.","Point to the local housing agency, tenant groups, or legal aid to confirm.","Mark this as legal information, not legal advice."]},
  {id:"research:estate-planning", kind:"research", when:/\b(a will|my will|wills|living trusts?|power of attorney|living will|estate plan\w*|probate|advance directives?|health ?care proxy)\b/i, add:["Explain what each document does, when it takes effect, and when it stops.","Note the state's rules for signing, witnesses, and probate, and what happens without one.","Show which situations each covers: incapacity, death, health decisions, money.","Include rough costs and do-it-yourself versus attorney tradeoffs.","End with a checklist of decisions to make before meeting a lawyer."]},
  {id:"research:employment-law", kind:"research", when:/\b(unioni[sz]\w*|labor law\w*|labor posters?|workplace posters?|independent contractors?|contractor vs|misclassif\w*|overtime rules|wage and hour|legal obligations)\b/i, add:["Cite the federal labor agency's guidance, and note where state rules are stricter.","List what employers may and may not do, with concrete examples.","For contractor versus employee, walk through the federal and state tests factor by factor.","Give penalties and common mistakes, and when to consult an employment lawyer.","Present outcome evidence from both worker and employer sides where it applies."]},
  {id:"research:trademark-ip", kind:"research", when:/\b(trademarks?|cease and desist|c&d|patents?|copyright\w*|ip landscape|intellectual property)\b/i, add:["Check the official registry: owner, status, goods and services classes, filing and first-use dates.","Walk through likelihood-of-confusion factors: similar marks, related goods, sales channels, actual confusion.","Separate registered rights from common-law rights and their geographic limits.","For patents, separate granted patents from pending applications, and note expiry dates.","List questions for the IP lawyer; this is not legal advice."]},
  {id:"research:rules-permits-compliance", kind:"research", when:/\b(licen[cs]es?|permits?|cottage food|business registration|gdpr|compliance|regulatory (landscape|requirements)|regulations?|dispensary|llc|sole propriet\w*|cyber insurance)\b/i, unless:/\bdriver'?s licen\w*/i, add:["Map every layer: city, county, state, federal, with the agency that handles each.","List each requirement as a checklist item with its official source, fee, and processing time.","Note thresholds that change what applies: size, revenue, home-based, kind of data handled.","Cover inspections, renewals, liability exposure, and penalties for skipping steps.","Order the steps so nothing blocks a later one, such as zoning approval before signing a lease."]},
  {id:"research:market-competitor-research", kind:"research", when:/\b(competitors?|competitive (landscape|intel\w*)|competitor pricing|market (research|entry|size|sizing|landscape|positioning|assessment)|tam|due diligence|seed (round|investors?)|pitch\w* (seed )?investors|investment (sector|committee)|funding landscape)\b/i, unless:/\b(overseas|supplier|manufacturer)\b/i, add:["Define the market boundary and customer segment before sizing anything.","Build a competitor table: offer, pricing for like-for-like service, positioning, strengths, weaknesses, recent moves.","Source from filings, pricing pages, job posts, customer reviews, and trade or government data.","Size the market top-down and bottom-up, and label estimates versus sourced figures.","Close with risks, open questions, and what would change the conclusion."]},
  {id:"research:business-decision-evidence", kind:"research", when:/\b(makes? sense|worth it|actually (helps?|works?|pays?))\b[^.]{0,50}\b(business|shop|store|cafe|restaurant|agency|team|nonprofit)\b|\b(business|shop|store|cafe|restaurant|agency|team|nonprofit)\b[^.]{0,50}\b(makes? sense|worth it|actually (helps?|works?))\b|\b(start(ing)? a [\w ]{0,20}business|food truck|4[- ]day (work ?week)?|four[- ]day|remote work|value[- ]based pricing|subscription box\w*|second location|chatbot|performance review\w*|wellness app|worker cooperative|buy(ing)? out|crypto payments?|donor retention)\b/i, unless:/\buploaded\b/i, add:["Find evidence from organizations of similar size and sector, not only large-company studies.","Separate controlled trials from surveys, vendor case studies, and advocacy reports.","Lay out one-time and ongoing costs, the expected benefit, and the break-even point.","Name the main risks, how reversible the change is, and a small pilot to test it.","Include evidence against the hoped-for answer, not only support for it."]},
  {id:"research:service-plan-compare", kind:"research", when:/\b(phone plans?|cell(ular)? (plan|carrier)s?|internet (plans?|providers?)|credit card process\w*|payment process\w*|pos( systems?)?|point of sale|accounting software|fundraising platforms?)\b|\bswitch(ing)? (from|to|our|my)\b[^.]{0,40}\b(software|platforms?|systems?|providers?|plans?)\b/i, add:["Calculate total yearly cost at the person's real volume, including every fee and hardware cost.","Check contract length, early-termination fees, and price rises after promotions end.","Use reviews from users of the same size and type, not marketing pages.","Include switching costs: migration, downtime, retraining, lost data or history.","For phone plans, check coverage at the exact address using independent and crowdsourced maps."]},
  {id:"research:import-supply-chain", kind:"research", when:/\b(suppliers?|manufacturers?|factory|factories|tariffs?|import(ed|s)?|supply chain|rare earths?)\b/i, unless:/\buploaded\b|\bspec sheets?\b/i, add:["Verify the supplier's registration, ownership, audits, certifications, and trade references.","Screen against sanctions and forced-labor lists, and check labor-practice reports.","Use the official tariff schedule and product classification codes, with effective dates.","Model cost exposure under several scenarios by share of imported inputs.","Suggest risk reducers: sample orders, staged payments, inspections, a second source."]},
  {id:"research:grants-funders", kind:"research", when:/\b(funders?|grants?|grantmakers?|foundations? that fund)\b/i, unless:/\buploaded\b/i, add:["Use funder databases and funders' public tax filings to see who they actually funded, and how much.","Match on the geography, budget size, and program area of past grantees.","Give a table: funder, typical grant size, focus, deadline, eligibility, how to apply.","Flag invite-only funders and ones that rarely fund organizations of this size."]},
  {id:"research:travel-planning", kind:"research", when:/\b(trip|travel(l?ing)?|vacation|itinerary|flights?|hotels?)\b|\bbest (month|time|season) (of (the )?year )?to (visit|go)\b/i, add:["Give month-by-month weather from the national weather service: temperature, rain days, daylight.","Compare crowds and prices in peak, shoulder, and low seasons.","Check official government travel advice for entry rules, visas, and safety.","Note local holidays and events that change availability or prices."], ask:["What do you want to do there, and do you mind rain or crowds more?"]},
  {id:"research:relocate-abroad", kind:"research", when:/\b(retire|move|moving|relocat\w*)\b[^.]{0,40}\b(abroad|overseas|countr(y|ies))\b|\bexpats?\b|\bjob offer\b[^.]{0,40}\b(abroad|overseas|countr(y|ies))\b/i, add:["Compare visa or residency routes, income requirements, and processing times from official immigration sites.","Cover tax residency, tax treaties, and how pensions or foreign income are taxed.","Explain healthcare access for residents and when private insurance is needed.","Compare cost of living for the household's lifestyle, plus schooling and language.","Give a side-by-side table and the main deal-breakers for each option."]},
  {id:"research:public-policy-evidence", kind:"research", when:/\b(city council|town council|school board|ballot|referendum|public comment|ordinance|zoning (vote|hearing)|congestion pricing|minimum wage|rent control|fluoridation|highway|big box|affordable housing|policy brief|standardized testing|per[- ]pupil|universal basic income|ubi|debate|both sides|steelman|con side)\b/i, unless:/\b(watch(ing)?|live|tonight)\b[^.]{0,30}\bdebate\b/i, add:["Use before-and-after data from comparable places, not single anecdotes.","Rank evidence by design: peer-reviewed causal studies above advocacy or industry reports, noting funders.","Give the strongest evidence on each side, and where the research is still mixed.","Separate factual disagreements from disagreements about values.","Anticipate the top rebuttals to the person's position and how the evidence answers them."]},
  {id:"research:history-genealogy", kind:"research", when:/\b(historical (significance|society|records?|claims?|accuracy)|local history|town (history|records?|record book)|history (question|homework|class)|landmark\w*|news archives?|old newspapers?|clippings|deeds|1[5-9]\d0s|genealog\w*|family (tree|history)|ancestr\w*|great[- ]?(uncle|aunt|grand\w*)|adopt(ed|ion|ee)|biological (family|parents?|mother|father)|dna (test\w*|results)|ethnicity estimate)\b/i, unless:/\b(vehicle|credit|medical|price|browser) history\b/i, add:["Prefer primary sources: original records, contemporary newspapers, official registers, census and vital records.","Corroborate key claims with independent sources, and note when a claim first appears.","Mark each fact as documented, inferred, or family lore, with its source and date.","For adoptions, cover state rules on original birth certificates, consent registries, and DNA matching.","Explain that DNA ethnicity estimates change as reference panels update; relative matches are firmer evidence."]},
  {id:"research:literature-review", kind:"research", when:/\b(literature review|lit review|peer[- ]reviewed|systematic review|dissertation|thesis|annotated bibliography|journal articles?|academic sources|source evaluation|evaluat\w* (the )?sources)\b/i, add:["Search scholarly databases, and cite only sources you can name exactly.","For each source give its main claim, method, sample, and strength of evidence.","Map where findings agree, where they conflict, and where gaps remain.","Note recency, retractions, funding or bias, and whether key results were replicated.","Group sources by theme or question, not one summary after another."], avoid:["invented or unverifiable citations"]},
  {id:"research:journalism-investigation", kind:"research", when:/\b(journalists?|reporters?|investigative|freelanc\w* (journalist|for)|feature (story|piece|article)|magazine (piece|feature)|news (brief|piece|story)|foia|explainer|writing (a|an|my) (feature|article|story|piece))\b/i, add:["Separate confirmed facts from claims, and attribute each claim to who made it.","Prioritize primary documents: court filings, public records, regulatory filings, official data.","Date every fact, and note where the record is incomplete or disputed.","List who to contact for comment and what still needs confirming."], avoid:["press-release claims repeated as fact"]},
  {id:"research:fact-check-claim", kind:"research", when:/\b(is (it|that) (actually |really )?true|true that|myth|fact[- ]?check\w*|viral (claim|post)|health claim|rumou?rs?|hoax|debunk\w*|scary (posts?|headlines?)|even plausible|scam|recall(s|ed)?|truth about|whats (actually )?true|(real|actual) (answer|truth))\b|\bor (is )?(that|it|thats|this) (just |mostly )?(a )?(myth|marketing|hype|placebo|overblown|exaggerated|trend)\b/i, unless:/\brecall(ing)? from\b|\bfrom (memory|recall)\b/i, add:["Restate the exact claim, then trace it to its original source.","Check what major health, science, or fact-checking bodies have concluded.","Give a clear verdict: true, mostly true, misleading, or false, with the reason.","Explain the kernel of truth that keeps the claim alive, if there is one.","For recalls, check the regulator's official recall database by product, lot, and date."]},
  {id:"research:broad-topic-scope", kind:"research", when:/\b(everything about|entire (topic|history|landscape|space)|whole (topic|state)|absolutely everything|full research (dive|report)|research everything)\b/i, add:["Answer the narrowed question first, then add only context that supports it.","Break it into 3 to 5 sub-questions, and answer each with sources.","Say in one line which related topics were left for a follow-up."]},
  {id:"research:technical-evidence-brief", kind:"research", when:/\b(projections?|cost per|per megawatt|levelized|state of the (art|field)|current state of|catastrophe model\w*|pfas|sea level|error correction|energy density|regulatory approval|life ?cycle|environmental (impact|math)|carbon footprint)\b/i, add:["Cite authoritative assessments: intergovernmental reports, national labs, regulators, peer-reviewed reviews.","Give ranges with the scenario or assumptions behind each, and the publication date.","Separate lab or pilot results from performance proven at commercial scale.","For environmental comparisons, use life-cycle studies and state their boundaries and break-even point.","Put key numbers in a table with units and source."]},
  {id:"research:food-safety", kind:"research", when:/\b(food safety|safe to eat|sit out|left ?overs?|meal prep\w*|cooked rice|spoil\w*|refrigerat\w*)\b/i, add:["Use the national food safety agency's time and temperature limits.","Name the specific risk for that food, such as bacterial toxins that reheating does not destroy.","Give practical storage steps: how fast to cool, container depth, days in fridge or freezer.","Say who is at higher risk: young children, pregnant people, older adults."]},
  {id:"research:pets", kind:"research", when:/\b(dogs?|cats?|pupp(y|ies)|kittens?|pets?|vets?|veterinar\w*)\b/i, add:["Use veterinary schools, veterinary associations, and animal poison control sources.","Give toxic doses by body weight where relevant, and the symptoms to watch for.","State clearly when to call the vet or the poison line right away.","For pet insurance, compare exclusions, waiting periods, breed conditions, reimbursement, and premium rises with age."]},
  {id:"research:home-hazards", kind:"research", when:/\b(radon|mold|mould|gas stoves?|carbon monoxide|lead paint|asbestos|wasps?|hornets?|bottled water|tap water|water filt\w*|filtration|surge protect\w*)\b/i, add:["Use the national environmental or health agency's action levels and testing guidance.","Explain how to test, what the results mean, and the cost range.","Separate what is safe to do yourself from when to hire a licensed pro.","Add precautions for children, pets, and people with asthma or other conditions."]},
  {id:"research:home-garden-troubleshoot", kind:"research", when:/\b(winteriz\w*|reseal\w*|reroof\w*|gutters?|sprinklers?|oil changes?|change (my|the) oil|composting toilets?|septic|off[- ]grid|tire pressure|driveway|houseplants?|gardens?|gardening|tomato(es)?|grow lights?|lawn|no[- ]mow|sourdough|brew\w*|keeps? (dying|tasting|failing)|tastes? off|off flavou?r|smells? like|whats causing|why does my|dying)\b/i, unless:/\b(quotes|bids?)\b/i, add:["Use manufacturer specs, the local extension service, or trade guidance as sources.","Adjust for climate zone, season, and local frost dates where they matter.","For a problem, rank likely causes and give the sign that tells each apart.","Start with the cheapest, quickest checks, changing one thing at a time.","Say which signs mean calling a pro, with rough cost ranges."]},
  {id:"research:elder-care", kind:"research", when:/\b(assisted living|nursing homes?|memory care|senior (care|living)|medicare|medigap|open enrollment)\b/i, add:["Use state inspection reports, complaint records, and staffing data, not brochures.","List the fee structure: base rate, care-level charges, yearly increases, and discharge terms.","For Medicare choices, compare networks, out-of-pocket maximums, drug coverage, and switching rules.","Point to the free official counseling program for unbiased help.","Give questions to ask during an unannounced visit."]},
  {id:"research:grounded-doc-qa", kind:"research", when:/\b(uploaded|i upload\w*|my (notes|documents?|pdfs?|files|journal entries)|these (pdfs?|documents?|reports?|transcripts?|emails?|letters)|meeting minutes|only (from|answers? from|using) what|internal documents|knowledge base)\b/i, add:["Answer only from the uploaded sources, and say clearly when something is not in them.","Cite the document and page or section for every claim.","Quote exactly inside quotation marks; never mix paraphrase into a quote.","Flag where sources conflict instead of silently picking one."], avoid:["outside knowledge presented as if it came from the sources"]},
  {id:"research:doc-and-quote-compare", kind:"research", when:/\b(contradict\w* (each other|one another|themselves|the old|anywhere)|what (actually )?changed|(are|is) [\w ]{0,20}(consistent|comparable)|side by side|do they (all )?(agree|match)|same \w+ (fee )?clause)\b|\b(quotes|bids?)\b[^.]{0,60}\b(roof\w*|remodel|contractor|kitchen|hvac|plumb\w*)|\b(roof\w*|remodel|contractor|kitchen)\w*\b[^.]{0,60}\b(quotes|bids?)\b/i, add:["Build a side-by-side table per item or clause, with page references for each document.","Normalize scope, units, and dates before comparing numbers or prices.","List what appears in one document but not the others, such as exclusions or allowances.","Mark each difference as substantive or wording only.","For bids, compare payment schedule, timeline, warranty, and what to ask each bidder."]},
  {id:"research:pull-quotes", kind:"research", when:/\b(pull quotes?|key quotes?|good quotes?|quotes? (from|about)|interview transcripts?|oral history)\b/i, add:["Quote word for word, with the speaker and the timestamp or page.","Keep enough context that the meaning is not changed, and never splice sentences.","Balance quotes across speakers and viewpoints.","Flag unclear or likely mis-transcribed passages."]},
  {id:"research:timeline-extract", kind:"research", when:/\b(the (actual |real |clean )?timeline|a (clean |simple )?timeline|timeline of|sequence of events|chronolog\w*)\b/i, add:["One row per event: date, what happened, source and page.","Mark approximate or inferred dates, and say what they were inferred from.","Flag dates that conflict between sources.","Keep it strictly chronological, with no commentary unless asked."]},
  {id:"research:study-aid", kind:"research", when:/\b(study (sheet|guide|group)|flashcards?|exams?|test (on )?(friday|tomorrow|monday)|quiz|practice exam|lectures?|textbook|modules)\b/i, add:["Use only the course material provided, organized in the course's own order.","For each concept give a definition, one example, and a common mistake.","Mark topics the practice exam stresses and topics the notes skip.","Keep flashcards to one fact per card, with the question on the front."]},
  {id:"research:financial-docs", kind:"research", when:/\b(uploaded|my|our)\b[^.]{0,60}\b(p&l|statements|sales (reports?|data)|budgets|invoices|expenses|pos (data|exports?)|quickbooks|reimbursement|job cost|reserve stud(y|ies))\b/i, add:["Show each calculation with the figures used and the page they came from.","Give totals and percent change by period, and describe the trend.","Separate one-time items from recurring ones.","Note missing months or inconsistent categories before drawing conclusions."]},
  {id:"research:format-copy", kind:"research", when:/\b(that|this|same|house|similar|that same) (style|format|structure|shape|layout)\b|\b(style|format|structure|layout) (like|of|for|up top|approach)\b|\b\w+[- ]style\b|\b(one[- ]pager|handout|worksheet|columns|nothing else|in that order)\b|\b(always|like|notes like):/i, add:["Follow the exact structure the person describes, section by section, in that order.","Match the described length of each section, and add no extra sections.","Keep every fact sourced even when the format is short."]},
  {id:"research:exec-brief", kind:"research", when:/\b(exec(utive)? summary|exec summaries|board (memo|meeting|retreat|presentation|vote)|leadership presentation|presentation (to|for) leadership|briefing for|decision memo|investor memo)\b/i, add:["Open with the bottom line and 3 key takeaways.","Give the decision options with their tradeoffs.","Put supporting data and sources after the summary.","Flag the biggest uncertainty and what would resolve it."]},
  {id:"sound:sfx-ui-click", kind:"sound", for:"sfx", when:/\b(?:click|tap|pop)(?: sound| noise|s)?\b[\s\S]*\b(?:button|app|ui|interface|menu)\b|\b(?:button|ui|interface|menu)\b[\s\S]*\b(?:click|tap|press|pop)|\b(?:click|tap) sound/i, unless:/\bno clicks?\b/i, add:["very short, a fraction of a second, with a crisp attack and fast decay","soft rounded mid-high tone, no low rumble and no reverb tail","dry and isolated, silence before and after","gentle enough to hear hundreds of times without fatigue"], avoid:["music","harsh high-frequency snap","long tail"], ask:["Should it feel soft and calm, or crisp and snappy?"]},
  {id:"sound:sfx-notification-chime", kind:"sound", for:"sfx", when:/\b(?:notification|ding|chimes?|alert tone|message tone)\b|\bconnect(?:ed|s|ing)?\b[\s\S]*\bsound|\bplug(?:ged)? in\b/i, unless:/\b(?:crowd|cheer\w*|applause|whoosh|riser|puzzle|secret|level[- ]up|power[- ]?up)\b/i, add:["two or three soft notes rising in pitch, rounded bell or marimba tone","short smooth decay under a second, clean silence after","gentle attack in a mid-high register that reads clearly on small phone speakers","isolated sound only, no music bed"], avoid:["harsh buzzer tone","long reverb tail"], ask:["What should it signal: good news, a reminder, or a problem?"]},
  {id:"sound:sfx-glitch-error", kind:"sound", for:"sfx", when:/\bglitch|\berror (?:sound|beep|noise|message)|\bmalfunction|\bcorrupt|\bcomputer breaks/i, unless:/\b(?:drone|ambien\w*|bed|loop\w*|background)\b/i, add:["rapid stuttering repeats and chopped fragments with abrupt pitch jumps","sudden dropouts and a hard cutoff at the end","dry, under two seconds, isolated with silence around it"], avoid:["music","long ambient tail"], ask:["Should it feel cold and digital, funny, or organic and unsettling?"]},
  {id:"sound:sfx-game-pickup", kind:"sound", for:"sfx", when:/\b(?:coins?|gems?|collectibles?|pick-?ups?|pick up|collect(?:s|ing|ed)?)\b/i, unless:/\bpower[- ]?up|\blevel[- ]up/i, add:["bright quick two-note blip, the second note higher","crisp attack, under half a second, a tiny sparkle on the tail","high-mid register that cuts through game music","dry and clean so it can repeat constantly without fatigue"], avoid:["low bass","long reverb"], ask:["Retro 8-bit style, or a modern polished sound?"]},
  {id:"sound:sfx-level-up-win", kind:"sound", for:"sfx", when:/\blevel[- ](?:up|complete|cleared|finished)|\b(?:win|won|beat|clear)(?: a| the)? level|\bpower[- ]?up|\bachievement|\bvictory|\bunlock(?:ed)?\b|\bsolv(?:e|ed|ing)? (?:a |the )?puzzle|\bfind (?:a |the )?secret|\breward(?:ing)? sound/i, unless:/\bcrowd|\bcheer/i, add:["quick rising arpeggio resolving on a bright major chord","sparkling shimmer on the final note with a short tail","one to two seconds, punchy start, celebratory and clean","isolated sound, not a full music track"], avoid:["minor or sad notes","long fanfare"], ask:["Retro chiptune style, or a modern orchestral or synth sound?"]},
  {id:"sound:sfx-game-jump", kind:"sound", for:"sfx", when:/\bjump(?:s|ing)?\b/i, unless:/jump ?scare|jump cut/i, add:["short upward pitch sweep, a springy boing or soft blip","under half a second, light and airy, no heavy low end","soft enough to repeat constantly without annoying the player"], avoid:["music","long tail"], ask:["Cartoony and bouncy, or subtle and realistic?"]},
  {id:"sound:sfx-combat-hit", kind:"sound", for:"sfx", when:/\b(?:swords?|blades?|punch(?:es)?|slash\w*|melee|finishing move|fighting game|clash\w*|uppercut)\b|\b(?:hits?|defeats?) an? enemy/i, unless:/^(?![\s\S]*\bnot\b[\s\S]{0,25}\bcartoon)[\s\S]*\b(?:cartoon\w*|silly|funny|goofy)\b/i, add:["layered impact: sharp transient, meaty low-mid thump, short tail","metallic ring and scrape for blade contact, dull thud and cloth snap for body blows","tight and dry, under a second, no music","a few variations with slightly different pitch and texture"], avoid:["cartoon bonk sounds","long reverb tail"], ask:["What hits what (sword on armor, fist on body), and how heavy should it feel?"]},
  {id:"sound:sfx-cartoon-comedy", kind:"sound", for:"sfx", when:/\b(?:cartoon\w*|boing|silly|goofy|funny|comical|pratfall|slapstick|oops|wacky|prank)\b/i, unless:/\b(?:glitch\w*|error|whoosh|swoosh|sting(?:er)?|hit|impact|crash|shatter|breaking|braam)\b/i, add:["exaggerated cartoon gesture: slide-whistle drop, springy boing, or bouncy descending wah-wah tone","short, dry and close, one clear comic shape","playful and harmless, no realistic pain or violence"], avoid:["harsh buzzer","realistic injury sounds"], ask:["What happens on screen at that exact moment?"]},
  {id:"sound:sfx-healing-spell", kind:"sound", for:"sfx", when:/\bheal(?:ing|er|s)?\b|\brestor(?:e|ation)\b|\bblessing\b/i, add:["soft rising harp-like glissando with glassy chimes","warm airy pad that swells and gently fades, major tonality","no harsh transients and no low rumble","one to three seconds with a sparkling tail"], avoid:["dark or dissonant tones","explosive impact"]},
  {id:"sound:sfx-magic-spell", kind:"sound", for:"sfx", when:/\b(?:spells?|magic(?:al)?|wizard|sorcer\w*|enchant\w*|fireball|mana)\b/i, unless:/\bheal(?:ing|er|s)?\b|\brestor(?:e|ation)\b|\bsparkl\w*|\bshimmer\w*|\btransition|\bwedding/i, add:["a short charge-up swell followed by a punchy release burst","layered whoosh, crackling energy and a tonal shimmer","one to three seconds, tail fading out cleanly"], avoid:["music"], ask:["What kind of spell is it (fire, ice, lightning, arcane, a hidden door opening)?"]},
  {id:"sound:sfx-whoosh", kind:"sound", for:"sfx", when:/\b(?:whoosh\w*|swoosh\w*|woosh\w*|swish\w*)\b|\btransition (?:sound|sfx|effect)/i, unless:/\bsparkl|\bshimmer|\bmagic/i, add:["fast air swish that swells and falls away, peaking in the middle","short and clean, under a second, with a soft fade in and out","stereo movement from one side to the other","no music and no tonal melody"], avoid:["harsh hiss","long reverb wash"], ask:["Subtle and quick, or a big cinematic sweep?"]},
  {id:"sound:sfx-sparkle-transition", kind:"sound", for:"sfx", when:/\bsparkl\w*|\bshimmer\w*|\btwinkl\w*|\bglitter|\bfairy dust|\bmagical whoosh/i, add:["soft airy whoosh carrying high twinkling chimes and bell tones","gentle attack with no hard hit, a fading shimmer tail","about one to two seconds, light and delicate"], avoid:["heavy low impact","harsh metallic ring"]},
  {id:"sound:sfx-riser", kind:"sound", for:"sfx", when:/\briser|\buplifter|\bbuild[- ]?up|\bbuilding tension|\btension build|\bbuilds? (?:up )?(?:tension|before|for)|\bbefore (?:my|the|a) (?:drop|reveal)/i, add:["steady rise in pitch, volume and density toward a single peak","noise sweep layered with a rising tone and a tightening pulse","ends right at its peak with a hard cut, ready for the hit or reveal","no melody"], avoid:["peaking too early","fading out at the end"], ask:["How long should it build, and does it end on a hit or cut to silence?"]},
  {id:"sound:sfx-stinger", kind:"sound", for:"sfx", when:/\bsting(?:er)?s?\b/i, unless:/\bnot (?:a |any )?(?:music )?sting/i, add:["one short gesture, one to three seconds, accent at the very start","a single hit or chord stab with a quick decaying tail","ends cleanly so speech or the next scene can follow"], avoid:["long build-up","a melody that keeps going"], ask:["Should it feel dramatic, funny, or menacing?"]},
  {id:"sound:sfx-braam", kind:"sound", for:"sfx", when:/\bbra+m+|\bbwa+h*m|\bhorn (?:hit|blast|blare)s?|\bdeep horns?\b/i, unless:/\bfog ?horn|\bship/i, add:["massive low brass blast layered with distorted synth and detuned tones","swelling attack, held two to four seconds, long hall reverb tail","deep sub-bass rumble under the brass","one sustained chord, no melody"], avoid:["music bed","thin or bright tone"], ask:["Dark and threatening, or triumphant and grand?"]},
  {id:"sound:sfx-trailer-impact", kind:"sound", for:"sfx", when:/\b(?:boom|impact|big hit|cinematic hit|dramatic hit|explosions?|explode|kaboom|pow)\b/i, unless:/\b(?:doors?|punch\w*|swords?|braam|predat\w*|nature)\b/i, add:["sharp transient crack layered over a deep sub-bass boom","rumbling tail decaying over a few seconds in a large space","layered low drum, metal and debris textures, no music"], avoid:["thin, small-room sound","music"], ask:["Should it end clean, or ring out with a long tail under the title?"]},
  {id:"sound:sfx-horror-ambience", kind:"sound", for:"sfx", when:/^(?=[\s\S]*\b(?:drones?|hum|ambien\w*|atmospher\w*|background|beds?|soundscape|room tone|loop\w*))(?=[\s\S]*\b(?:scary|creepy|horror|eerie|haunt\w*|dread|unsettl\w*|spooky|ominous|asylum|sinister|silent hill))/i, unless:/\b(?:not|never|without|nothing)\s+(?:too\s+|that\s+|anything\s+)?(?:eerie|scary|creepy|unsettl\w*|spooky|horror|tense)/i, add:["low sustained drone with slow beating between detuned tones","distant metallic creaks and faint indistinct movement at long, irregular intervals","cold room tone and air, no melody","slow swells in intensity over a minute or more, no sudden loud hits"], avoid:["jump-scare hits","screams","music"], ask:["Does it loop under gameplay, and for how long?"]},
  {id:"sound:sfx-jumpscare", kind:"sound", for:"sfx", when:/jump ?scare/i, unless:/\b(?:not|no|never)\b[\s\S]{0,12}jump ?scare/i, add:["sudden full-force dissonant burst: screeching strings and metal scrape over a low hit","instant attack out of near silence, under two seconds","fast decay back into silence"], avoid:["slow build before the hit","screaming voice"]},
  {id:"sound:sfx-rain", kind:"sound", for:"sfx", when:/\brain(?:fall|drops?|storm|y)?\b|\bdrizzle|\bdownpour/i, add:["steady even rainfall, soft broadband hiss with gentle droplet detail","consistent level with no sudden loud events","warm, slightly muffled tone without harsh high hiss","seamless loop with no audible seam"], avoid:["music","sharp thunder cracks"], ask:["Rain on a roof, on a window, or in a forest?"]},
  {id:"sound:sfx-thunder", kind:"sound", for:"sfx", when:/\bthunder\w*/i, unless:/\b(?:sleep\w*|relax\w*|calm\w*)\b/i, add:["sharp close crack splitting into a long rolling rumble","deep low end decaying over several seconds","natural outdoor space with echoes off distant terrain"], avoid:["music","explosion sound"], ask:["Close and violent, or distant and rolling?"]},
  {id:"sound:sfx-forest-ambience", kind:"sound", for:"sfx", when:/\b(?:forest|woods|woodland|jungle|camping|campsite|birdsong|birds chirping|nature sounds)\b/i, unless:/\b(?:scary|creepy|horror|eerie|haunt\w*)\b/i, add:["soft wind moving through leaves, sparse distant birdsong","occasional far-off creek trickle and faint insect hum","steady calm level, no close loud bird calls or sudden events","seamless loop"], avoid:["music","animal cries"]},
  {id:"sound:sfx-wind", kind:"sound", for:"sfx", when:/\bwind\b|\bhowl(?:ing)?\b|\bgusts?\b|\bblizzard/i, unless:/wind ?chimes?/i, add:["steady broadband wind with slow gusts rising and falling","low rumble on the gusts, airy whistle at the peaks","no music, no animal or voice sounds","seamless loop"], ask:["A gentle breeze, or harsh howling exposure?"]},
  {id:"sound:sfx-room-ambience", kind:"sound", for:"sfx", when:/^(?=[\s\S]*\b(?:coffee ?shop|caf[eé]|bakery|restaurant|bar|pub|diner|market|bazaar|office|lobby|kitchen|classroom|library|mall)\b)(?=[\s\S]*\b(?:ambien\w*|background|noise|sounds|atmosphere|bed|walla)\b)/i, unless:/\b(?:typing|keyboard|footsteps?|doors?)\b/i, add:["indistinct murmured chatter with no intelligible words","soft room details like cups, footsteps and doors, spaced far apart","steady density, no single loud event standing out","seamless loop"], avoid:["music","clear words or names"], ask:["How busy should it be: a few people, or a packed room?"]},
  {id:"sound:sfx-crowd", kind:"sound", for:"sfx", when:/\b(?:crowd|cheer(?:s|ing)?|applause|applaud\w*|clapping|stadium)\b/i, unless:/\bwalla|\bmurmur/i, add:["large live crowd: dense clapping, whoops and whistles","natural swell to a peak, then a gradual fade","reflections that match the venue, indoor hall or open stadium","no announcer, no music"], avoid:["canned laugh track"], ask:["How big is the crowd, a school hall or a stadium?"]},
  {id:"sound:sfx-footsteps", kind:"sound", for:"sfx", when:/\bfoot ?steps?\b|\bfootfalls?\b|\b(?:walking|running|steps?) (?:on|across|through|down|up)\b|\bfloorboards?\b|\bcreak\w*|\bwalk(?:ing)? sounds?/i, add:["close-mic steps with distinct heel and toe contact","the surface texture and footwear clearly audible on every step","natural uneven pacing with slight variation between steps","dry, no music"], avoid:["identical repeated steps"], ask:["What surface and footwear, and walking or running?"]},
  {id:"sound:sfx-door", kind:"sound", for:"sfx", when:/\bdoors?\b/i, unless:/\bmagic|\bsecret/i, add:["solid contact thud with latch click and handle rattle","short natural decay with reflections matching the room","isolated, no music"], ask:["What kind of door (wood, metal, car), and how hard is it opened or closed?"]},
  {id:"sound:sfx-breakage", kind:"sound", for:"sfx", when:/\b(?:shatter\w*|smash\w*|crash|breaking|breaks)\b/i, unless:/\b(?:computer|glitch\w*|error|waves?|news)\b|\bad breaks?\b|\bbreaking in\b/i, add:["sharp initial crack followed by bright scattering fragments","debris pieces settling over a second or two","close, dry and realistic, no music"], ask:["What breaks (glass, wood, ceramic), and how big is it?"]},
  {id:"sound:sfx-scifi-hum", kind:"sound", for:"sfx", when:/^(?=[\s\S]*\b(?:industrial|factory|machinery|space ?station|spaceship|starship|spacey|engine room|reactor|server room|cyberpunk|sci-?fi|hacking)\b)(?=[\s\S]*\b(?:drones?|hum|ambien\w*|loop\w*|beds?|background|soundscape))/i, unless:/\briser|\bgroan|\bcrush\w*|\bglitch sound/i, add:["low steady machinery hum with layered rhythmic mechanical pulses","distant vent hiss and occasional soft metallic clanks","no event loud enough to give away the loop point","no melody"], avoid:["music","alarms"]},
  {id:"sound:sfx-seamless-loop", kind:"sound", for:"sfx", when:/\bloop\w*|\bseamless\w*|\bfor hours\b|\ball (?:day|night)\b|\bcontinuous\w*|\bon repeat\b/i, add:["steady, even texture from start to finish","no standout one-off events that reveal the repeat","same level and tone at the start and end so the seam is invisible"], avoid:["fade in or fade out","sudden loud events"]},
  {id:"sound:sfx-respectful-ambience", kind:"sound", for:"sfx", when:/\b(?:memorial|grief|griev\w*|mourn\w*|funeral|famine|genocide|tragedy|bereave\w*|loss)\b/i, unless:/\bbra+m|\bsting|\bone-shot|\bflatline|\bbells?\b/i, add:["restrained, sparse and quiet, with plenty of space and silence","soft sustained tones with long gentle decay, low to mid register","no dissonant stabs, horror textures or dramatic hits"], avoid:["eerie or unsettling textures","melodramatic swells"]},
  {id:"sound:sfx-typing", kind:"sound", for:"sfx", when:/\btyping\b|\bkeyboard\b|\btypewriter\b/i, add:["close-mic mechanical key clicks with an uneven, natural human rhythm","occasional heavier spacebar thump and short pauses between bursts","dry room sound, no music"], avoid:["perfectly even machine-gun rhythm"], ask:["Mechanical clicky keyboard, quiet laptop keys, or an old typewriter?"]},
  {id:"sound:sfx-retro-analog", kind:"sound", for:"sfx", when:/\b(?:static|dial[- ]?up|modem|projector|film reel|countdown reel|vhs|cassette|tape hiss|vinyl crackle|old cinema)\b/i, add:["authentic analog character: narrow midrange band, tape hiss, slight wow and flutter","the mechanical detail of the period device rather than a modern digital imitation","dry and isolated, no music"], avoid:["clean modern digital sound"]},
  {id:"sound:sfx-medical-monitor", kind:"sound", for:"sfx", when:/heart monitor|\bflatline|\be[ck]g\b|\bhospital|\blife support/i, add:["clean sine-like monitor beep at a steady pulse rhythm","small, slightly boxy device speaker in a quiet room","a flatline as one continuous, unchanging tone"], avoid:["music","melodramatic swells"]},
  {id:"sound:sfx-reverberant-space", kind:"sound", for:"sfx", when:/\b(?:cathedral|chapel|bathroom|tiled|stairwell|cave|tunnel|canyon|echo\w*)\b/i, add:["long natural reverb tail matching the size and hard surfaces of the space","early reflections clearly audible, source at a believable distance","quiet background room tone between sounds"], avoid:["dry close-mic sound","artificial plate reverb"]},
  {id:"sound:music-study-focus", kind:"sound", for:"music", when:/\b(?:study(?:ing)?|studies|homework|concentrat\w*|lo-?fi|productivity|deep focus)\b|\bfocus (?:app|music|timer|session|playlist|track)/i, unless:/\bcase study/i, add:["mellow piano or electric piano chords over dusty, softly swung drums","slow relaxed tempo with gentle vinyl crackle and tape warmth","no vocals and no lead melody that pulls attention","steady energy with no drops, builds or sudden changes"], avoid:["vocals","sudden changes"], ask:["Lo-fi beats, or beatless ambient?"]},
  {id:"sound:music-voiceover-bed", kind:"sound", for:"music", when:/\b(?:voice-?over|narrat\w*|explainer|e-?learning|onboarding|compliance|training video|tutorial|product (?:video|demo))\b|\bunder (?:the )?(?:host|speech|talking|dialogue)/i, unless:/\b(?:jingle|song|lyrics|sing\w*)\b/i, add:["sparse arrangement with an open mid-range so speech stays clear","steady moderate tempo with no sudden hits, drops or swells","soft pads with a light plucked or piano motif, no vocals","even dynamics so it can sit low under a voice"], avoid:["busy lead melody","vocals"], ask:["Does someone talk over the whole piece, or only parts of it?"]},
  {id:"sound:music-show-intro", kind:"sound", for:"music", when:/\b(?:intro|outro|opening (?:title|theme|music)|signature (?:hook|sound|tune)|theme (?:music|tune))\b/i, unless:/\b(?:lyrics|vocals?|sing(?:ing|s)?|song|boss|battle)\b/i, add:["a short recognizable motif stated within the first two seconds","a confident opening hit, then a settle to a low bed or a clean ending button","the same signature instruments and key so it stays recognizable every episode"], avoid:["long slow fade-in"], ask:["How many seconds should it run, and does the host start talking over it?"]},
  {id:"sound:music-name-jingle", kind:"sound", for:"music", when:/\bjingle|\bstation id|\bcall letters|\busername|\bnam(?:e|es|ed|ing)\b/i, unless:/\bplanets|\bnames? of (?:all|the)|\bbed\b|no idea what to call/i, add:["a short hook of a few words built around the name, sung on strong downbeats","the name sung slowly and clearly on the longest note of the hook","the hook repeated at the end, finishing on a clean button","bright, simple melody easy to remember after one listen"], avoid:["name buried in a fast verse","long instrumental intro"], ask:["How exactly is the name pronounced?","How many seconds is the spot?"]},
  {id:"sound:music-timed-hit", kind:"sound", for:"music", when:/\bat\s+(?:about\s+|around\s+|exactly\s+|roughly\s+)?\d+(?:\.\d+)?\s?(?:s|sec|secs|seconds?)\b|\b\d+\s?(?:s|sec|secs|seconds?) in\b|\bminute mark\b|\b(?:reveal|payoff|hero shot|tagline|takeoff|key change|near-miss|big hit)\b|\b(?:drop|hit|swell|lift)\b[\s\S]{0,25}\b(?:when|right|exactly|for the)\b|\bbuild(?:s|ing)? (?:to|toward|towards|into)\b|\bbefore the (?:final|big|huge)\b/i, add:["a steady build in energy and density toward the marked moment","a short breath of near-silence or a held note just before it","a full-band accent hit with a low impact landing exactly on the moment","a fuller, bigger arrangement after the hit, carrying to the end"], avoid:["peaking before the moment"], ask:["At what second does the moment land, and how long is the whole piece?"]},
  {id:"sound:music-trailer-epic", kind:"sound", for:"music", when:/\b(?:trailer|epic|blockbuster)\b|\bhero (?:moment|reveal)/i, unless:/\b(?:bra+m|boss|pep rally|workout|gym|phonk|techno|synthwave|80s|rap|trap|edm)\b|\b(?:avoid|no|not|exclude\w*)\s+(?:any\s+|anything\s+(?:like\s+)?)?(?:movie\s+)?trailer/i, add:["three-stage build: sparse low pulse, rising string ostinato and percussion, full climax","deep brass hits and large taiko-style drums on the big accents","a brief silence before the final hit, then a long ringing tail","huge hall reverb and wide stereo"], avoid:["pop song structure","thin synth strings"], ask:["How long is the trailer, and when is its biggest moment?"]},
  {id:"sound:music-epic-choir", kind:"sound", for:"music", when:/\b(?:choir|choral|chant\w*|wordless)\b/i, unless:/\b(?:gospel|church|easter|sermon|pep|team|soccer|football|basketball|sports?|rally|esports|fans|call and response)\b/i, add:["large choir singing wordless or Latin-style syllables, no recognizable lyrics","low male voices chanting in unison, sopranos soaring in at the climax","big hall reverb with orchestral strings and low drums driving underneath"], avoid:["modern pop vocals","electronic drums"], ask:["When should the choir enter, and where is the peak?"]},
  {id:"sound:music-gospel", kind:"sound", for:"music", when:/\b(?:gospel|church|easter|sermon|worship|praise|hymns?|congregation|choir director)\b/i, unless:/\b(?:youth group|preachy|not religious)\b/i, add:["warm Hammond organ and piano with rich soulful chords","builds from a single voice or instrument to full choir with handclaps","final section lifts with a key change up a step"], avoid:["thin synth organ"], ask:["With singing, or instrumental only?"]},
  {id:"sound:music-wedding-ceremony", kind:"sound", for:"music", when:/\b(?:processional|recessional|ceremony|aisle|walks? down|guests (?:are )?seated)\b|\bbride(?:'s)? (?:entrance|enters|walk)/i, unless:/\b(?:closing ceremony|trophy ceremony|awards?)\b/i, add:["warm major key, string quartet or piano with soft strings","even, unhurried walking pulse with no drums","a fuller lift with added strings for the bride's entrance","an ending that can hold or fade naturally when the walk is done"], avoid:["the standard bridal chorus melody","big drums"], ask:["When does the bride enter, in seconds from the start?"]},
  {id:"sound:music-love-song", kind:"sound", for:"music", when:/\b(?:first dance|vows?|vow renewal|propos(?:al|e|ing)|love song|romantic|anniversary|engaged|engagement|father[- ]daughter|duet)\b|\bwedding (?:song|duet|slideshow|montage|video)/i, unless:/\b(?:brewery|church|company|business|startup|store|restaurant)\b/i, add:["slow to mid tempo, warm piano or acoustic guitar with soft strings","a gentle opening that grows into a fuller final section","intimate close sound, sincere rather than grand","lyrics, if sung, built on the couple's own story instead of love cliches"], avoid:["cheesy love cliches","overblown power ballad"], ask:["Sung or instrumental, and which personal details (how you met, a shared moment) should it include?"]},
  {id:"sound:music-wedding-reception", kind:"sound", for:"music", when:/\b(?:dance ?floor|bachelorette|bachelor party|wedding dance|reception (?:dance|party|playlist|opener|song))\b/i, add:["upbeat groove around 120 BPM with four-on-the-floor kick and handclaps","bright brass stabs and a big singalong chorus","a breakdown to drums and voice before the last chorus"], avoid:["slow ballad sections"], ask:["Which names should be shouted out or sung?"]},
  {id:"sound:music-birthday-song", kind:"sound", for:"music", when:/\b(?:birthday|bday|b-day)\b|\bturning \d+/i, unless:/\b(?:circus|clown|calliope|instrumental)\b|\bno (?:vocals|words|lyrics|singing)\b/i, add:["the person's name sung clearly and repeated in a short chorus everyone can join","two or three personal details about them woven into the verses","bright upbeat party groove with handclaps and a big final chorus"], avoid:["generic lyrics that could fit anyone"], ask:["What's their name, the age they're turning, and a few things they love?"]},
  {id:"sound:music-kids-song", kind:"sound", for:"music", when:/^(?=[\s\S]*\b(?:kids?|child(?:ren)?(?:'s)?|preschool\w*|toddlers?|nursery|classroom|my class|\d+(?:st|nd|rd|th) grade)\b)(?=[\s\S]*\b(?:song|sing\w*|lyrics|vocal|theme song)\b)/i, add:["simple melody in a narrow, comfortable range children can sing","short repeating chorus with clear, slowly sung words","bright playful instruments: ukulele, glockenspiel, handclaps","no scary sounds or sudden loud hits"], avoid:["complex wordplay","fast rapid-fire lyrics"], ask:["How old are the kids?"]},
  {id:"sound:music-kids-background", kind:"sound", for:"music", when:/\b(?:kids?|child(?:ren)?(?:'s)?|preschool\w*|toddlers?|bab(?:y|ies))\b/i, unless:/\b(?:song|sing\w*|lyrics|vocals?|ballet|recital|dance studio)\b/i, add:["gentle, even dynamics with no sudden loud hits or scary low tones","bright major key with a light, friendly melody","small variations over time so long play does not grate"], avoid:["dark minor passages","harsh high squeals"]},
  {id:"sound:music-memorial", kind:"sound", for:"music", when:/\b(?:funeral|memorial|tribute|in memory|passed away|losing|grief|griev\w*|eulogy|celebration of life)\b|\blost (?:my|our)\b/i, unless:/\b(?:retire\w*|graduat\w*)\b/i, add:["slow tempo, solo piano or soft strings with space between phrases","warm, mostly major harmony with touches of minor: peaceful rather than despairing","restrained dynamics, no drums or big dramatic swells","a quiet, resolved ending"], avoid:["melodramatic swells","horror-like dissonance"], ask:["Should it have singing, and if so, what should the lyrics remember about them?"]},
  {id:"sound:music-tribute-song", kind:"sound", for:"music", when:/\b(?:retire\w*|farewell|moving away|going away|years at|reunion|milestone|100th)\b|\b(?:brewery|company|business|store|restaurant|club|school)(?:'s)?[\s\S]{0,20}anniversary/i, unless:/\bretirement (?:community|home|village)|\bsenior living/i, add:["lyrics built on specific habits, achievements and inside jokes","warm mid-tempo groove, proud and celebratory rather than sad","a big singalong final chorus the whole room can join"], avoid:["generic lyrics that could fit anyone","sad farewell tone"], ask:["Which specific details (years, habits, inside jokes) should the lyrics include?"]},
  {id:"sound:music-funny-song", kind:"sound", for:"music", when:/^(?=[\s\S]*\b(?:funny|joke|meme|silly|parody|diss|goofy|comedy|ridiculous|absurd|roast|for fun)\b)(?=[\s\S]*\b(?:song|rap|lyrics|track|anthem|sing\w*|vocal)\b)/i, unless:/\binstrumental\b|\bno (?:vocals|lyrics|words)\b/i, add:["concrete, specific details in the lyrics with a punchline landing in each verse","a catchy chorus that repeats the central joke","earnest, committed vocal delivery played straight for comic contrast","teasing but affectionate, never cruel"], avoid:["vague jokes","insults that sound genuinely mean"], ask:["Which inside jokes or specific details should it mention?"]},
  {id:"sound:music-sports-chant", kind:"sound", for:"music", when:/^(?=[\s\S]*\b(?:chant\w*|call and response|yell back|hype))(?=[\s\S]*\b(?:team|sports?|soccer|football|basketball|baseball|hockey|league|esports|stadium|game day|championship|fans|mascot)\b)/i, add:["stomping drums and handclaps on a heavy, simple beat","a short shouted phrase repeated, easy for a crowd to yell back","call-and-response between a lead voice and the group","clean, family-friendly lyrics"], avoid:["long verses","complex melody"], ask:["What name or phrase should the crowd chant?"]},
  {id:"sound:music-pep-rally", kind:"sound", for:"music", when:/\b(?:pep rally|pep band|marching band|drumline|homecoming)\b/i, add:["marching snare and bass drum cadence with crashing cymbals","bold brass melody with stabs on the accents","fast march tempo, loud and bright from start to finish"], avoid:["slow or quiet sections"]},
  {id:"sound:music-workout", kind:"sound", for:"music", when:/\b(?:gym|workout|work out|hiit|fitness|lifting|personal record|cardio|spin class|crossfit|exercise)\b|\bpr\b/i, add:["fast tempo around 128 to 150 BPM with a punchy kick and heavy bass","relentless energy, no slow breakdowns","a hard drop on the most intense moment"], avoid:["long ambient intro","soft ballad sections"], ask:["What genre do you train to (techno, rap, rock, EDM)?"]},
  {id:"sound:music-techno-dj", kind:"sound", for:"music", when:/\btechno\b|\brave\b|\bwarehouse\b|\bdj set\b/i, unless:/\b(?:puzzle|app|game|gym|fitness|hiit|workout)\b/i, add:["four-on-the-floor kick around 130 BPM with rumbling, distorted sub bass","hypnotic repeating synth stabs and metallic industrial percussion","long drums-only intro and outro for mixing","no vocals"], avoid:["pop melodies","big cinematic swells"]},
  {id:"sound:music-phonk", kind:"sound", for:"music", when:/\bphonk\b/i, add:["heavy sliding, distorted 808 bass with punchy cowbell hits","hard-hitting trap drums with fast rolling hi-hats","dark, gritty mix with heavy saturation, aggressive from the first second"], avoid:["orchestral swells","clean pop vocals"]},
  {id:"sound:music-hip-hop", kind:"sound", for:"music", when:/\b(?:rap|hip[- ]?hop|808s?|trap beat|drill)\b/i, unless:/\bphonk\b|\b(?:no|not|exclude\w*|without|avoid|zero)\b[\s\S]{0,30}\b(?:trap|rap|hip[- ]?hop)/i, add:["deep 808 bass and hard-hitting drums with crisp hi-hats","a short, repeatable hook that returns between sections","heavy head-nodding groove with space for a vocal on top"], avoid:["orchestral swells","acoustic strumming"]},
  {id:"sound:music-synthwave", kind:"sound", for:"music", when:/\b(?:synthwave|retrowave|outrun|80'?s|eighties|neon|vaporwave)\b/i, add:["analog-style polysynth pads and pulsing arpeggiated bass","drum machine beat with a big gated-reverb snare","warm, slightly detuned lead melody over nostalgic chords"], avoid:["trap hi-hats","modern EDM drops"]},
  {id:"sound:music-noir-jazz", kind:"sound", for:"music", when:/\b(?:noir|detective|smoky|torch song|jazz club|private eye)\b/i, add:["walking upright bass and brushed drums","muted trumpet and sparse piano with minor and diminished chords","slow late-night tempo with a small, intimate room sound"], avoid:["bright upbeat swing","big band brass"]},
  {id:"sound:music-cafe-lounge", kind:"sound", for:"music", when:/\b(?:bossa\w*|caf[eé]|coffee ?(?:shop|house)|coffeehouse|lounge|lobby|cocktail bar|brunch|restaurant)\b/i, unless:/\b(?:jingle|song|lyrics|vocal|sing\w*)\b/i, add:["relaxed groove with nylon-string guitar, soft brushed percussion and upright bass","steady gentle energy for hours of background listening","instrumental, nothing that competes with conversation","warm acoustic recording rather than thin synth tones"], avoid:["hold-music synth tones","loud drums"]},
  {id:"sound:music-venue-playlist", kind:"sound", for:"music", when:/\b(?:taproom|brewery|retail|in-store|store|shop|boutique|bar|venue|speakers?|speaker system)\b/i, unless:/\b(?:caf[eé]|coffee\w*|bossa|lounge|spa|lobby|jazz|jingle|lyrics|sing\w*|stud\w*|lo-?fi|halloween|spooky|retirement|senior|gym|karaoke|pick up the bar|radio|spot|ad|commercial|voice-?over|dreamy|ambien\w*|chill|calm|relax\w*|gentle)\b/i, add:["steady upbeat mid-tempo groove with bright major chords","instrumental, sits under conversation without demanding attention","two or three sections with small changes so it does not feel like a loop"], avoid:["melancholy minor passages","abrupt stops"]},
  {id:"sound:music-meditation-spa", kind:"sound", for:"music", when:/\b(?:meditat\w*|yoga|spa|massage|mindful\w*|breathwork|sleep|wellness|relaxation|sound bath|singing bowls?)\b/i, add:["slow evolving pads with long, soft attacks and releases","no percussion, no sudden changes, no melody that demands attention","gentle singing-bowl tones or low drones in a wide, soft reverb"], avoid:["drums","sudden loud notes"], ask:["How long is the session, and should it stay level or slowly deepen?"]},
  {id:"sound:music-documentary-underscore", kind:"sound", for:"music", when:/\b(?:documentary|docuseries|video essay|archival|history channel)\b/i, add:["understated underscore of sparse piano, soft strings or low pads","slow harmonic movement and no catchy melody, staying under the narration","mood changes placed at the story's turning points"], avoid:["busy rhythms","vocals"], ask:["What is the mood of this segment, and does it shift partway through?"]},
  {id:"sound:music-landscape-awe", kind:"sound", for:"music", when:/\b(?:aerial|landscapes?|mountains?|vista|wildlife|planetarium|national park|dinosaurs?)\b/i, add:["slow swelling strings and French horns with open, wide chords","a gradual build to a full orchestral swell on the widest shot","low brass and high strings spread far apart to convey scale"], avoid:["busy percussion","pop beat"]},
  {id:"sound:music-boss-battle", kind:"sound", for:"music", when:/\bboss (?:battle|fight|level|theme|music|intro|stage)|\bfinal boss|\bfinal battle|\bbattle (?:theme|music)|\bcombat music|\bfight music|\bvillain/i, add:["fast, driving orchestral ostinato over heavy pounding percussion","brass stabs and choir hits on the strongest accents","dark minor key, relentless with no quiet breaks"], avoid:["calm interludes","lo-fi production"], ask:["Does the fight have phases, and should the track loop?"]},
  {id:"sound:music-horror-tension", kind:"sound", for:"music", when:/\b(?:scary|horror|spooky|creepy|eerie|suspense\w*|thriller|haunted|sinister|dread|tense|tension|chase)\b/i, unless:/\b(?:halloween|party)\b|\b(?:not|no|nothing|exclude\w*|without|avoid)\b[\s\S]{0,25}\b(?:tense|tension|scary|spooky|creepy|anxious)/i, add:["low sustained strings with slowly shifting dissonant clusters","a quiet heartbeat-like pulse that gradually speeds up","high scraping string harmonics and distant metallic textures"], avoid:["cheerful major melody"], ask:["Slow-burning dread, or relentless chase energy?"]},
  {id:"sound:music-song-structure", kind:"sound", for:"music", when:/\b(?:full song|lyrics|with singing|vocals?|sung|singer|verse|chorus|bridge|duet)\b/i, unless:/\b(?:no|without|exclude\w*|zero)\b[\s\S]{0,20}\b(?:vocals?|singing|lyrics|words|voices?)\b|^instrumental|\binstrumental (?:only|track|version|demo|underscore|piece|for)\b|\bpure instrumental|\b(?:jingle|chant|station id|hook|singing bowls?)\b|^(?![\s\S]*\blyrics)[\s\S]*\b(?:choir|wordless)\b/i, add:["verse, chorus, verse, chorus, bridge, final chorus structure","a memorable chorus hook repeated at least three times","lyrics with concrete images and specific details instead of generic phrases","lead vocal mixed clearly on top with easy-to-understand words"], avoid:["generic filler lyrics"], ask:["What genre and voice (male, female, duet)?"]},
  {id:"sound:music-instrumental-only", kind:"sound", for:"music", when:/\b(?:no|without|zero|exclude\w*|excluding)\b[\s\S]{0,25}\b(?:vocals?|singing|lyrics|words|voices?|hums?)\b|\binstrumental\b|\bkaraoke\b/i, unless:/\bnot (?:just )?(?:an? )?instrumental|\bwith vocals\b|\bwordless\b|\bfull (?:vocal|song)|\bvocal (?:theme|song|anthem|jingle)/i, add:["fully instrumental: no lead vocal, backing vocals, hums, chants or vocal chops","the melody carried by an instrument instead of a voice"], avoid:["vocal samples","choir pads"]},
  {id:"sound:music-breakup-song", kind:"sound", for:"music", when:/\b(?:breakup|break-up|broke up|heartbreak|heartbroken|dumped|my ex|an ex)\b|\bmissing (?:someone|you|him|her)\b/i, add:["raw, close-mic lead vocal over sparse guitar or piano","lyrics built from specific small memories, not generic heartbreak lines","restrained verses opening into a cathartic chorus"], avoid:["heavy auto-tune","glossy over-produced pop"], ask:["Sad and raw, angry, or moving toward peace?"]},
  {id:"sound:music-short-form-social", kind:"sound", for:"music", when:/\b(?:tiktok|tik tok|instagram|reels|youtube shorts|trend\w*|viral)\b/i, add:["hook within the first second, no intro","punchy current beat with a clear drop lined up to the key moment","short and tight, ending cleanly or looping back to the start"], avoid:["slow build-up","long outro"], ask:["How long is the clip, and when does the main moment hit?"]},
  {id:"sound:music-background-loop", kind:"sound", for:"music", when:/\b(?:loop\w*|for hours|all day|all night|continuous\w*|on repeat|hour long|an hour|stream\w*|twitch|livestream\w*)\b/i, unless:/\b(?:build\w*|grow\w*|evolv\w*|swell\w*|lift|shift\w*|gets (?:more|sillier))\b|\b(?:not (?:just )?a|like a|feel like a) loop\b/i, add:["consistent tempo, key and energy from start to end","no intro build-up and no final ending, so it repeats smoothly","gentle variations in texture so it does not feel repetitive over long play","uncluttered mid-range so talk or voice chat stays clear"], avoid:["big drops","sudden stops"]},
  {id:"sound:music-circus", kind:"sound", for:"music", when:/\b(?:circus|clown\w*|calliope|carnival|big top)\b/i, add:["calliope or circus organ melody over an oompah tuba bass","fast two-beat march with snare rolls","slide whistle, horn honks and cymbal crashes on the gags"], avoid:["creepy horror-clown tone"]},
  {id:"sound:music-graduation", kind:"sound", for:"music", when:/\b(?:graduat\w*|commencement)\b/i, add:["reflective piano opening that builds into a big anthemic chorus","a shift from looking back to looking forward","a triumphant final section with full drums and strings"], avoid:["sad ending"], ask:["With singing, or instrumental only?"]},
  {id:"sound:music-ballet-recital", kind:"sound", for:"music", when:/\b(?:ballet|ballerina|dance recital|dance studio)\b/i, add:["graceful waltz or flowing triple meter with strings and piano","clear phrasing in eight-count groups that dancers can follow","a swelling crescendo for the lift or final pose"], avoid:["heavy drums","abrupt tempo changes"], ask:["When is the big lift or final pose, in seconds?"]},
  {id:"sound:music-senior-nostalgia", kind:"sound", for:"music", when:/\bretirement (?:community|home|village)|\bsenior living|\bnursing home|\belderly\b|\bolder (?:folks|residents|adults)/i, add:["classic big band, Motown or crooner style from past decades","gentle mid-tempo with familiar, simple song forms","warm vintage recording sound, no modern electronic textures"], avoid:["sudden loud changes","modern trap or EDM drums"]},
  {id:"sound:music-luxury-brand", kind:"sound", for:"music", when:/\b(?:luxury|premium|upscale|high-end|real estate|boutique hotel|classy|opulent)\b/i, unless:/\b(?:runway|fashion)\b/i, add:["solo piano with lush strings over a soft, steady pulse","spacious, uncluttered mix with long reverb tails","unhurried, confident tempo, no busy percussion"], avoid:["cheap stock-music ukulele","busy drums"]},
  {id:"sound:music-not-stock", kind:"sound", for:"music", when:/\b(?:stock|generic|cheap|clich[eé]s?|corny|cheesy|not boring|on the nose|buzzwords?|hold music)\b/i, add:["one distinctive signature instrument or texture carried through the whole piece","real, acoustic-sounding performance with small human timing and dynamics","an unexpected but fitting chord or rhythm choice instead of the obvious one"], avoid:["ukulele-and-glockenspiel corporate pop","four-chord piano build with claps"]},
  {id:"sound:music-corporate-neutral", kind:"sound", for:"music", when:/\b(?:corporate|law (?:firm|office)|clinical|neutral|unremarkable|tech (?:product|ad|launch|demo)|launch video|business video)\b/i, unless:/\b(?:jingle|lyrics|sing\w*)\b/i, add:["minimal modern pulse with clean soft synths or felt piano","restrained, neutral harmony with no emotional swells","consistent level and texture from start to finish"], avoid:["aggressive drums","sentimental strings"], ask:["Should it stay completely flat, or lift slightly at the end?"]},
  {id:"sound:music-upbeat-happy", kind:"sound", for:"music", when:/\b(?:happy|upbeat|feel[- ]good|good vibes|cheerful|summer|vacation|sunny|positiv\w*|grand opening)\b/i, unless:/\b(?:chill|relax\w*|calm|dark|moody|spooky|scary|lullaby|sad)\b|\b(?:not|no|nothing|without|avoid|never|exclude\w*)\b[\s\S]{0,25}\b(?:happy|upbeat|bright|cheerful|fun)/i, add:["bright major key with a bouncy mid-to-fast tempo","handclaps and crisp light percussion driving a feel-good groove","a catchy hook that returns often"], avoid:["minor-key passages","slow quiet sections"]},
  {id:"sound:music-uplifting-orchestral", kind:"sound", for:"music", when:/\b(?:uplifting|hopeful|aspirational|inspiring|inspirational|nonprofit|charity|donation|fundrais\w*|annual report)\b/i, unless:/\b(?:gospel|church|choir|disco|funk\w*|store|playlist|song|lyrics|vocals?|sing\w*|anthem)\b/i, add:["rising string ostinato under a warm piano melody","layers building gradually toward a bright, open major-key peak","sincere and hopeful, without tearjerker sadness or melodrama"], avoid:["guilt-trip sad piano","tense or anxious passages"]},
  {id:"sound:music-western", kind:"sound", for:"music", when:/\b(?:western|cowboy|saloon|wild west|old west|pioneers?|frontier|honky[- ]?tonk)\b/i, add:["acoustic guitar, banjo and fiddle over a loping, galloping rhythm","twangy reverb guitar and harmonica over open, wide chords","dusty, vintage recording warmth"], avoid:["modern drums","synths"]},
  {id:"sound:music-campfire-singalong", kind:"sound", for:"music", when:/\b(?:campfire|sing-?along|scouts?|scout troop|summer camp)\b/i, unless:/\bretirement|\bsenior/i, add:["strummed acoustic guitar, banjo and simple hand percussion","an easy repeating chorus with a narrow melody anyone can sing","warm, loose group vocals like friends singing together"], avoid:["polished studio pop","complex lyrics"]},
  {id:"sound:music-lullaby", kind:"sound", for:"music", when:/\blullab\w*|\bnewborn|\bbedtime|\bput (?:the )?baby to sleep/i, add:["slow, gentle swaying triple-meter rhythm","soft music box, celesta or fingerpicked guitar","hushed, breathy vocal close to the mic, or no vocal at all","no drums, no sudden changes, a quiet fading ending"], avoid:["percussion","bright loud instruments"]},
  {id:"style:photo-product", kind:"style", for:"image", when:/\b(?:e[\s-]?commerce[\s-]?photo|product[\s-]?photo|product[\s-]?shot|packshot)\b/i, add:["seamless clean backdrop with soft even light","crisp silhouette, no edge fringing","true-to-life colour and sharp label detail"], avoid:["props","warped or garbled label text"]},
  {id:"style:photo-food", kind:"style", for:"image", when:/\b(?:food[\s-]?photography|food[\s-]?photo|food[\s-]?shot)\b/i, add:["soft natural window light from one side","shallow depth of field, sharp focus on the dish","simple clean background that complements the food"], avoid:["plastic-looking food","cluttered props stealing focus"]},
  {id:"style:photo-portrait", kind:"style", when:/\b(?:portrait[\s-]?photography|portrait[\s-]?photo|profile[\s-]?photo|headshot)\b/i, add:["soft key light with gentle fill","85mm look, shallow depth of field, blurred background","sharp eyes, natural skin texture"], avoid:["over-smoothed plastic skin","distorted hands or uneven eyes"]},
  {id:"style:photo-street", kind:"style", when:/\b(?:street[\s-]?photography|candid[\s-]?street|street[\s-]?photo)\b/i, add:["candid unposed moment in public space","35mm wide-angle perspective","available light with natural contrast"], avoid:["posed subjects","clean studio lighting on a street scene"]},
  {id:"style:photo-cinematic", kind:"style", when:/\b(?:cinematic[\s-]?still|cinematic[\s-]?photo|cinematic[\s-]?shot|movie[\s-]?still|film[\s-]?still)\b/i, add:["shallow depth of field with soft background bokeh","motivated lighting with muted, graded colour"], avoid:["flat even lighting","stock-photo look instead of film look"]},
  {id:"style:photo-noir", kind:"style", when:/\b(?:noir[\s-]?style|film[\s-]?noir|noir)\b/i, add:["black and white, high contrast","low-key lighting with hard shadows","unbalanced tilted compositions"], avoid:["soft even lighting","colour leaking into a monochrome image"]},
  {id:"style:photo-documentary", kind:"style", when:/\b(?:documentary[\s-]?photo|photojournalism|press[\s-]?photo|reportage)\b/i, add:["candid unposed moment","available light, natural uneven exposure","honest unretouched look"], avoid:["staged polished look","heavy colour grading"]},
  {id:"style:photo-macro", kind:"style", when:/\b(?:macro[\s-]?photography|macro[\s-]?photo)\b/i, add:["extreme close-up with razor-thin focus plane","soft creamy out-of-focus background","even soft light showing fine texture"], avoid:["blurry subject","sharpness fading to mush on the focal edge"]},
  {id:"style:photo-longexposure", kind:"style", when:/\b(?:long[\s-]?exposure|light[\s-]?trails|silky[\s-]?water|star[\s-]?trails)\b/i, add:["moving elements as smooth streaks","stationary elements perfectly sharp"], avoid:["blur across the whole frame","ghosted static objects"]},
  {id:"style:photo-aerial", kind:"style", when:/\b(?:aerial[\s-]?(?:photo|photograph|view|shot|image)|bird\'?s[\s-]?eye[\s-]?view|top[\s-]?down[\s-]?aerial)\b/i, unless:/\bfpv\b/i, add:["high vantage point looking down","map-like patterns and scale","wide view with deep sharp focus"], avoid:["tilted horizon","toy-like miniature blur"]},
  {id:"style:photo-architecture", kind:"style", when:/\b(?:architectural[\s-]?photography|interior[\s-]?design[\s-]?photo|architecture[\s-]?photo|real[\s-]?estate[\s-]?photo|interior[\s-]?photo)\b/i, add:["straight parallel vertical lines","wide-angle view with deep focus","balanced natural and artificial light"], avoid:["converging leaning walls","warped impossible geometry"]},
  {id:"style:photo-fashion", kind:"style", when:/\b(?:fashion[\s-]?editorial|editorial[\s-]?photo|fashion[\s-]?shoot|fashion[\s-]?photo)\b/i, add:["deliberate styled lighting and pose","clothing is the visual focus","clean composed framing"], avoid:["melted clothing details","generic catalogue look"]},
  {id:"style:photo-sports", kind:"style", when:/\b(?:sports[\s-]?photography|sports[\s-]?action|sports[\s-]?photo|action[\s-]?shot)\b/i, add:["fast shutter, frozen peak action","telephoto compression, blurred background","panning blur behind a sharp athlete"], avoid:["distorted limbs","motion blur on the subject itself"]},
  {id:"style:photo-goldenhour", kind:"style", when:/\b(?:sunrise[\s-]?landscape|sunset[\s-]?landscape|landscape[\s-]?photo|golden[\s-]?hour)\b/i, add:["warm low-angle sunlight with long shadows","soft diffuse low-contrast light","warm tones against cooler shadows"], avoid:["harsh midday light","oversaturated fake-looking sky"]},
  {id:"style:photo-nightcity", kind:"style", when:/\b(?:neon[\s-]?night[\s-]?photo|city[\s-]?at[\s-]?night|night[\s-]?city|neon[\s-]?city)\b/i, add:["artificial neon and street-light glow","reflections on wet surfaces"], avoid:["daylight","muddy noise instead of clean glow"]},
  {id:"style:art-anime", kind:"style", when:/\b(?:toon[\s-]?shading|anime[\s-]?style|cel[\s-]?shaded|cel[\s-]?shaded|anime)\b/i, add:["flat colour blocks with hard-edged shadows","clean bold outlines","limited smooth shading, no gradients"], medium:"anime illustration", avoid:["photoreal skin","soft airbrushed gradients"]},
  {id:"style:art-manga", kind:"style", when:/\b(?:black[\s-]?and[\s-]?white[\s-]?manga|manga[\s-]?panel|manga[\s-]?ink|manga)\b/i, add:["black and white ink line work","screentone shading"], medium:"manga ink drawing", avoid:["colour","garbled speech bubble text"]},
  {id:"style:art-childrensbook", kind:"style", when:/\b(?:childrens[\s-]?book[\s-]?illustration|storybook[\s-]?illustration|children's[\s-]?book|picture[\s-]?book)\b/i, add:["soft watercolour washes","gentle rounded shapes and warm palette","simple readable character shapes"], medium:"children's book illustration", avoid:["scary details","inconsistent character look"]},
  {id:"style:art-watercolour", kind:"style", when:/\b(?:watercolour[\s-]?painting|wash[\s-]?painting|watercolour|watercolor)\b/i, add:["transparent washes with paper showing through","soft bleeding wet-on-wet edges","visible paper texture"], medium:"watercolour painting", avoid:["opaque digital-looking fills","hard vector edges"]},
  {id:"style:art-oil", kind:"style", when:/\b(?:oil[\s-]?painting|oil[\s-]?paint|painterly)\b/i, add:["visible thick brushstrokes","rich dense colour with layered glazes","canvas texture"], medium:"oil painting", avoid:["smooth airbrushed digital finish","plastic photo look"]},
  {id:"style:art-gouache", kind:"style", when:/\b(?:gouache[\s-]?painting|gouache)\b/i, add:["opaque matte flat colour","visible brush marks","solid poster-like colour shapes"], medium:"gouache illustration", avoid:["glassy transparent washes","digital gradients"]},
  {id:"style:art-pencil", kind:"style", when:/\b(?:graphite[\s-]?drawing|pencil[\s-]?drawing|pencil[\s-]?sketch)\b/i, add:["graphite line and hatching","soft grey tonal shading","paper grain showing"], medium:"pencil drawing", avoid:["colour","smooth digital shading"]},
  {id:"style:art-inkline", kind:"style", when:/\b(?:outline[\s-]?drawing|ink[\s-]?line[\s-]?art|ink[\s-]?drawing|pen[\s-]?and[\s-]?ink|line[\s-]?art)\b/i, add:["clean contour lines, no fills or gradients","varied line weight","plain background"], medium:"ink line art", avoid:["grey shading","broken or doubled lines"]},
  {id:"style:art-comic", kind:"style", when:/\b(?:graphic[\s-]?novel|comic[\s-]?style|comic[\s-]?panel|comic[\s-]?book)\b/i, add:["bold inked outlines","flat colour with halftone shading"], medium:"comic book illustration", avoid:["garbled lettering","soft painterly rendering"]},
  {id:"style:art-pixel", kind:"style", when:/\b(?:pixel[\s-]?art|pixelated|16[\s-]?bit|sprite|8[\s-]?bit)\b/i, add:["visible individual square pixels","restricted colour palette","hard edges, no blur or anti-aliasing"], medium:"pixel art", avoid:["smooth blurry gradients","inconsistent pixel size"]},
  {id:"style:3d-lowpoly", kind:"style", when:/\b(?:faceted[\s-]?3d|low[\s-]?poly|low[\s-]?poly)\b/i, add:["flat-shaded triangular facets","simple blocky forms with few polygons","clean minimal shading"], medium:"low-poly 3D render", avoid:["smooth high-poly surfaces","photoreal textures"]},
  {id:"style:art-isometric", kind:"style", when:/\b(?:isometric[\s-]?illustration|isometric[\s-]?view|isometric[\s-]?3d|isometric)\b/i, add:["parallel projection, no perspective","equal 30 degree axes","miniature diorama feel"], medium:"isometric illustration", avoid:["converging perspective lines","inconsistent angles between objects"]},
  {id:"style:3d-clay", kind:"style", when:/\b(?:clay[\s-]?animation|claymation|clay[\s-]?style|plasticine)\b/i, add:["tactile clay surface with fingerprints","soft rounded handmade forms","stop-motion look with soft studio light"], medium:"claymation-style 3D", avoid:["smooth plastic CGI sheen","perfectly clean machine surfaces"]},
  {id:"style:3d-render", kind:"style", when:/\b(?:cute[\s-]?3d[\s-]?character|3d[\s-]?illustration|stylized[\s-]?3d|stylised[\s-]?3d|3d[\s-]?render)\b/i, unless:/\b(?:realistic|photo\w*|cinematic|dramatic|storm\w*|gritty|moody|dark|horror|epic|intense)\b/i, add:["soft rounded forms with smooth materials","soft studio lighting with gentle shadows","colourful tactile finish"], medium:"stylised 3D render", avoid:["uncanny realism","harsh noisy shadows"]},
  {id:"style:art-vector", kind:"style", when:/\b(?:flat[\s-]?illustration|flat[\s-]?design|flat[\s-]?vector|vector[\s-]?art)\b/i, add:["solid flat colour shapes","simple geometric forms, bold palette"], medium:"flat vector illustration", avoid:["gradients and soft shadows","over-detailed texture"]},
  {id:"style:print-risograph", kind:"style", when:/\b(?:riso[\s-]?print|riso[\s-]?style|risograph)\b/i, add:["limited spot-ink colours","grainy textured ink","slight misregistered overlapping layers"], medium:"risograph print", avoid:["smooth full-colour photo look","perfect digital gradients"]},
  {id:"style:print-linocut", kind:"style", when:/\b(?:relief[\s-]?print|block[\s-]?print|linocut|woodcut)\b/i, add:["bold carved knife marks","solid flat ink areas","limited colours, rough print texture"], medium:"linocut print", avoid:["smooth digital gradients","fine photographic detail"]},
  {id:"style:art-ukiyoe", kind:"style", when:/\b(?:japanese[\s-]?woodblock|woodblock[\s-]?print|ukiyo[\s-]?e|ukiyoe)\b/i, add:["bold flat colour with outlined forms","woodblock print texture","composition and atmosphere over realism"], medium:"woodblock print", avoid:["photoreal shading","western perspective rendering"]},
  {id:"style:art-artnouveau", kind:"style", when:/\b(?:nouveau[\s-]?style|art[\s-]?nouveau)\b/i, add:["sinuous whiplash curves","flowing lettering woven into the art"], medium:"art nouveau illustration", avoid:["rigid symmetry","straight geometric ornament"]},
  {id:"style:art-artdeco", kind:"style", when:/\b(?:deco[\s-]?style|1920s[\s-]?deco|art[\s-]?deco)\b/i, add:["bold geometry and strict symmetry","gold, black and bright accent colours"], medium:"art deco illustration", avoid:["organic flowing curves","muddy modern minimalism"]},
  {id:"style:design-bauhaus", kind:"style", for:"image", when:/\b(?:international[\s-]?typographic[\s-]?style|swiss[\s-]?poster|swiss[\s-]?style|bauhaus)\b/i, add:["modular grid, asymmetric layout","geometric shapes and primary colours","sans-serif type with generous whitespace"], medium:"Swiss-style graphic design", avoid:["ornamental decoration","crowded centred layouts"]},
  {id:"style:art-vaporwave", kind:"style", when:/\b(?:vaporwave|retrowave|synthwave|80s[\s-]?neon|outrun)\b/i, add:["neon pink and cyan gradients","retro 80s and 90s digital look"], medium:"retro digital art", avoid:["muted realistic palette","modern flat minimal look"]},
  {id:"style:art-cyberpunk", kind:"style", when:/\b(?:neon[\s-]?dystopia|cyber[\s-]?punk|cyberpunk)\b/i, add:["neon light against deep shadows","rain-slick reflective surfaces"], avoid:["bright cheerful daylight","clean utopian look"]},
  {id:"style:art-steampunk", kind:"style", when:/\b(?:steam[\s-]?punk|steampunk)\b/i, add:["polished brass and copper tones","Victorian iron, wood and leather materials"], avoid:["modern plastic and chrome","neon sci-fi look"]},
  {id:"style:art-fantasyconcept", kind:"style", when:/\b(?:fantasy[\s-]?concept[\s-]?art|game[\s-]?concept[\s-]?art|fantasy[\s-]?art|concept[\s-]?art)\b/i, add:["painterly digital rendering","dramatic atmospheric lighting","strong readable silhouettes"], medium:"digital concept painting", avoid:["flat stock-photo lighting","cluttered unreadable detail"]},
  {id:"style:art-tattooflash", kind:"style", for:"image", when:/\b(?:traditional[\s-]?tattoo|tattoo[\s-]?design|tattoo[\s-]?flash)\b/i, add:["bold black outlines","limited colour palette","minimal shading, flat fills"], medium:"tattoo flash illustration", avoid:["photographic skin","soft gradients"]},
  {id:"style:design-sticker", kind:"style", for:"image", when:/\b(?:die[\s-]?cut[\s-]?sticker|die[\s-]?cut[\s-]?sticker|sticker[\s-]?design|sticker)\b/i, add:["thick white border around the shape","bold simple artwork with clear outline","plain neutral background"], medium:"sticker illustration", avoid:["busy background","fine detail lost at small size"]},
  {id:"style:design-logo", kind:"style", for:"image", when:/\b(?:logo[\s-]?design|brand[\s-]?mark|app[\s-]?icon|logo)\b/i, unless:/\bmock[\s-]?ups?\b|\b(?:on|onto) (?:a |an |the |our |my )?(?:mug|shirt|t-?shirt|hoodie|cap|hat|bag|tote|sign|truck|van|storefront|box|package|bottle|label)\b/i, add:["simple bold shape with strong silhouette","solid colours, balanced negative space","scales cleanly to small sizes"], medium:"logo design", avoid:["extra lettering","garbled or extra lettering"]},
  {id:"style:design-poster", kind:"style", for:"image", when:/\b(?:concert[\s-]?poster|event[\s-]?poster|gig[\s-]?poster)\b/i, add:["one dominant headline with clear hierarchy","strong central image with bold colour","large legible text from a distance"], avoid:["garbled lettering","too much small text"]},
  {id:"style:design-bookcover", kind:"style", for:"image", when:/\b(?:novel[\s-]?cover|book[\s-]?cover|cover[\s-]?art)\b/i, add:["title as the clear dominant element","single strong cover image","consistent typography hierarchy"], avoid:["misspelled title","text over a busy image"]},
  {id:"style:design-thumbnail", kind:"style", for:"image", when:/\b(?:youtube[\s-]?thumbnail|video[\s-]?thumbnail)\b/i, add:["one clear focal subject","very short bold high-contrast text, readable when small"], avoid:["long text","small text that vanishes when shrunk"]},
  {id:"style:design-infographic", kind:"style", for:"image", when:/\b(?:info[\s-]?graphic|data[\s-]?graphic|infographic)\b/i, add:["clear sections with strong visual hierarchy","consistent palette and spacing"], avoid:["invented numbers","dense tiny unreadable text"]},
  {id:"style:design-menu", kind:"style", for:"image", when:/\b(?:restaurant[\s-]?menu|menu[\s-]?design|cafe[\s-]?menu)\b/i, add:["clear sections for each course type","name and price in aligned rows","restrained typography, generous spacing"], avoid:["garbled prices","dense unreadable columns"]},
  {id:"style:design-social", kind:"style", for:"image", when:/\b(?:social media (?:graphic|post design|template|banner)|instagram (?:graphic|post design|template|quote post)|post graphic|quote graphic)\b/i, add:["one clear focal subject","short bold headline, high contrast","safe margins for the platform crop"], avoid:["long text","important content near the crop edge"]},
  {id:"style:design-card", kind:"style", for:"image", when:/\b(?:thank[\s-]?you[\s-]?card|greeting[\s-]?card|birthday[\s-]?card|holiday[\s-]?card|card[\s-]?design)\b/i, add:["warm balanced layout with clear margins","short message in clear lettering"], avoid:["misspelled text","text crowded against the edge"]},
  {id:"text:complaint-letter", kind:"text", when:/\b(complain(t|ts|ing)?|refunds?|compensation|runaround|chargeback|firmer email)\b|\bmissed (my )?connection\b/i, unless:/\b(review|yelp|landlord|hoa|tenants?|neighbou?rs?|complaints about|guy in \d+\w?)\b|\b(reply|respond) to (a|an|the|this|our) (upset |angry )?(customer|client)\b|\b(customer|client)s? (is |who'?s |whos )?(upset|mad|angry)\b|\bsupport macros?\b/i, add:["State the problem, the dates and what was promised in the first two sentences.","List each incident or earlier contact as a short dated timeline with order or ticket numbers.","Ask for one specific remedy, such as a refund, credit or repair, and a reply deadline.","Name the next step if unresolved, like a regulator complaint or card dispute, calmly and without threats.","Keep it firm and factual: no sarcasm, insults or all caps."], avoid:["long venting paragraphs that bury the request","legal threats the writer cannot back up"], ask:["What exactly do you want them to do: refund, credit, repair or something else?","Do you have dates and order or ticket numbers to include?"], role:"a consumer advocate who writes complaint letters that get results"},
  {id:"text:landlord-repair-request", kind:"text", when:/\blandlord\b[\s\S]*\b(mold|mould|repairs?|fix|broken|leak\w*|heat(ing)?|heater|ac|a\/c|air ?con\w*|pests?|roach\w*|mice)\b|\b(mold|mould|leak\w*|broken|repairs?)\b[\s\S]*\blandlord\b/i, add:["Open with the problem, when it started, and the dates of earlier requests.","Describe the health or safety impact plainly and factually.","Request the repair by a specific date and ask for the plan in writing.","Keep it polite and dated so it works as a paper trail later.","Mention tenant rights only in general terms, since repair and rent-withholding rules vary by location."], avoid:["advising rent withholding without checking local law","angry or sarcastic tone"], ask:["How many times, and on what dates, have you already asked?"], role:"a tenant rights advocate"},
  {id:"text:neighbor-dispute", kind:"text", when:/\b(hoa|homeowners'? association)\b|\bneighbou?r'?s?\b[\s\S]{0,60}\b(tree|branch|fence|dog|music|noise|parking)\b|\bguy in \d{1,2}[a-z]\b|\b(notice|reminder) (for|to) (my |our |the )?(apartment|building|tenants|residents)\b|\bmy tenants?\b/i, add:["Cite the exact rule, bylaw section or lease clause involved.","Stick to observable facts with dates and times; attach photos or measurements if available.","Make one specific request with a reasonable deadline, and say what happens next if ignored.","Keep the tone neighborly, since the relationship continues after this.","In notices about complaints, don't name the people who complained."], avoid:["accusations about motives or character","threats beyond what the rules allow"], ask:["Which rule or agreement applies, and what have you already tried directly?"], role:"a calm neighbor-dispute mediator and experienced property manager"},
  {id:"text:work-update-email", kind:"text", when:/\b(status update|project update|sprint update|behind schedule|pushing (the |our )?[\w\s]{1,25}? back|(project|roadmap) delay|explaining (a|the|why) [\w\s]{0,25}?delay|meeting (notes|recap|summary|minutes)|recap (email|of the (call|meeting))|people who missed|action items)\b/i, add:["Lead with the bottom line in the first sentence: status, decisions, or the new date.","List action items with an owner and a due date for each.","If something slipped, give the cause in one factual sentence, the recovery plan and the next milestone.","Say what you need from the reader, if anything, and by when.","Use a subject line that names the project or meeting and the key point."], avoid:["burying bad news at the end","blaming individuals","who-said-what play-by-play"], ask:["What is the realistic new date or main decision, and who needs to act?"], role:"a seasoned project manager"},
  {id:"text:negotiation", kind:"text", when:/\bnegotiat\w*|\b(ask(ing)? (my \w+ )?for a raise|pay rise|counter ?offer|raising my rates|rate increase)\b|\braise\b[\s\S]{0,60}\b(boss|manager)\b|\b(boss|manager)\b[\s\S]{0,60}\braise\b/i, add:["Anchor with a specific number backed by market data or concrete results, slightly above the real target.","Justify with value delivered, not personal need or apology.","Set a walk-away point and a fallback ask in advance, such as a review date, terms or extras.","Script replies to the two most likely objections.","State the number once, then stop talking and let them respond."], avoid:["bluffing about offers that don't exist","over-explaining or apologizing for the ask"], ask:["What number are you aiming for, and what is your walk-away point?"], role:"a seasoned negotiation coach"},
  {id:"text:school-message", kind:"text", when:/\b(email|note|message|letter|write|talk) (to |with )?(my |my (son|daughter|kid|child)'?s |the |a )?(professor|teacher|instructor|principal)\b|\b(professor|teacher)\b[\s\S]{0,80}\b(extension|bull(y|ied|ying)|grade[sd]?|regrade)\b|\ba parent (emailed|called)\b|\bconference\b[\s\S]{0,30}\bparent\b|\bnote home\b/i, add:["Put the situation and the specific request in the first two sentences.","Describe behavior and events as observable facts with dates, not labels.","Propose a concrete next step, like a new deadline, a short meeting, or a plan both sides follow.","When writing to a parent, open with a specific, genuine strength of the child.","Keep it short and respectful; teachers and parents read these between other tasks."], avoid:["comparing the child to other students","emotional accusations"], ask:["What outcome do you want from this message?"], role:"an experienced teacher who knows how school emails get read"},
  {id:"text:performance-review", kind:"text", when:/\bperformance (review|improvement|plan|feedback)\b|\b(pip|appraisal|self[- ]review)\b|\breview for (someone|an employee|my (direct )?report)|\bfeedback (to|for) (an? |my )?(employee|report|direct report|team ?mate|team member)\b/i, add:["Tie every point to a specific observed example and its impact on the team or results.","Separate what to keep doing from what must change, with clear expectations.","Set measurable goals with dates and the support the manager will provide.","Describe behavior and results, never personality.","For an improvement plan, state check-in dates and consequences plainly and suggest HR review."], avoid:["vague praise like 'great team player'","raising problems for the first time in writing"], ask:["What are two or three specific examples, good and bad, from this period?"], role:"an experienced people manager"},
  {id:"text:resignation", kind:"text", when:/\b(resign\w*|two weeks'? notice|2 weeks'? notice|notice period|leaving the company|telling my team i'?m leaving|last day is)\b/i, add:["State the resignation and the exact last working day in the first sentence.","Thank them briefly and specifically; no reasons or criticism are required.","Offer concrete handover help: documentation, training a replacement, finishing named work.","Keep it short and neutral, since it stays in the personnel file."], avoid:["grievances or complaints about colleagues","negotiating inside the resignation letter"], ask:["What is your last working day, and who should receive it?"], role:"an experienced HR advisor"},
  {id:"text:toast-speech", kind:"text", when:/\b(toasts?|best man|maid of honou?r|matron of honou?r|wedding speech|rehearsal dinner|retirement (speech|party)|farewell|bat mitzvah|bar mitzvah|anniversary (dinner|party)|speech for my)\b|\bsay something at\b/i, unless:/\b(eulogy|funeral|memorial|layoffs?|all[- ]hands)\b/i, add:["Aim for about two to four minutes spoken, roughly 300 to 500 words.","Open with a short specific moment, not 'for those who don't know me' or a dictionary definition.","Build around one or two stories that show who the person is, then what they mean to you.","Keep inside jokes clear to the whole room; nothing about exes or embarrassing secrets.","End by asking everyone to raise a glass, with a one-line wish."], avoid:["roasting that humiliates","long lists of adjectives"], ask:["How do you know them, and what is one story that shows who they are?","Should it lean funny or sentimental, and how long?"], role:"a speechwriter who specializes in wedding and celebration toasts"},
  {id:"text:eulogy", kind:"text", when:/\b(eulog\w*|memorial|funeral|passed away|celebration of life|obituary|in memoriam)\b/i, add:["Build around two or three specific stories or habits, not a list of virtues.","Allow gentle humor if it fits the person; lightness and grief can sit together.","Keep it about three to five minutes spoken, in short sentences easy to read aloud through tears.","Acknowledge a complicated person honestly and gently, without airing grievances.","Close with what they leave behind or a direct goodbye."], avoid:["a chronological résumé of their life","clichés like 'in a better place' unless the family wants them"], ask:["What are two or three stories or habits that capture them?"], role:"a compassionate eulogy writer"},
  {id:"text:wedding-vows", kind:"text", when:/\bvows?\b/i, add:["Keep it about one to two minutes spoken.","Start with a specific memory or moment that shows who your partner is to you.","Mix serious promises with one or two small, concrete, playful ones.","End with a forward-looking line said directly to the partner."], avoid:["private details the partner wouldn't want shared","generic lines like 'my best friend and soulmate' with nothing specific"], ask:["Have you and your partner agreed on length and tone?"], role:"a wedding officiant who helps couples write vows"},
  {id:"text:card-message", kind:"text", when:/\b(birthday (message|card|note|wish|text|post)|card for|write in (a|the|her|his) card|anniversary (card|message)|get well|retirement card|goodbye card|thank[- ]you (note|card|message|text))\b|\b(turning|turns) \d{2}\b/i, unless:/\b(toast|speech|eulog\w*|song)\b/i, add:["Build it around one specific memory or trait instead of generic wishes.","Keep it to two to five sentences unless asked for more.","Match the person: plain and warm for someone who dislikes mushy, playful for close friends.","Offer three versions in different tones."], avoid:["greeting-card clichés","making it about the writer"], ask:["What is one memory or habit of theirs you'd like to mention?"], role:"a thoughtful greeting card writer"},
  {id:"text:cover-letter", kind:"text", when:/\bcover letters?\b/i, add:["Open with a specific reason for this company or role, not 'I am writing to apply for'.","Match two or three requirements from the posting to concrete achievements with results.","Keep it under about 300 words, three or four short paragraphs.","Close with a confident, specific line inviting a conversation.","Never invent experience; leave bracketed placeholders for missing facts."], avoid:["repeating the résumé line by line","generic flattery of the company"], ask:["Can you paste the job posting and your two proudest relevant achievements?"], role:"a hiring manager who has read thousands of cover letters"},
  {id:"text:resume-bullets", kind:"text", when:/\b(r[eé]sum[eé]s?|cv)\b/i, unless:/\bcover letter\b/i, add:["Start each bullet with a strong past-tense action verb, never 'Responsible for'.","Follow action, what, how, result, in one or two lines.","Show scale and results with numbers, percentages, time saved or team size where true.","Mirror keywords from the target job posting for applicant tracking systems.","Never invent numbers; use bracketed placeholders like [X%] for the person to fill."], avoid:["soft skills claimed without evidence","first-person pronouns in bullets"], ask:["What job are you targeting, and do you have any numbers for your results?"], role:"a professional résumé writer and recruiter"},
  {id:"text:bio", kind:"text", when:/\b(instagram|ig|linkedin|speaker|author|band|artist|twitter|tiktok|conference|short|professional|website|team|personal|jacket) bios?\b|\bbios? for\b|\b(about (me|section|page)|linkedin about|profile summary)\b/i, add:["Lead with what you do and for whom in one clear sentence.","Include one or two specific proof points, credentials or results.","Add one human detail that makes the person memorable.","Match the platform: first person for LinkedIn or Instagram, third person for speaker and event bios.","Respect length limits, such as 150 characters for an Instagram bio."], avoid:["buzzwords like 'results-driven', 'passionate', 'synergy'"], ask:["Where will this bio appear, and who should it attract?"], role:"a personal branding copywriter"},
  {id:"text:social-caption", kind:"text", when:/\b(captions?|instagram post|ig post|tweets?|tiktok|facebook post|social (media )?post|linkedin post|threads post|x post)\b/i, unless:/\bcaptions? (script|file|track)s?\b|\bsubtitles?\b/i, add:["Put the hook in the first line, since feeds cut off after one or two lines.","Use one concrete detail, like a taste, a sound or a moment, instead of adjectives.","Offer three options in different tones, such as playful, warm and minimal.","End with one simple call to action or question when the goal is engagement.","Keep hashtags to a few relevant ones at the end, or none."], avoid:["walls of hashtags","hype words like 'game-changer' or 'you won't believe'"], ask:["Which platform, and what should people do after reading it?"], role:"a social media copywriter for small brands"},
  {id:"text:video-titles-hooks", kind:"text", when:/\b(youtube|yt|video|short|reel)s? (titles?|descriptions?|hooks?|intro|opening)\b|\bhook lines?\b|\btitle (options|ideas)\b|\b(titles?|description) for (a |my |our )?(youtube )?video\b/i, add:["Give eight to ten options with different angles: curiosity, benefit, number, contrarian.","Keep titles under about 60 characters and front-load the key search words.","Make the first spoken line of a video create a question the viewer needs answered.","Every title and hook must be paid off by the actual video."], avoid:["clickbait the video doesn't deliver","ALL CAPS titles"], ask:["Who is the target viewer, and what is the one payoff of the video?"], role:"a YouTube growth strategist"},
  {id:"text:product-description", kind:"text", when:/\bproduct (descriptions?|listings?|page|copy)\b|\b(etsy|amazon|shopify) (listings?|description)\b|\bmenu (descriptions?|items?)\b|\b(product|listing) for my\b|\bdescriptions? for (my|our) (new )?\w+ (candle|soap|sauce|bar|board|latte|product)s?\b/i, unless:/\b(real estate|\d (bed(room)?|br)s?|(house|home|condo) listing)\b/i, add:["Lead with the sensory or practical benefit, then the features that prove it.","Include what buyers look for: size, materials, scent or flavor, care, how to use.","Use short paragraphs or bullets that scan on a phone.","Make only true, checkable claims; no health claims or unprovable 'best'.","Work in two or three natural search keywords for the marketplace."], avoid:["filler like 'elevate your space' or 'luxurious'","invented reviews or awards"], ask:["What makes it different from similar products, and who buys it?"], role:"an e-commerce copywriter"},
  {id:"text:real-estate-listing", kind:"text", when:/\b(listing description|real estate listing|property listing|mls)\b|\b\d (bed(room)?|br)s?\b[\s\S]{0,20}\b\d(\.\d)? (bath(room)?|ba)s?\b/i, add:["Lead with the strongest feature or feeling of the home, not the bed and bath count.","Replace clichés with specifics: what was updated, materials, light, outdoor space.","Describe the property, not the ideal buyer, to stay within fair housing rules.","Keep it about 150 to 250 words and end with the key facts."], avoid:["clichés like 'cozy', 'must see', 'won't last'","phrases like 'perfect for families'"], ask:["What are the three best features, and what was recently updated?"], role:"a real estate copywriter"},
  {id:"text:marketing-email", kind:"text", when:/\b(launch email|announcement email|newsletters?|onboarding emails?|welcome (email|series)|re-?engagement|email (campaign|sequence|series)|subject lines?|promo(tional)? email|win-?back)\b|\bemail to (our |my )?(users|customers|subscribers|members)\b|\bmembers who\b/i, unless:/\binvestor\b/i, add:["Give two or three subject lines under about 50 characters, plus preview text.","State the one main benefit in the first sentence and keep one primary call to action.","Use short paragraphs and bullets; most readers skim on a phone.","Write from a named person in a conversational voice, not 'Dear valued customer'.","For a series, give each email one job and say when it sends."], avoid:["several competing calls to action","spam-trigger phrasing like 'act now!!!'"], ask:["What one action should the reader take after reading?"], role:"an email marketing specialist"},
  {id:"text:cold-outreach", kind:"text", when:/\b(cold (email|outreach|message|dm|pitch)|outreach (messages?|emails?)|prospecting|sales email|proposal email|pitch email|potential clients)\b/i, add:["Keep it under about 120 words and open with something specific to the recipient.","Name one concrete problem you solve for businesses like theirs, with one proof point.","End with a low-effort ask, like a short call or a yes or no question.","Add a brief follow-up for a few days later that offers something new."], avoid:["'I hope this email finds you well'","long feature lists about yourself"], ask:["Who exactly is the recipient, and what result have you gotten for similar clients?"], role:"a B2B sales copywriter"},
  {id:"text:customer-reply", kind:"text", when:/\b(1|one|2|two)[- ]stars?\b|\byelp\b|\b(respond|reply|response)\b[\s\S]{0,40}\breviews?\b|\breviews?\b[\s\S]{0,40}\b(respond|reply)\b|\bsupport (macros?|replies|tickets)\b|\b(reply|respond) to (a|an|the|this|our) (upset |angry )?(customer|client)\b|\b(customer|client)s? (is |who'?s |whos )?(upset|mad|angry)\b/i, unless:/\b(performance|code|design doc|peer) reviews?\b/i, add:["Thank them and acknowledge the specific complaint in the first sentence.","Apologize once, specifically, and say exactly what you will do and by when.","Correct factual errors calmly and briefly, without calling the customer a liar.","Offer a direct way to continue privately, with a named contact.","Keep public replies under about 100 words; future customers are the real audience."], avoid:["'we apologize for any inconvenience'","defensive policy explanations"], ask:["What can you actually offer: refund, replacement, credit or nothing?"], role:"a senior customer support and reputation manager"},
  {id:"text:invoice-reminder", kind:"text", when:/\b(invoices?|unpaid|overdue|past due|late (payment|paying)|(hasn'?t|hasnt|still hasnt|still hasn'?t) paid|need (to get )?paid)\b/i, unless:/\b(my|a) friend\b/i, add:["Put the invoice number, amount, original due date and days overdue near the top.","Restate how to pay, with a direct link or details, so paying takes one step.","Set a specific new pay-by date.","Escalate by stage: friendly reminder, firm second notice, final notice naming late fees or paused work.","Mention late fees or collections only if the contract allows them."], avoid:["apologizing for asking to be paid","guilt-tripping"], ask:["Is this the first reminder, and does your contract mention late fees?"], role:"an accounts receivable specialist for freelancers"},
  {id:"text:explain-to-kid", kind:"text", when:/\b(explain\w*|teach\w*|talking points|science fair)\b[\s\S]{0,80}\b(\d{1,2}[- ]?(year|yr)s?[- ]?old|kids?|son|daughter|nephew|niece|child|children|\d(st|nd|rd|th)[- ]grader?s?)\b|\b(\d{1,2}[- ]?(year|yr)s?[- ]?old|my (kid|son|daughter|nephew|niece|child))\b[\s\S]{0,80}\b(explain\w*|science fair)\b/i, unless:/\b(asthma|action plan|report card|polic(y|ies)|rubric|lesson plan|teacher|parent whose|essay)\b/i, add:["Use one everyday analogy from a child's world, like cooking, toys or the playground.","Use short sentences, and define each new word with a simple picture.","Include a hands-on activity or question the child can answer to check understanding.","Correct the most common misconception about this topic explicitly.","Simplify but never say something false."], avoid:["talking down or baby talk","more than one new idea at a time"], ask:["How old is the child, and what do they already know about it?"], role:"a patient elementary school science teacher"},
  {id:"text:explain-to-beginner", kind:"text", when:/\b(like i'?m (5|five|a beginner|not|new|dumb)|eli5|in plain (english|words|terms|language)|plain[- ]english|never (coded|done this)|i'?m not a (lawyer|doctor|\w+ (nerd|person))|for (a )?beginners?|keep getting confused|i (still )?(don'?t|dont) (get|believe|understand)|explain\w*\b[\s\S]{0,60}\b(simply|simple|without jargon))\b/i, unless:/\b\d{1,2}[- ]?(year|yr)s?[- ]?old\b/i, add:["Start with a one-sentence plain answer, then build up.","Use one concrete analogy, then say where the analogy breaks down.","Define each technical term in one plain sentence when it first appears.","Walk through one small worked example with real numbers or real objects.","End with the most common misconception and why it's wrong."], avoid:["jargon without definitions","condescending phrases like 'simply' or 'obviously'"], ask:["What do you already know about it, and where does it stop making sense?"], role:"a patient teacher who explains hard ideas to beginners"},
  {id:"text:homework-problem", kind:"text", when:/\b(homework|stoichiometry|moles?|mole conversion|gas laws?|physics|calc(ulus)?|algebra|geometry|equation|word problem|p-?value|probability|monty hall|syllogism)\b|\blogic\b[\s\S]{0,20}\bvalid\b|\bshow (every|each|all|the) steps?\b/i, unless:/\b(essay|thesis statement|parent whose|conference with)\b/i, add:["Write the knowns, the unknown and the formula before any arithmetic.","Show each step with units carried through, then check the answer is reasonable.","Explain why each step is taken, not just what is done.","Flag the most common mistake on this type of problem.","Offer one similar practice problem with the answer at the end."], avoid:["skipping steps","an answer with no units"], ask:["Do you want the full solution, or a hint first so you can try it?"], role:"a patient math and science tutor"},
  {id:"text:essay-help", kind:"text", when:/\b(essays?|thesis statement|intro paragraph|college application|personal statement|argumentative|persuasive (paper|essay))\b/i, unless:/\b(rubric|grading|grade[sd]? (it|them))\b/i, add:["Make the thesis arguable: a claim a reasonable person could dispute, plus the main reasons.","Give each body paragraph one claim, specific evidence, and analysis tied back to the thesis.","Address the strongest counterargument and answer it.","For personal essays, open inside a specific moment and show change through concrete details.","Keep the student's own voice and ideas when revising."], avoid:["opening with a dictionary definition or 'Since the dawn of time'","summary instead of analysis"], ask:["What is the exact prompt, and how long must it be?"], role:"a writing tutor and college essay coach"},
  {id:"text:academic-writing", kind:"text", when:/\b(abstract|lit(erature)? review|dissertation|methodology|journal|thesis (draft|committee)|my thesis|research paper|manuscript|papers?\b[\s\S]{0,40}\b(synthes\w*|contradict|disagree))\b/i, unless:/\bthesis statement\b/i, add:["Organize sources by theme or argument, not one paper at a time.","Show where studies agree, disagree, and why, such as different methods or samples.","Hedge claims to what the evidence supports.","Never invent citations or results; mark anything needing a source.","Respect stated word limits exactly and report the final count."], avoid:["inflated claims of novelty","a list of summaries with no synthesis"], ask:["What is the field and the target venue or committee?"], role:"an academic writing advisor and journal reviewer"},
  {id:"text:study-plan", kind:"text", when:/\b(study (schedule|plan|timetable)|(exam|test|final)s? (is )?in \d+|cram\w*|havent studied|haven'?t studied|prep(are)? for the (sat|act|gre|gmat|mcat|lsat))\b|\b(sat|act|gre|gmat|mcat|lsat)\b[\s\S]{0,40}\b(schedule|plan|weeks?)\b/i, add:["Work backward from the exam date, starting with a practice test to find weak areas.","Spend most time on the highest-weight and weakest topics.","Use active recall and spaced repetition instead of rereading.","Lay it out day by day or week by week with specific tasks and time blocks.","Keep the last day light and protect sleep before the exam."], avoid:["equal time on every topic","plans with no rest"], ask:["How many hours a day can you study, and which topics are weakest?"], role:"an academic coach"},
  {id:"text:study-materials", kind:"text", when:/\b(study guide|flash ?cards?|practice (questions|problems|tests?|quiz)|review sheet|study notes|cheat sheet|quiz me|exam questions|vocab(ulary)? (list|words)|sat words)\b/i, add:["Organize by topic with a short summary at the end of each section.","Write questions that test understanding and application, not only definitions.","Mix formats: short answer, multiple choice with plausible wrong options, and one applied scenario.","Put answers with short explanations after all the questions.","Flag commonly confused pairs and how to tell them apart."], avoid:["trick questions","copying lecture notes without condensing them"], ask:["What topics will the exam cover, and what format are its questions?"], role:"an experienced teacher who writes exam prep materials"},
  {id:"text:language-learning", kind:"text", when:/\b(learn\w*|practi[cs]e|speak|sentences?|grammar|tutor|fluent|phrases)\b[\s\S]{0,60}\b(spanish|french|italian|german|japanese|portuguese|mandarin|chinese|korean|hebrew|arabic|russian)\b|\b(spanish|french|italian|german|japanese|portuguese|mandarin|chinese|korean|hebrew|arabic|russian) (sentences?|grammar|phrases|lessons?|verbs?|words)\b|\b(ser (and|vs\.?) estar|conjugat\w*|subjunctive)\b/i, add:["Show the corrected sentence first, then the rule behind the mistake in one or two lines.","Give contrasting example pairs that isolate the rule.","Note formal versus informal forms and pronunciation where relevant.","For travel goals, prioritize high-frequency phrases and listening practice over grammar tables."], avoid:["long grammar lectures before examples"], ask:["What is your current level, and what do you need the language for?"], role:"a friendly, experienced language tutor"},
  {id:"text:workout-plan", kind:"text", when:/\b(workouts?|work out (plan|routine)|start(ed)? working out|working out again|exercise (plan|routine|program)|training (plan|split|program)|workout split|\d[- ]day (a week )?split|lifting|strength training|get stronger|build(ing)? muscle|couch to 5k|running plan)\b/i, add:["Give a weekly schedule table with sets, reps and rest times.","Include a short warm-up and a progression rule, such as add reps, then weight.","Offer an easier and a harder version of each exercise, plus swaps for stated injuries.","Give one form cue per exercise.","Say to stop on sharp pain and check with a doctor about existing conditions."], avoid:["advanced exercises for beginners without explanation"], ask:["What equipment, how many days and minutes, and any injuries?"], role:"a certified strength and conditioning coach"},
  {id:"text:meal-plan", kind:"text", when:/\b(meal (plan|prep|planning)|plan (my )?(meals|dinners)|week of (new )?(dinners|meals)|\d+ ?g(rams)? (of )?protein|calories|macros)\b|\bdinners?\b[\s\S]{0,40}\bweek\b/i, add:["Give a seven-day table plus one grocery list grouped by store section.","Reuse ingredients across meals to cut cost and waste, and batch-cook where possible.","List prep time per meal and which days to cook ahead.","Show protein or calories per day when the person gave a target.","Follow stated diets, allergies and budget exactly."], avoid:["specialty ingredients used only once","long recipes for people who dislike cooking"], ask:["Any dietary restrictions, a budget, and how much time to cook?"], role:"a practical registered dietitian who cooks at home"},
  {id:"text:recipe-help", kind:"text", when:/\b(recipes?|cups? (of |to )|to grams|substitut\w*|buttermilk|halv(e|ing)|double (the|a|this) recipe|sourdough|baking|bake)\b/i, unless:/\bmeal (plan|prep)\b/i, add:["Give dry ingredients in grams per ingredient, since a cup of flour and a cup of sugar weigh differently.","For substitutions, give the ratio and how texture or flavor will change.","When scaling, turn awkward fractions into easy measures like tablespoons and teaspoons.","Write steps in order with times, temperatures and visual doneness cues."], avoid:["one generic cup-to-gram number for every ingredient"], ask:["Which exact ingredients and amounts are you working with?"], role:"an experienced recipe developer"},
  {id:"text:travel-itinerary", kind:"text", when:/\b(itinerar\w*|road ?trip|trip to|vacation|\d+[- ]days? (trip|in)|plan (a|my|our) trip|honeymoon)\b/i, unless:/\b(packing list|what to pack|playlist|polic(y|ies))\b/i, add:["Plan day by day with morning, afternoon and evening, grouped by area to cut transit.","Give realistic travel times between stops and leave slack each day.","Note which places need advance booking or close on certain days.","Give rough cost ranges marked as estimates, plus one rainy-day alternative.","Remind them to check hours, prices and seasonal closures before going."], avoid:["cramming too many stops into one day"], ask:["What dates, budget and pace, and what do you most enjoy?"], role:"a seasoned travel planner"},
  {id:"text:packing-list", kind:"text", when:/\b(packing list|what (to|should i) pack|pack for)\b/i, add:["Group items by category: clothing, gear, toiletries, documents, electronics, and kids if relevant.","Scale clothing to trip length and weather, with layers for cold.","Add a short 'easy to forget' section.","Use a checkbox list unless another format is requested."], avoid:["items the trip type doesn't need"], ask:["Where, how long, what weather, and who is coming?"], role:"an experienced travel and outdoor guide"},
  {id:"text:budget", kind:"text", when:/\b(monthly budget|make a budget|build (me )?a budget|household budget|wedding budget|budget for|spending plan|50\/30\/20)\b|\bsplit\b[\s\S]{0,40}\b(rent|bill|check|costs?|expenses|utilities)\b/i, unless:/\b(app|stack|code)\b/i, add:["Start from take-home pay, then fixed costs, variable costs, savings and debt.","Show a table with categories, amounts and percent of the total.","Include emergency savings and irregular costs like yearly bills.","For shared costs, offer two fair methods, like equal or by room size; shares must sum exactly.","Point out the two or three biggest levers for saving."], avoid:["shaming spending choices"], ask:["What is your monthly take-home pay and your biggest fixed costs?"], role:"a practical personal finance coach"},
  {id:"text:money-math-explainer", kind:"text", when:/\b(loans?|mortgage|amortiz\w*|apr|interest (rate|rates)|compound interest|refinanc\w*|tax brackets?|401\(?k\)?|ira|roth|monthly payment|electric bill)\b/i, add:["Show the formula, the inputs and the result, and say what is rounded.","Add a small table, such as the first payments or total interest over the term.","Define each term, like APR or principal, in one plain sentence.","List the factors that decide which option fits, and which way each points.","Say what depends on personal details and when a tax or financial professional should check."], avoid:["telling them exactly what to buy or invest in"], ask:["What are the exact numbers: amount, rate, term, and any fees?"], role:"a clear-explaining financial educator"},
  {id:"text:apology", kind:"text", when:/\b(apolog\w*|sorry (text|message|note|email)|say sorry|flak(e|ed)|i messed up|my fault|make it up to|i feel (awful|terrible|bad)|(she|he|they)('?s|'?re| is| are) (annoyed|upset|mad))\b/i, add:["Name what you did specifically and own it, with no 'if anyone was offended'.","Acknowledge the impact on them in one sentence.","Give at most one line of context, not a list of excuses.","Say what you'll do differently or offer a concrete make-up.","Match length to the channel: a text stays a few lines."], avoid:["'sorry, but' that shifts blame","over-apologizing that asks them to comfort you"], ask:["What exactly happened, and what do you want to happen next?"], role:"an emotionally intelligent communication coach"},
  {id:"text:breakup", kind:"text", when:/\b(break ?up (text|message|letter|email)|break up with|breaking up with|end (things|it) with|ending (things|it|the relationship) with|dump(ing)? (him|her|them))\b/i, add:["Say clearly in the first lines that the relationship is over, with no ambiguity.","Use 'I' statements about the decision instead of listing their faults.","Keep it short, kind and final; don't invite a negotiation.","If they have been controlling, keep it brief, skip reasons, and plan support from a trusted person."], avoid:["'maybe someday' lines that leave the door open","blame or a list of grievances"], ask:["Do you want any chance of staying friends, or a clean break?"], role:"a direct but kind relationship counselor"},
  {id:"text:difficult-conversation", kind:"text", when:/\b(difficult|hard|awkward|tough) (conversation|talk)\b|\b(talk(ing)? to|tell|approach|confront|respond to) my (dad|mom|parents|roommate|coworker|co-worker|friend|partner|boss)\b|\b(what to (actually )?say|talking points)\b[\s\S]{0,80}\b(roommate|dad|mom|parents|coworker|friend)\b|\b(roommate|coworker|co-worker)\b[\s\S]{0,40}\bkeeps\b|\bbring (this|it) up\b|\bpassive[- ]aggressive\b|\bexplain to my (dad|mom|parents|family)\b/i, unless:/\b(raise|resign\w*|break ?up)\b/i, add:["Open by naming the shared goal or care before the issue.","Describe the specific behavior and its effect, without labels or 'always' and 'never'.","Make one clear request, then invite their side with an open question.","Prepare calm replies to the two most likely pushbacks.","Give word-for-word opening lines, then flexible talking points."], avoid:["ambush timing, like in front of others","bringing up every past issue at once"], ask:["What outcome would count as a win for you?"], role:"a family and workplace mediator"},
  {id:"text:creative-writing", kind:"text", when:/\b(bedtime story|short story|stor(y|ies) (about|for)|fairy tale|fiction|backstory|villain|poems?|poetry|haiku|limerick|sonnet|screenplay|dialogue scene)\b/i, unless:/\b(case study|success story|user stor(y|ies)|(what'?s|whats) (this|that) story)\b/i, add:["Start in the middle of a moment, with a character who wants something.","Use concrete sensory details instead of summary.","Give the main character a choice that drives the ending.","For bedtime stories, keep a gentle rhythm and a calm, reassuring ending.","For poems, keep one form and meter, and prefer slant rhyme over forced rhyme."], avoid:["stock phrases like 'little did they know'","a moral stated outright at the end"], ask:["Who is it for, and how long should it be?"], role:"a published fiction author and poet"},
  {id:"text:decision-help", kind:"text", when:/\b(decide|deciding|pick(ing)? between|choos(e|ing) between|compare|comparison|versus|pros and cons|which (one )?is better|should i (take|stay|buy|switch|go|refinance)|job offers?)\b/i, add:["List the person's top criteria and how much each matters.","Compare the options side by side in a table on those criteria.","Separate facts given from assumptions, and flag what is missing.","Name the deciding factor and give a recommendation, plus what would flip it.","Note which parts of the decision are hard to reverse."], avoid:["a balanced list with no conclusion","facts not in the provided material presented as certain"], ask:["What matters most to you in this choice?"], role:"a clear-headed decision coach"},
  {id:"text:summarize", kind:"text", when:/\b(summari[sz]\w*|summary|tl;?dr|key (points|takeaways)|main themes|recurring (complaint )?themes|top \d+ complaints|boil (it|this) down|executive summary|condense|show notes)\b/i, unless:/\b(meeting (notes|recap)|investor update)\b/i, add:["Lead with a two- or three-sentence bottom line, then supporting points.","Group points by theme and say roughly how often each comes up.","Point to the section, page or quote behind each key claim so it can be checked.","Separate what the source says from interpretation, and note gaps.","Fit length and vocabulary to the stated audience."], avoid:["adding facts that are not in the source","a section-by-section retelling"], ask:["Who will read the summary, and what will they decide with it?"], role:"an analyst who writes executive briefings"},
  {id:"text:legal-document", kind:"text", when:/\b(contracts?|clauses?|nda|non-?compete|arbitration|leases?|indemnif\w*|living trust|cease and desist|disclaimer|terms of service|rent (increase|hike)|raised (the |my )?rent|draft(ing)? a will|withdraw\w* from (their|the|a) case)\b/i, add:["Quote the exact clause, then explain in plain words what it requires, of whom and when.","Flag unusual or one-sided terms and what is more typical.","List questions to ask or changes to request before signing.","When drafting, use defined terms consistently and bracket wording that depends on jurisdiction.","Say it is general information, and recommend a licensed lawyer for high-stakes decisions."], avoid:["guessing what local law says without flagging it","advice on someone's specific case presented as certain"], ask:["Which country or state applies?"], role:"a contracts lawyer explaining and drafting for a client"},
  {id:"text:medical-explainer", kind:"text", when:/\b(lab (results?|work)|blood (test|work|pressure)|cholesterol|discharge (papers|summary)|diagnos\w*|hypertrophy|symptoms?|asthma|medications?|dosage|vomit\w*|throwing up|doctor (said|says|talked)|vet)\b/i, add:["Explain each term and value in plain words, including what the normal range means.","Say which findings are common and mild and which need prompt attention.","List the specific warning signs that mean call a doctor or vet now.","Suggest three questions to ask at the next appointment.","Frame it as general information to discuss with their clinician, not a diagnosis."], avoid:["alarming worst cases without context","telling them to change medication"], ask:["Can you paste the exact wording or numbers from the report?"], role:"a clear-speaking physician explaining results to a patient"},
  {id:"text:incident-postmortem", kind:"text", when:/\b(post-?mortems?|incident (report|review)|outages?|root cause|rca|runbook)\b/i, unless:/\b(internet provider|isp)\b/i, add:["Use sections: summary, impact, timeline with timestamps, root cause, contributing factors, what went well, action items.","Keep it blameless: describe systems and decisions, not people's mistakes.","Quantify impact: duration, users affected, errors or revenue.","Separate the trigger from the underlying root cause.","Make each action item specific, owned, dated and linked to a ticket."], avoid:["vague action items like 'be more careful'"], ask:["Do you have the timeline with timestamps and the impact numbers?"], role:"a site reliability engineer who runs blameless postmortems"},
  {id:"text:investor-update", kind:"text", when:/\binvestor (update|email|letter)s?\b|\b(update|email) (to|for) (our |my )?investors\b|\b(pitch(ing)? investors|pitch deck)\b/i, add:["Open with three to five headline metrics versus last period and plan.","Use sections: highlights, lowlights, metrics, cash and runway, asks.","Report bad news plainly, with the plan to fix it.","Tie every claim to a number the reader can check.","End with specific asks, like intros, hires or advice."], avoid:["jargon and hype","hiding misses"], ask:["What are this period's key numbers versus plan?"], role:"a startup CFO who writes investor updates"},
  {id:"text:release-notes", kind:"text", when:/\b(release notes|patch notes|changelog|what'?s new|update announcement|feature announcement|new feature|announcing (our|the) (app'?s )?new)\b/i, add:["Lead with user-visible changes and benefits, grouped as new, improved and fixed.","Write each item as what the user can now do, in plain words, not commit messages.","Drop internal refactors unless users will notice them.","Put breaking changes and required actions at the top."], avoid:["claims the update doesn't deliver","internal ticket numbers"], ask:["Who reads these, and which change matters most to them?"], role:"a product marketing manager"},
  {id:"text:interview-prep", kind:"text", when:/\b(job interview|interview (prep|questions|tomorrow|for)|final round|mock interview|behavio(u)?ral questions|practice (a )?(job )?interview|interview is)\b/i, unless:/\b(transcripts?|recordings?|recorded|podcast|city council candidate|follow[- ]?up|thank[- ]you (note|email))\b/i, add:["List likely questions for this specific role, including behavioral ones.","Coach answers in STAR form, with a number in the result where possible.","Prepare two or three thoughtful questions to ask the interviewer.","For mock interviews, ask one question at a time and give feedback after each answer."], avoid:["memorized-sounding scripts"], ask:["What is the role and company, and which round is it?"], role:"an experienced hiring manager and interview coach"},
  {id:"text:grant-writing", kind:"text", when:/\b(grants?|funders?|need statement|program description)\b/i, add:["Answer the funder's exact question in the first sentence, using their wording.","Back need claims with specific data and cite the source.","State outcomes as measurable targets with a timeline.","Stay within the word or character limit and report the final count."], avoid:["vague mission language with no numbers"], ask:["What is the exact question and limit from the funder?"], role:"an experienced grant writer"},
  {id:"text:rubric-lesson-plan", kind:"text", when:/\b(rubrics?|lesson plans?|state standards|curriculum|my students|mixed[- ]level|unit plan)\b/i, add:["Give each criterion three or four performance levels with observable descriptors.","Make points add up exactly to the stated total and show the math.","Write level descriptions in student-friendly language.","For lessons, include objective, warm-up, guided practice, support and extension for different levels, and an exit check."], avoid:["vague descriptors like 'good' or 'excellent' with no detail"], ask:["What grade level, and what total points or class length?"], role:"an experienced classroom teacher and curriculum designer"},
  {id:"text:word-limit", kind:"text", when:/\b(\d+[- ]?(words?|characters?|chars?) (limit|max|or less|or fewer)|word (limit|count)|character limit|tighten\w*|too long|cut (it |this )?down|shorten|shrink|under \d+ (words|characters|seconds|minutes)|exactly \d+ words)\b/i, add:["Count words or characters and state the final count; stay at or under the limit.","Cut filler, hedges and repeated ideas before cutting content.","Keep the key facts, numbers and main claim.","Keep the author's voice and any sentences they asked to keep."], avoid:["dropping the main point to hit the count"], ask:["What is the exact limit, and is anything off-limits to cut?"], role:"a sharp-eyed editor"},
  {id:"text:rewrite-polish", kind:"text", when:/\b(polish\w*|punch (it |this |them )?up|rewrite|reword|sound (less|more)|less like (chatgpt|ai|a robot)|like a robot|proofread|fix (my|the) grammar|grammar is not)\b/i, add:["Keep the meaning and any lines the person asked to keep word for word.","Use plain, specific words and cut clichés and filler.","Vary sentence length and use contractions for a natural voice.","List the main changes briefly after the rewrite."], avoid:["AI-sounding words like delve, tapestry, elevate, seamless","changing the facts"], ask:["Who will read it, and what tone should it have?"], role:"a skilled line editor"},
  {id:"text:honest-critique", kind:"text", when:/\b(brutally honest|be honest|tell me honestly|poke (as many )?holes|devil'?s advocate|tear (it|this) apart|critique|what'?s not working|is (this|it) (any )?good|garbage)\b/i, add:["Lead with the biggest problems ranked by impact, not a pile of small nits.","Point to the exact passage for each problem and suggest a concrete fix.","Name what genuinely works, briefly, so it is kept.","Give a clear verdict instead of softening it into vagueness."], avoid:["empty praise","rewriting everything instead of critiquing"], ask:["Who is the audience, and what is the goal of the piece?"], role:"a demanding but fair editor"},
  {id:"text:community-rules", kind:"text", when:/\b(server rules|discord|rules for|house rules|community guidelines|moderation policy|code of conduct|ground rules|side bet)\b/i, add:["Number the rules, each short and stated as a clear do or don't.","Give one concrete example for any rule people tend to argue about.","State consequences as escalating steps, like warning, timeout, ban.","Say how disputes are decided and by whom."], avoid:["vague rules like 'be cool'","rules nobody will enforce"], ask:["What problems keep coming up that the rules must settle?"], role:"an experienced community moderator"},
  {id:"text:event-planning", kind:"text", when:/\b(birthday party|party (theme|planning|ideas|games)|plan(ning)? (a|the|my|her|his) (\w+ )?party|baby shower|bridal shower|day[- ]of timeline|wedding (day )?timeline|event plan|birthday theme|theme for|\d+(st|nd|rd|th) birthday)\b/i, unless:/\b(toasts?|speech|vows?)\b/i, add:["Give a countdown timeline with what to do each week before the event.","Add a checklist grouped by invites, food, decor, activities and supplies.","Suggest activities with timing that fit the guests' ages.","Build in buffer time and a backup for weather or delays."], avoid:["schedules with no slack between parts"], ask:["How many guests, what budget, and indoors or outdoors?"], role:"an experienced event planner"},
  {id:"text:code-debug", kind:"text", when:/\b(errors?|exceptions?|bugs?|traceback|keyerror|indexerror|typeerror|null pointer|(script|code|function|query|formula) (is )?(not working|doesn'?t work)|fires immediately|race condition|duplicate rows|runs one extra)\b/i, unless:/\b(grammar|spelling|essay|break ?up|relationship|eulog\w*)\b/i, add:["Explain the root cause first in one or two sentences, pointing at the exact line.","Give the minimal fix in a code block before any wider refactor.","Show how to confirm the fix with a small test case.","Mention one related edge case the same pattern could cause."], avoid:["rewriting the whole program when a one-line fix works"], ask:["Can you paste the full error message and the code around it?"], role:"a senior software engineer who debugs patiently"},
  {id:"text:code-write", kind:"text", when:/\b(python|javascript|typescript|sql|regex|bash|powershell|google sheets formula|excel formula)\b|\bwrite (me )?(a |some )?(code|script|function|query)\b/i, add:["State the language, version and any libraries, preferring the standard library.","Handle edge cases like empty input, bad data and duplicates.","Include a short usage example with sample input and expected output.","Comment only the non-obvious parts and keep it runnable as is."], avoid:["placeholder code that doesn't run"], ask:["What does the input data look like, with a sample?"], role:"a senior software engineer"},
  {id:"text:comedy", kind:"text", when:/\b(jokes?|roast me|comedy|stand-?up|my set|puns?|punchlines?|funny (opener|opening|line|one-?liner)s?)\b/i, add:["Keep setups short and put the funniest word at the very end.","Use specific, concrete details instead of generic ones.","Offer a few variations of each punchline.","Aim jokes at situations and the speaker, not the audience or vulnerable groups."], avoid:["explaining the joke","overused openers"], ask:["Who is the audience, and how edgy can it be?"], role:"a stand-up comedy writer"},
  {id:"text:news-explainer", kind:"text", when:/\b(what'?s (going on|the deal|happening) with|everyone'?s (talking|sharing)|everyones (talking|sharing)|in the news|stock market (dropped|fell|rose|crashed)|tariffs?|interest rates? this (week|month)|the fed)\b/i, add:["Say what you know as of your knowledge cutoff and that newer events may change it.","Separate confirmed facts from speculation and opinion.","Explain why it matters to an ordinary person with two or three concrete effects.","Recommend a current, reliable source for anything time-sensitive."], avoid:["presenting old information as current","unsourced numbers"], ask:["Can you paste a headline or link so I know which story you mean?"], role:"a careful news explainer"},
  {id:"text:data-summary", kind:"text", when:/\b(dataset|spreadsheet|csv|cohort|retention|churn|a\/b test|conversion|kpis?|dashboard|statistically significant|significance|survey (results|answers|data))\b/i, unless:/\b(script|keyerror|code|function)\b/i, add:["Lead with the headline finding and what it means for a decision.","Give three to five key numbers, each compared to a baseline.","State caveats: sample size, missing data, and what the data can't show.","Use only the data provided and mark any assumption clearly.","For tests, report the effect size with a confidence interval, not only a p-value."], avoid:["inventing figures not in the data","methodology detail the audience didn't ask for"], ask:["Who will read this, and what decision does it support?"], role:"a senior data analyst who briefs executives"},
  {id:"text:troubleshoot-fix", kind:"text", when:/\b(keeps (dying|wobbling|happening|breaking)|why (is|are|does|do) my|turning yellow|stopped (bubbling|working)|troubleshoot\w*|how (do i|to) fix|steps to (fix|change|replace)|wobbl\w*|flat (bike )?tire)\b/i, unless:/\b(code|script|python|javascript|sql|function)\b/i, add:["List the most likely causes in order, with a quick check for each.","Give numbered fix steps, one action each, with what you should see after.","List tools or materials needed up front.","Say when to stop and get a professional, a vet or a repair shop."], avoid:["many causes with no order of likelihood"], ask:["What exactly happens, and what have you already tried?"], role:"a patient hands-on troubleshooter"},
  {id:"text:scam-check", kind:"text", when:/\b(scam|phishing|is (this|it) (real|legit)|suspicious (email|text|call|message)|ssn|social security number)\b/i, add:["List the specific red flags, like urgency, requests for ID numbers, or odd links.","Advise contacting the organization through its official website or number, not the message.","Give steps if information was already shared: bank, credit freeze, official fraud report."], avoid:["replying to or calling the number in the message"], ask:["Did you already click a link or share any information?"], role:"a fraud prevention specialist"},
  {id:"text:internal-announcement", kind:"text", when:/\b(layoffs?|all[- ]hands|(company|staff|internal|policy) memo|memo (to|explaining|about|for)|company[- ]wide|to the whole (team|company)|maternity leave|parental leave|new (pto|data retention|remote work|password) polic\w*|(pto|password) policy)\b/i, add:["State the news and what it means for the reader in the first two sentences.","Answer the obvious questions: what changes, when, who is affected, who to ask.","Use plain, human words instead of corporate euphemisms.","For bad news, be direct and respectful and give concrete support details."], avoid:["euphemisms like 'rightsizing'","burying the change under background"], ask:["What exactly changes, from when, and who answers questions?"], role:"an experienced internal communications lead"},
  {id:"text:fundraising-appeal", kind:"text", when:/\b(donors?|donation|fundrais\w*|volunteers?|gofundme|nonprofit|non-profit|church bulletin|food (bank|pantry))\b/i, add:["Lead with one concrete person or moment, not statistics.","Make a specific ask: an amount, shift or date, and exactly how to sign up.","Show what each contribution achieves in concrete terms.","For thank-yous, name the gift's specific impact and don't ask for more."], avoid:["guilt or desperation","vague 'any help is appreciated' asks"], ask:["What exactly do you need, how much or how many, and by when?"], role:"a nonprofit development director"},
  {id:"text:checklist-steps", kind:"text", when:/\b(checklist|numbered steps|step[- ]by[- ]step|turn (this|it) into (clean |quick )?(steps|bullets|a checklist)|instructions|how-?to|faq)\b/i, add:["Number the steps, one action per step, each starting with a verb.","Put safety warnings and critical steps first and mark them clearly.","Keep each line short enough to read at a glance.","Group steps under short headings when there are more than about ten."], avoid:["paragraphs","steps that combine several actions"], ask:["Who will follow this, and where will they read it?"], role:"a technical writer who writes for busy readers"},
  {id:"text:tech-design-doc", kind:"text", when:/\b(design doc|technical design|architecture|migrat(e|ing|ion) (our|the|from)|read replicas?|rfc|rate limiter|webhook support)\b/i, add:["Use sections: context, goals and non-goals, design, alternatives, risks, rollout and rollback, open questions.","Spell out failure modes and how each is detected and handled.","For migrations, phase the rollout with a tested rollback at each step.","List assumptions and the numbers they rest on, like traffic and data size."], avoid:["designs with no rollback plan"], ask:["What scale, constraints and deadlines does this need to meet?"], role:"a staff software engineer"},
  {id:"text:code-review", kind:"text", when:/\breview (this|my|our) (python |js |javascript |terraform |sql )?(code|function|class|module|script|pull request|pr|hcl)\b|\bcode review\b|\bsecurity (issues|review|holes)\b|\bfeedback not a rewrite\b/i, add:["Rank findings by severity: bugs and security first, then correctness, then style.","Cite the exact line for each finding, explain the risk, and show the smallest fix.","Say briefly what is already fine so it isn't changed.","Respect the request scope: give feedback, not a full rewrite, unless asked."], avoid:["style nitpicks presented as bugs"], ask:["What does this code need to handle, and what runtime or version does it use?"], role:"a senior engineer doing a careful code review"},
  {id:"text:fact-check", kind:"text", when:/\b(fact[- ]?check\w*|check (whether|if) (these|this|the|our) claims?|verify (these|this|the) claims?|claims? (we|i) can (actually )?(say|make))\b/i, add:["Check each claim separately and label it supported, contradicted, or not found in the sources.","Cite the exact source passage for each verdict.","Use only the provided sources unless asked, and label any outside knowledge.","Suggest a corrected wording for each claim that fails."], avoid:["judging a claim true because it sounds plausible"], ask:["Which sources or rules should the claims be checked against?"], role:"a meticulous fact-checker"},
  {id:"text:ask-a-favor", kind:"text", when:/\b(cover (my|a) shift|swap (my |a )?(\w+ )?shifts?|switch (my )?(shifts?|sessions?|times?)|switch to (evenings|mornings)|ask(ing)? (for )?(a )?favou?r|(linkedin )?recommendation from|reference from)\b/i, add:["Put the ask in the first line, with the exact date or task.","Give one sentence of context, not a long justification.","Make it easy to say no, and offer something in return or flexibility.","For recommendations, include a few bullet points they could mention to save them time."], avoid:["guilt-tripping","over-apologizing"], ask:["What exactly do you need, and what can you offer in return?"], role:"a socially savvy coworker and friend"},
  {id:"text:out-of-office", kind:"text", when:/\b(out of (the )?office|ooo|auto-?reply|away message)\b/i, add:["Give the dates away and the return date.","Name who to contact for urgent matters, with their email.","Give no personal reason unless the person wants to share one.","Keep it under about 60 words."], avoid:["promising replies on specific dates while away"], ask:["Who should people contact while you're away?"], role:"an executive assistant"},
  {id:"text:rejection-email", kind:"text", when:/\brejection (email|letter|note|template)s?\b|\b(not accepting|turn(ing)? down|declin\w*) (the |their |these |a )?(proposals?|applicants?|candidates?|submissions?|speakers?)\b/i, add:["State the decision clearly in the first two sentences.","Thank them for something specific about their application or time.","Give one honest reason or point of context if possible, without debate.","Offer a real next step, like future calls or feedback on request, only if it exists."], avoid:["false hope","'unfortunately we received many strong applications' as the only content"], ask:["Can you share anything specific about why, or invite them to reapply?"], role:"a thoughtful recruiter and program organizer"},
  {id:"text:grocery-list", kind:"text", when:/\b(grocery|shopping) list\b|\bby aisle\b/i, add:["Group items by store section in a typical walking order: produce, bakery, meat, dairy, frozen, pantry.","Merge duplicates and total the quantities for each item.","Flag items people often forget, like staples used in several recipes."], avoid:["changing items the person listed"], ask:["Which store do you shop at?"], role:"an organized home cook"},
  {id:"text:shift-handoff", kind:"text", when:/\b(hand-?off|handover|shift (notes|report)|sbar|next (nurse|shift))\b/i, add:["Use SBAR for each patient: situation, background, assessment, recommendation.","Put time-sensitive items first: meds due, pending labs, fall or allergy risks.","Keep each patient to a few scannable bullets.","Keep all clinical details exactly as given; don't add or infer anything."], avoid:["dropping a detail to make it shorter"], ask:["Are there any pending results or scheduled meds the next shift must act on?"], role:"an experienced charge nurse"},
  {id:"text:chore-chart", kind:"text", when:/\bchore (chart|list|schedule|ideas)\b|\bchores for\b/i, add:["Assign age-appropriate tasks, with a clear definition of done for each.","Rotate shared or disliked chores weekly so it feels fair.","Lay it out as a table by day and child.","Add a simple reward or points system tied to finishing, not perfection."], avoid:["tasks unsafe for the child's age"], ask:["How old are the kids, and are there chores they fight over?"], role:"a practical parenting coach"},
  {id:"text:style-match", kind:"text", when:/\b(i (love|loved|like|really like|liked) (how|the way)|the way (they|she|he|it|my \w+|the host|this)|used to (write|give|tell|explain|say)|whose \w+ (updates|emails|captions|descriptions)|explains? (stuff|things|complicated stuff|storm\w*|complex topics) (so|in|without)|in that (kind of )?(style|tone|voice|way)|that (tone|energy|structure|style|format|voice) for|kind of style|there'?s a (style|way))\b/i, add:["First name the concrete traits of the described style: structure, sentence length, tone, what it leaves out.","Apply those traits to the person's own content and topic.","Imitate the technique, not the wording, of any named source.","Keep the person's facts as given; don't invent details to fit the style."], avoid:["copying a real writer's sentences","drifting back to a generic tone halfway through"], ask:["Can you paste a short example of the style you mean?"], role:"a versatile ghostwriter who can match any voice"},
  {id:"text:presentation-prep", kind:"text", when:/\b(present(ing)? (the |our |my )?(quarterly )?(numbers|results|findings)|q&a|slide deck|google slides|powerpoint|what to (actually )?say on the slide|pitch (script|opening)|script for my seed pitch|demo video script|talk track)\b/i, add:["Give each slide one headline that states the takeaway as a full sentence.","Write speaker notes in spoken language, at roughly 130 to 150 words per minute.","List the five hardest likely questions with short, honest answers.","For numbers, say what changed, why, and what happens next, in that order."], avoid:["reading dense slides aloud","more than one main point per slide"], ask:["Who is the audience, and how many minutes do you have?"], role:"an executive presentation coach"},
  {id:"text:pet-training", kind:"text", when:/\b(puppy|puppies|dog training|crate training|potty training|house ?training|leash training)\b/i, add:["Lay it out week by week with two or three focus skills per week.","Use reward-based training in short sessions of a few minutes, several times a day.","Give a potty schedule tied to waking, eating, play and naps, adjusted for age.","Say what to do after an accident: clean with enzyme cleaner, no punishment."], avoid:["punishment-based methods","long sessions for young puppies"], ask:["How old is the puppy, and what is your daily schedule?"], role:"a certified dog trainer"},
  {id:"text:gardening", kind:"text", when:/\b(planting schedule|plant (tomatoes|seeds|veg\w*)|vegetable garden|zone \d{1,2}[ab]?|last frost|seed starting)\b/i, add:["Time planting from the local last and first frost dates, not fixed calendar dates.","Separate cool-season crops from warm-season crops and say which tolerate frost.","Use soil temperature and nighttime lows as the real go signal for warm crops.","Suggest a few easy, forgiving crops for beginners."], avoid:["one planting date for every region"], ask:["What is your growing zone or nearest town, and how much space do you have?"], role:"an experienced vegetable gardener"},
  {id:"video:product-turntable", kind:"video", when:/\b(rotat\w*|spin\w*|turntable|360|floats? and rotates?|revolv\w*)\b.{0,60}\b(products?|sneakers?|shoes?|bottles?|phones?|devices?|gadgets?|headphones|earbuds|airpods|smartwatch|pedestal|bouquet|prototype)\b|\b(products?|sneakers?|shoes?|bottles?|phones?|devices?|gadgets?|headphones|earbuds|airpods|smartwatch|bouquet|prototype)\b.{0,60}\b(rotat\w*|spin\w*|turntable|360|revolv\w*)\b|\bapple (ad|style|look|product)|product (reveal|launch look)/i, unless:/\b(perfume|fragrance|cologne)\b/i, add:["product centered on a seamless backdrop with a soft contact shadow beneath it","one slow, constant-speed rotation; camera locked off","a long soft key light plus a thin rim light tracing the edges","highlights gliding across surfaces and glass as it turns","shape, proportions and markings unchanged through the full turn"], avoid:["product warping or melting as it turns","duplicate products appearing","garbled logo or label text"], ask:["Plain white seamless, or a styled surface and colour mood?","Do you have a photo of the real product to start from?"]},
  {id:"video:car-reveal", kind:"video", when:/\b(cars?|suv|trucks?|vehicle|ev|sports car)\b.{0,60}\breveal\w*|\breveal\w*.{0,60}\b(cars?|suv|trucks?|vehicle)\b|headlights?.{0,50}\b(dark\w*|reveal\w*|garage|sweep\w*)|\bshowroom\b/i, add:["car emerging from near darkness as a light sweep travels along the body","long specular highlights tracing the body lines over glossy paint","low camera at headlight height, slow push-in or rising crane","haze in the air so the light beams are visible","ending on a clean three-quarter front view, held still"], avoid:["wheels or badge warping","body shape changing between frames","readable fake text on plates or signs"], ask:["What make, model and colour, and do you have a photo of it?"]},
  {id:"video:app-screen-demo", kind:"video", when:/\b(our|my) (app|startup|saas|dashboard)\b|\bapp (open|on screen|opening|dashboard)|\bscreen (turning on|lights up|unlock\w*)|face (recognition|unlock|id)|\blanding page\b.{0,60}\b(phone|laptop|screen|app)\b/i, add:["screen as a clean bright glow with simple shapes, ready for the real UI to be composited","device held naturally or on a clean desk, slight push-in","soft daylight, minimal background, shallow depth of field behind the device","fingers tapping and scrolling with natural timing"], avoid:["garbled text or invented UI on the screen","extra or merged fingers","screen glare hiding the display"], ask:["Will you composite your real app screens in afterwards, or should the screen stay abstract?"]},
  {id:"video:perfume-ad", kind:"video", when:/\b(perfume|fragrance|cologne|eau de)\b/i, add:["glass bottle with light refracting through the liquid and caustics on the surface below","one hard light from the side or behind, deep falloff into shadow","slow motion for any liquid, smoke, petals or fabric in the frame","slow push-in or gentle arc that ends resting on the bottle","bottle silhouette and cap identical in every frame"], avoid:["bottle shape warping","invented brand text on the label","busy props competing with the bottle"], ask:["What does the bottle look like (shape, glass and liquid colour), or do you have a photo?"]},
  {id:"video:jewelry-watch-macro", kind:"video", when:/\b(diamonds?|jewel(ry|lery)|necklace|earrings?|bracelet|engagement ring|wedding rings?|timepiece|wristwatch|(luxury|smart) ?watch(es)?|watch (face|gears?|case|movement|on|drops|rotating|ad))\b|戒指|手表/i, add:["macro lens, very shallow depth of field, focus on the facets or dial","small moving point lights making the stones sparkle as the angle changes","dark velvet or polished stone surface with soft reflections","watch hands and gears moving at a steady mechanical pace","very slow rotation or glide; tiny movements look large at macro scale"], avoid:["facets, numerals or hands warping","fingers merging with the piece","random engraved text"]},
  {id:"video:coffee-tea", kind:"video", when:/\b(coffee|espresso|latte|cappuccino|barista|pour[- ]over|matcha|tea (leaves|cup|ceremony|pour\w*|brand|commercial)|cup of tea)\b/i, add:["steam curling up, backlit against a darker background so it reads","liquid poured in one smooth continuous stream, crema or foam with visible texture","warm morning window light from one side","close angle at cup height, or locked top-down for latte art"], avoid:["cup or saucer changing shape","latte art pattern morphing randomly","liquid spilling over the rim"], ask:["Which moment: espresso pulling, latte art pour, or a finished cup with steam?"]},
  {id:"video:beer-pour", kind:"video", when:/\b(beers?|lager|pints?|taproom|brewery|ipa|stout|draft|draught)\b/i, unless:/\broot beer\b/i, add:["cold glass with condensation beads, backlit so the beer glows","streams of rising bubbles and a dense foam head forming","glass tilted at the tap, then straightened as the foam reaches the rim","dark bar background with warm bokeh from practical lights"], avoid:["foam overflowing endlessly","glass deforming","liquid level jumping between frames"]},
  {id:"video:spirits-cocktail", kind:"video", when:/\b(whiske?y|bourbon|scotch|rum|cognac|brandy|tequila|mezcal|gin|vodka|spirits|distiller\w*|cocktails?|bartender|mixolog\w*|martini|speakeasy bar)\b/i, add:["heavy crystal glass with a large clear ice cube, liquid glowing amber in backlight","slow-motion pour with the stream folding around the ice","low-key warm tungsten light, deep shadows, wood and brass textures","camera at glass height, slow push-in","garnish, citrus mist or smoke lit from behind so it glows"], avoid:["liquid level jumping","invented label text","hands with extra fingers on the bottle"]},
  {id:"video:food-hero", kind:"video", when:/\b(food|dish|burgers?|pizza|pasta|tacos?|steak|brisket|dessert|cheese pull|ramen|noodles|sushi|ice cream|chocolate sauce|drizzl\w*|spices|tasting menu|plating|plated|plate of|watermelon|sizzl\w*|cinnamon roll|cake slice|food truck)\b/i, unless:/\b(bread|sourdough|croissants?|loaf|bakery|dog food|pet food)\b/i, add:["macro close-up, shallow depth of field on the hero bite","backlight so steam and glistening sauce stand out against a darker background","one appetizing action in slow motion: pull, drizzle, slice or sizzle","neutral surface with few props, warm colour balance"], avoid:["food morphing into a different dish","plastic, over-glossy look","cutlery bending"], ask:["What exactly is the dish, and what is the one action (pour, slice, pull, sizzle)?"]},
  {id:"video:bakery-bread", kind:"video", when:/\b(bread|sourdough|croissants?|baker(y|ies)|loaf|loaves|pastr(y|ies)|baguette|dough)\b/i, add:["steam rising from the crust, backlit against the darker oven interior","deep golden crackled crust with a dusting of flour","tray or peel sliding out of the oven, or hands tearing it open to show the crumb","warm tungsten light with flour particles drifting in the air"], avoid:["bread changing shape as it moves","dough moving like liquid","extra fingers on kneading hands"]},
  {id:"video:chef-kitchen-action", kind:"video", when:/\b(chefs?|line cook|flamb\w*|wok|chopping|cooking (show|video|competition)|pan (flip|toss)|flipping a pan|tossing .{0,25}pan|pizza dough|kitchen prep|restaurant kitchen|busy kitchen|open kitchen|grill)\b/i, add:["food tossed from the pan in a clean arc, a brief orange flame flare","stainless kitchen with warm practicals and steam haze behind","hands and knife in sharp focus, quick confident movements","slow motion at the peak of the toss, real speed around it"], avoid:["food appearing or vanishing mid-air","knife passing through fingers","flames that never die down"]},
  {id:"video:real-estate-exterior", kind:"video", when:/\b(real estate|realtor|listing|zillow|property|condo|mansion|villa|house|home|farmhouse|estate)\b.{0,60}\b(drone|aerial|fly ?over|flying|exterior|from above|crane|rising)\b|\b(drone|aerial|fly ?over|flying (over|toward)|exterior)\b.{0,60}\b(house|home|property|listing|condo|mansion|villa|tower|estate)\b/i, unless:/\b(haunted|horror|spooky|halloween)\b/i, add:["smooth drone glide at steady speed, slowly descending toward the front entrance","golden hour or blue hour with warm interior lights glowing in the windows","vertical lines kept straight, no wide-angle bending of walls","landscaping and pool clean and still, sky soft and clear","no sudden turns, tilts or speed changes"], avoid:["building shape or windows changing as the camera moves","extra structures appearing","fisheye distortion"], ask:["Daytime, or dusk with the lights on?"]},
  {id:"video:interior-walkthrough", kind:"video", when:/\b(walk-?\s?through|glide through|steadicam glide|room to room|interior)\b.{0,80}\b(house|home|listing|kitchen|apartment|condo|rooms?|hotel|lobby|suite|gym|office|space)\b|\b(listing|real estate|realtor)\b.{0,80}\b(walk\w*|interior|kitchen|inside|rooms?)\b|\b(hotel|resort|infinity pool|lobby|suite)\b/i, add:["steady forward glide at walking pace, camera at chest height","bright natural window light balanced with the interior, windows not blown out","vertical lines straight, wide lens without fisheye bending","one continuous move through a doorway into the next space","tidy, styled rooms with warm accent lamps on"], avoid:["furniture appearing, vanishing or changing","walls warping","rooms that do not connect logically"], ask:["Which rooms or spaces, and in what order?"]},
  {id:"video:logo-sting", kind:"video", when:/\blogos?\b|\bstinger\b|\bbumper\b|\bmascot\b/i, add:["image-to-video from the real logo artwork, its exact shape kept","logo forming from light, particles or fog, settling at center within two seconds","dark or brand-colour background with one glow accent","final second held still on the finished logo"], avoid:["logo letters morphing or misspelled","extra symbols or text appearing","logo shape changing after it settles"], ask:["Do you have the logo as an image to start from?"]},
  {id:"video:channel-intro", kind:"video", when:/\b(channel|stream|show|podcast|youtube|twitch|series|vlog|gaming) (intro|opener|opening)\b|\bintro (clip|video|for|to) (my|our|the)\b|\bstream(er)? intro\b/i, add:["one punchy action that peaks within three seconds","bold silhouette and high contrast so it reads on a phone screen","ending on a calm, uncluttered area for the channel name","lighting and colour that match the channel's look"], avoid:["several competing actions","gibberish text on screens or signs"], ask:["Where will the channel name or logo go, and is there a sound or music sting?"]},
  {id:"video:animate-still", kind:"video", when:/\b(animate|animating|bring .{0,40} to life|comes? to life|i (drew|made|painted|illustrated)|made (a|an|this|my)|(my|our|the|this) (drawing|painting|illustration|artwork|cover art|album cover|key art|concept art|poster|comic|tarot|flash|splash page|storybook|invite art|packaging art|hero illustration)|still (photo|image)|product photo|(old|vintage|family) (photo|picture)s?|photo (into|to) (a )?video|image[- ]to[- ]video|midjourney)\b/i, add:["original art style, colours and composition kept exactly; only motion added","subtle layered motion: hair, cloth, smoke, light, particles, water","at most a gentle camera move: slow push-in or slight parallax","faces and silhouettes stable, same identity in every frame","for photos of people: blinks, breathing and a small head turn only"], avoid:["style drifting toward photorealism or a different art style","new objects or characters appearing","features being redrawn"], ask:["Which parts should move, and which must stay perfectly still?"]},
  {id:"video:loop-background", kind:"video", when:/\bloop(s|ing|able|ed)?\b|\bseamless(ly)? loop|screensaver|waiting room|visuali[sz]er|loading screen|\babstract (colou?rs?|shapes|background|motion|loop)|flowing (colorful |colourful )?shapes|(video|clip|lyric video|podcast'?s?|website|stream) background|background (video|clip|loop|visual)/i, add:["seamless loop: the last frame matches the first, motion at constant speed","locked-off camera so the loop point is invisible","slow, repeating motion: drifting, flowing, rippling or flickering","nothing entering or leaving the frame"], avoid:["sudden events or camera moves that break the loop","a visible jump at the loop point","flashing that tires the eye"], ask:["Will text or a person sit on top of it, and where?"]},
  {id:"video:rain-window", kind:"video", when:/\brain\w*\b.{0,40}\bwindows?\b|\bwindows?\b.{0,40}\brain\w*\b/i, add:["droplets and streaks on the glass in sharp focus, city lights as soft bokeh behind","locked-off camera, drops trickling down at natural speed","cool blue night tones with warm points of light","now and then a larger drop running down and merging with others"], avoid:["rain falling inside the room","droplets moving upward or sideways for no reason"]},
  {id:"video:candle-flame", kind:"video", when:/\bcandles?\b|candlelit|fireplace|campfire|bonfire|flickering flame|flame flicker\w*/i, unless:/\b(birthday|bday|b-day|blow\w* out)\b/i, add:["flame swaying gently and flickering naturally, never jumping","warm light pooling on nearby surfaces and falling off into darkness","locked-off camera or a very slow push-in","faint smoke wisp and glossy melted wax or glowing embers"], avoid:["flame duplicating or detaching from the wick","light brightness pulsing unnaturally"]},
  {id:"video:birthday-candles", kind:"video", when:/\b(birthday|bday|b-day)\b.{0,100}\b(candles?|cake)\b|\bblow\w* out\b.{0,30}\bcandles?|\bcandles?\b.{0,40}\bblow\w*/i, add:["warm candlelight on the face in a dimmed room","one breath and the flames go out, thin smoke curling up","family around the edges in soft focus, clapping hands","handheld home-video feel at the child's eye level"], avoid:["extra candles appearing","distorted faces or hands in the crowd","candles relighting"], ask:["Who is blowing out the candles (age and look), and do you have a photo?"]},
  {id:"video:pets", kind:"video", when:/\b(dogs?|pupp(y|ies)|cats?|kittens?|corgis?|golden retriever|husky|labrador|pets?)\b/i, unless:/\b(hot ?dogs?|logo|illustrat\w*|drawing|painting|mascot|jazz cat)\b/i, add:["camera low at the animal's eye level","backlight catching the edges of the fur","fast-shutter look when running: ears and fur bouncing, paws leaving the ground","one simple action from start to finish"], avoid:["extra legs or tails","breed or markings changing mid-shot","human-like facial expressions"], ask:["What breed, colour and size, or do you have a photo of the pet?"]},
  {id:"video:wildlife-doc", kind:"video", when:/\b(wildlife|safari|bears?|fox(es)?|wol(f|ves)|lions?|lioness|tigers?|eagles?|hawks?|herons?|owls?|hummingbirds?|whales?|dolphins?|deer|elk|monkeys?|herd|sea turtles?|hatchlings?|bees|birdwatching|pigeons?)\b/i, unless:/\b(logo|illustrat\w*|drawing|painting|papercraft|tarot|cartoon|anime|mascot|storybook)\b/i, add:["long telephoto lens from a distance, compressed soft background","natural light only, animal behaving naturally and unaware of the camera","slow tracking pan that keeps the animal framed","slow motion only for the key moment: dive, strike, breach, takeoff"], avoid:["anatomy errors in wings, legs or tails","human-like expressions","animals posing for the camera"]},
  {id:"video:aerial-landscape", kind:"video", when:/\b(drone|aerial|fly ?over|flyover|flythrough|fly-through|establishing shot|bird'?s[- ]eye|sweeping (shot|move)|over (the )?(mountains|valley|canyon|cliffs|ocean|lake|vineyard|coast))\b/i, unless:/\b(fpv|listing|real estate|realtor|zillow|house|condo|mansion|villa)\b/i, add:["slow drone push forward at steady altitude, horizon perfectly level","low sun with long shadows, mist or haze layering the depth","a foreground element passing beneath the camera to show speed and scale","one continuous move with a smooth start and finish"], avoid:["horizon tilting","terrain warping as the camera moves","cuts or jumps"]},
  {id:"video:time-lapse-nature", kind:"video", when:/time[- ]?lapse|\bbloom(s|ing)?\b|blossoming|unfurl\w*|\b(grow|grows|growing) from (a )?seed|seed to|\bsprout\w*|wilting|petals? (slowly )?open/i, unless:/\b(dress|gown|fabric|skirt)\b/i, add:["locked-off camera; only the subject changes over time","smooth, continuous progression with no sudden jumps","steady, even light through the whole change","plain dark or soft backdrop isolating the subject"], avoid:["the plant turning into a different species","camera drift","light flickering"], ask:["Fast like a real time-lapse, or slow and graceful?"]},
  {id:"video:storm-weather", kind:"video", when:/\b(storms?|stormy|thunder\w*|lightning|tornado(es)?|blizzard|hurricane|squall)\b/i, add:["heavy cloud structure rolling with visible depth and motion","lightning as brief flashes lighting the clouds from within","rain or spray streaks angled by the wind","wide, steady camera to show the scale of the weather"], avoid:["lightning bolts that stay on for seconds","rain falling straight down in strong wind"]},
  {id:"video:underwater", kind:"video", when:/\b(underwater|coral|reefs?|shipwreck|jellyfish|aquarium|fish tank|scuba|diver|dive school|kelp)\b/i, add:["light rays filtering down from the surface, floating particles in the water","slow drifting camera, no fast moves","colour fading to blue-green with distance","soft caustic light patterns rippling on surfaces"], avoid:["bubbles rising sideways or down","fish swimming backward or merging"]},
  {id:"video:space-scene", kind:"video", when:/\b(astronauts?|spacewalk|space station|spaceships?|spacecraft|nebula|outer space|in space|zero[- ]g|alien planet|orbit(ing)? (the )?earth)\b/i, add:["single hard sunlight, deep black shadows, no air haze in open space","slow, weightless motion; tethers and small objects drifting","planet large in frame for scale","stars faint or hidden when bright objects are exposed"], avoid:["smoke or flames billowing in vacuum","objects falling as if under gravity"]},
  {id:"video:car-driving", kind:"video", when:/\b(cars?|suvs?|trucks?|sedan|coupe|sports car|muscle car|mustang|vehicles?|ev|motorcycles?|bike)\b.{0,60}\b(driv\w*|road|highway|drift\w*|speed\w*|racing|burnout|cruis\w*|commercial|dealership|corner)\b/i, unless:/\b(reveal\w*|showroom|toy|model train)\b/i, add:["tracking shot from a camera car alongside, low to the road","wheels visibly turning, motion blur on the road and background","sky and lights gliding as reflections over the paint","road curving ahead with the vehicle leading the frame"], avoid:["wheels frozen or spinning backward","vehicle shape changing between frames","extra cars appearing from nowhere"], ask:["What make, model and colour?"]},
  {id:"video:action-chase-explosion", kind:"video", when:/\bchas(e|ed|es|ing)\b|\bpursuit\b|getaway|running (away )?from|being followed|\bexplo(sion|sions|de|des|ding)\b|fireball|\bblast\b/i, unless:/\b(ball|frisbee|toy mouse|tail|puppy|kitten|dogs?|cats?|explod\w* into|confetti|flowers|splash\w*)\b/i, add:["handheld or vehicle-mounted camera, tight framing, quick small corrections","background streaked with motion blur, the subject sharp","one clear beat per shot: near miss, swerve, leap or blast","fireballs rolling into thick black smoke, debris arcing outward","camera shake arriving a beat after any flash or impact"], avoid:["a confusing pile of cars or people","debris floating weightlessly","too many actions in one clip","gore"]},
  {id:"video:fight-combat", kind:"video", when:/\b(fight\w*|duel\w*|sparr\w*|boxing|boxers?|punch\w*|knock(ed)? ?out|martial arts|karate|taekwondo|fencing|swords? clash\w*|shadowbox\w*)\b/i, unless:/\b(fighter jet|cockpit|firefight\w*)\b/i, add:["readable choreography: one strike, one clear reaction","slow motion at the moment of impact, sweat or dust flying","medium-wide framing at a low angle so both fighters stay in frame","hard backlight through haze, faces half in shadow"], avoid:["limbs merging or bending wrongly","weapons bending or vanishing","gore"]},
  {id:"video:sports-highlight", kind:"video", when:/\b(dunk\w*|basketball|soccer|football|goal(ie|keeper)|penalty kick|sprint\w*|marathon|finish line|hockey|tennis|baseball|surf(ing|er)?|ski(er|ing)|snowboard\w*|bmx|athletes?|figure skat\w*|roller derby|game[- ]winning|sports (reel|highlight|commercial|brand|league|campaign))\b/i, add:["slow motion at the peak of the action, real speed just before","low angle looking up to make the athlete powerful","arena or sun backlight catching sweat, chalk and spray","crowd soft and dark in the background, faces not detailed"], avoid:["ball passing through hands or hoop","extra limbs","ball changing size"]},
  {id:"video:skateboarding", kind:"video", when:/\bskat(e|er|ers|eboard|eboarder|eboarding|ing|epark)\b|\bollie\b|kickflip|grind(ing|s)? (a )?(rail|curb|ledge)/i, unless:/\b(figure skat\w*|ice skat\w*|roller derby|roller skat\w*)\b/i, add:["low wide-angle follow cam running close behind the board","board staying under the feet through the trick, all four wheels landing together","rough concrete, rails and stairs with gritty urban texture","natural daylight or hard streetlight"], avoid:["board floating away from the feet","legs bending wrongly on landing"]},
  {id:"video:gym-fitness", kind:"video", when:/\b(gym|workout|work out|deadlift\w*|bench press|squats?|push-?ups?|battle ropes|treadmill|crossfit|box jump|personal train\w*|lifting weights|barbell|protein shake|fitness)\b/i, add:["hard side light or top light carving muscle definition","chalk dust and sweat catching the light","close on the strain at the hardest point of the rep","dark gym background with a few practical lights"], avoid:["weights bending, floating or passing through the body","extra fingers on the bar"]},
  {id:"video:music-performance", kind:"video", when:/\b(music video|concert|singers?|rapper|band|bands|on stage|stage lights|dj|guitar\w*|drummer|trumpet|choir|moshpit|mosh\w*|club lights|rave)\b/i, unless:/\babstract\b/i, add:["haze in the air so stage beams and spotlights show as shafts","strong backlight turning the performer into a silhouette at moments","camera slowly circling or dollying at chest height","hands and instrument shown in motion, fingers on strings or keys"], avoid:["mouth moving out of sync with the song","instruments with wrong numbers of strings or keys"], ask:["Should the performer lip-sync to your song, and do you have the audio?"]},
  {id:"video:dance", kind:"video", when:/\b(danc(e|er|ers|ing)|ballet|ballerina|pirouette|twirl\w*|en pointe)\b/i, unless:/\b(first dance|wedding)\b/i, add:["full body in frame for the whole movement, feet visible","fabric and hair following the spin with real momentum","single spotlight or soft window light against a dark background","slow motion at the peak of the turn or leap"], avoid:["limbs twisting unnaturally","the dancer duplicating","feet sliding on the floor"]},
  {id:"video:fashion-runway", kind:"video", when:/\b(runway|catwalk|fashion|editorial|lookbook|wind machine|model (walking|walks|standing|twirling|in a|struts?))\b/i, add:["fabric texture and movement clear, catching rim light","long lens from the end of the runway, background flattened and soft","steady stride, camera tracking backward at the model's pace","hard key light or flash-like strobes against a dark backdrop"], avoid:["garment changing colour or cut","legs merging mid-stride","face changing between frames"]},
  {id:"video:beauty-skincare", kind:"video", when:/\b(skincare|skin care|serum|lipstick|make-?up|beauty|cosmetics?|moisturi[sz]er|manicure|nail polish|shampoo|lotion)\b/i, add:["extreme macro of skin with real texture and fine pores","droplets or serum beading with crisp specular highlights","soft, even wraparound or butterfly light","slow-motion liquid: a drop, a ripple, a smooth swipe"], avoid:["plastic, over-smoothed skin","faces melting or changing","product texture turning watery"]},
  {id:"video:wedding", kind:"video", when:/\b(wedding|bride|groom|newlyweds?|propos(e|es|al|ing)|engagement|vows|save the date|down the aisle|first dance|on one knee)\b/i, add:["soft backlight or string-light bokeh, warm natural skin tones","slow push-in or gentle handheld follow at a respectful distance","candid emotion: small smiles, held hands, glances","slow motion only for the key moment: kiss, ring, toss"], avoid:["faces changing between frames","rings on the wrong hand or merging with fingers","crowd faces distorted"], ask:["Do you have photos of the couple so they stay recognizable?"]},
  {id:"video:family-memory", kind:"video", when:/\b(memorial (video|slideshow|service)|tribute (video|reel|slideshow)|in memory of|for (my |our )?(late )?(grandma|grandpa|grandmother|grandfather|nana)|grandkids|grandchildren|family (video|album|memories|slideshow|keepsake)|remembering|flashback|keepsake|for the family)\b/i, add:["warm, slightly soft late-afternoon light","gentle grain and faded warm colours like home film","still or very slow camera, small natural movements","candid moment, nobody posing for the camera"], avoid:["glossy commercial look","fast cuts or camera moves"]},
  {id:"video:horror", kind:"video", when:/\b(horror|creepy|scary|spooky|haunted|unsettling|jump scare|eerie|sinister|thriller|stalker|found footage)\b/i, unless:/\b(funny|cute|for kids|kid-friendly|not (too )?scary|playful|halloween|witch|cauldron|trick[- ]or[- ]treat\w*)\b/i, add:["slow, steady push forward into darkness","one weak light source: flashlight beam, flickering bulb or moonlight","something barely visible deep in shadow or at the frame edge","cold desaturated palette with crushed blacks","long stillness before any sudden movement"], avoid:["showing the monster fully and clearly","bright even lighting","gore"]},
  {id:"video:halloween-playful", kind:"video", when:/\b(halloween|witch(es)?|cauldron|trick[- ]or[- ]treat\w*|jack-?o-?lanterns?|pumpkins?)\b/i, unless:/\b(terrifying|disturbing|gore)\b/i, add:["warm orange glow from candles and pumpkins against cool purple night","fog drifting low along the ground","glowing green smoke curling up and lighting faces from below","storybook spookiness: crooked shapes, bats, moonlit silhouettes"], avoid:["gore or real violence","pitch-black frames where nothing reads"]},
  {id:"video:noir-detective", kind:"video", when:/\bnoir\b|detectives?|venetian blinds?|private eye/i, add:["hard single light through blinds or from a streetlamp, sharp shadows","wet street reflecting light, rain streaks backlit","high contrast with deep blacks","slow dolly at a distance, figure in hat and coat partly in silhouette","cigarette smoke or mist hanging in the light beam"], avoid:["bright even lighting","modern cars or phones"], ask:["Black and white, or colour?"]},
  {id:"video:cyberpunk-neon", kind:"video", when:/\b(cyberpunk|neon|blade runner|synthwave|vaporwave)\b/i, add:["wet pavement mirroring pink, cyan and violet neon","haze and rain catching the coloured light","dense signs as glowing shapes, no readable text","lateral truck or slow push at street level through the crowd"], avoid:["gibberish lettering on signs","flat daylight"]},
  {id:"video:giant-creature", kind:"video", when:/\b(dragons?|monsters?|kaiju|mechs?|mecha|golem|titan|giant robot|dinosaurs?|t[- ]?rex|beasts?|phoenix|godzilla)\b/i, add:["low camera with small figures or buildings in frame for scale","atmospheric haze between foreground and creature for depth","heavy, slow movement that matches its size; debris reacting on impact","one clear action: a roar, a landing, a wingbeat or a step"], avoid:["extra wings, heads or limbs","design changing mid-shot","too many actions at once"], ask:["Do you have concept art so the creature's design stays consistent?"]},
  {id:"video:trailer-teaser", kind:"video", when:/\b(trailers?|teasers?|key art reveal|game reveal)\b/i, add:["one strong beat per shot: reveal, turn or impact","slow build in camera motion, the biggest move saved for the end","silhouette against a bright background at the key moment","last frame held a beat, with space for a title card"], avoid:["cramming a whole plot into one clip","on-screen title text generated by the model"], ask:["What should the final beat be before the title appears?"]},
  {id:"video:hero-shot", kind:"video", when:/\b(warriors?|knights?|samurai|vikings?|superhero\w*|valkyrie|space marine|hero (shot|pose|standing)|standing (on|at) (a|the) (cliff|edge)|cape)\b/i, add:["wind moving cape, hair and cloth while the body holds still","strong rim light from behind separating the figure from the background","low angle, camera slowly pushing in or orbiting","smoke, mist or embers drifting between figure and background"], avoid:["armour or weapon changing design","hands fused with the weapon"]},
  {id:"video:war-battlefield", kind:"video", when:/\b(battlefield|soldiers?|trench(es)?|world war|ww(1|2|i|ii)|war (movie|documentary|memorial|film|reenactment)|battle charge|troops)\b/i, add:["smoke and dust drifting in layers, sun diffused through it","desaturated, cool, low-contrast palette","handheld at shoulder height close to one soldier","distant figures as silhouettes in the haze"], avoid:["gore","uniforms or weapons from the wrong era"], ask:["Which war or era?"]},
  {id:"video:talking-or-reaction", kind:"video", when:/\b(dialogue|monologue|lip[- ]?sync\w*|mouthing|news anchor|interview|voice ?over|talking head|line of dialogue)\b|\b(he|she|they|someone|character|one of them) says\b|\bsays (something like|his line|her line)|\bsaying ['"]|\b(his|her|their) line\b|\btalking (to|into|with) (the )?camera|\b(reaction|reacts?|reacting) (shot|to)\b|\b(see|sees|seeing|saw) .{0,30}for the first time\b|happy tears|bursts? into tears/i, unless:/\bno (\w+ )?(dialogue|talking|speaking|speech|voices?|lines)\b|\b(any|or) dialogue\b|\bwithout (dialogue|talking|speech)\b|\b(dialogue|talking)[- ]free\b/i, add:["medium close-up, eyes on the upper third, looking just off camera","soft key light from one side with gentle fill","the line or reaction happens once, then a short natural hold","natural blinks, breathing and small head movements","expression changing gradually, not in jumps"], avoid:["subtitles or on-screen text","mouth still moving after the line ends","a second person speaking"], ask:["What is the exact line (or reaction), and in what tone?"]},
  {id:"video:native-audio", kind:"video", when:/\b(sound effects?|sfx|foley|ambien(ce|t sound)|with (sound|audio)|audio (and|built)|baked[- ]in (sound|audio)|engine sound)\b/i, add:["audio: one steady ambient bed matching the location","two or three sound effects synced to visible actions: steps, pours, impacts","no background music unless it is asked for"], avoid:["sounds with no visible source","muffled or out-of-sync impacts"], ask:["Which sounds matter most, and should there be any speech?"]},
  {id:"video:multi-shot-sequence", kind:"video", when:/\b([2-9]|two|three|four|five|six|multiple|several|few) (different|distinct |connected )?(shots?|scenes|angles|camera angles)\b|shot list|montage|story arc|narrative|mini[- ]?story|beginning,? middle|whole little story/i, add:["numbered shots, each with its own framing, action and camera move","same character, wardrobe, light and colour grade in every shot","wide establishing first, closer details next, hero moment last","each shot one clear action that fits its length"], avoid:["character look changing between shots","too many actions per shot"], ask:["How long is the whole piece, and how many shots?"]},
  {id:"video:one-continuous-take", kind:"video", when:/\b(one|single) continuous|continuous (take|shot)|\bone take\b|\bno cuts\b|\boner\b|unbroken (shot|take)/i, add:["one unbroken camera move, no cuts or jumps","a clear path: a defined start, what it passes, a final resting frame","steady speed with a smooth ease-in and ease-out","subject and set consistent from first frame to last"], avoid:["hidden cuts or sudden jumps","objects changing as the camera passes them"]},
  {id:"video:fpv-drone", kind:"video", when:/\bfpv\b/i, add:["fast, low FPV flight skimming surfaces and banking through gaps","slight horizon roll on turns","wide lens with motion blur on the edges of frame","near misses past foreground objects for speed"], avoid:["obstacles warping as the camera passes","jerky stop-start motion"]},
  {id:"video:dolly-zoom", kind:"video", when:/dolly[- ]?zoom|vertigo (effect|shot)|\bzolly\b/i, add:["camera dollies toward the subject while the lens zooms out, subject stays the same size","background visibly stretching away behind the subject","subject centered and still during the move","one smooth, slow move held to the end"], avoid:["subject changing size","combining it with other camera moves"]},
  {id:"video:orbit-shot", kind:"video", when:/\b(orbit\w*|arc(s|ing)? around|arc shot|360 (shot|orbit)|circl(e|es|ing) (all the way )?around)\b/i, unless:/\borbit(ing)? (the )?earth\b|planets/i, add:["camera arcing around the subject at constant distance and height","subject centered and steady while the background slides past","lighting consistent as the angle changes","slow, even speed"], avoid:["subject turning to follow the camera","background objects warping during the arc"]},
  {id:"video:slow-motion", kind:"video", when:/slow[- ]?mo(tion)?\b|\b(120|240|1000) ?fps|high[- ]speed camera|super slow|\bsplash\w*|\bpuddle\b|drop(s|ping)? into (the )?water/i, add:["high-frame-rate slow motion with crisp detail","droplets, dust, hair or fabric hanging and drifting in the air","one moment stretched across the whole clip","splashes forming crowns of separate droplets, backlit so each one sparkles"], avoid:["stuttering or frame-skipping motion","motion that looks sped up","water behaving like gel"]},
  {id:"video:probe-lens-macro", kind:"video", when:/probe lens|laowa|macro (shot )?(of|on) (the )?(gears|mechanism)|\bmoving through (a maze|the inside|the interior)/i, add:["probe-lens perspective: tiny lens tip gliding a few centimetres from surfaces","deep focus with extreme foreground scale, objects towering over the lens","slow, smooth path weaving through gaps without touching anything","dust motes drifting through a single shaft of light"], avoid:["lens passing through solid objects","fast jerky moves"]},
  {id:"video:industrial-robotics", kind:"video", when:/\b(robot(ic)? arms?|assembly line|factory (floor|robots?)|robots? (welding|assembl\w*)|manufactur\w*|cnc|circuit board)\b/i, add:["precise, repeatable robotic motion with crisp starts and stops","cool clean industrial light, reflective metal and painted steel","shallow depth of field on the tool tip or part","welding sparks as short bright bursts that fade fast"], avoid:["robot joints bending like rubber","parts merging or vanishing"]},
  {id:"video:craft-hands", kind:"video", when:/\b(pottery|potter'?s wheel|clay|knit\w*|woodwork\w*|wood ?carv\w*|carving wood|hand plane|wood shavings|glass ?blow\w*|molten glass|blacksmith|forge|anvil|tattoo (needle|gun)|tattoo needle|needle .{0,20}skin|calligraphy|varnish|leather ?work|craftsman\w*|artisan\w*|soap (loaf|bars?)|barber\w*|haircut|straight razor|scissors|florist|(arranging|wrapping) a bouquet|welding|welder|mechanic)\b/i, unless:/\brobot/i, add:["close on the hands and tool, shallow depth of field","material texture vivid: shavings, wet clay, glowing metal, ink","steady, deliberate pace of real handwork","side light skimming across the surface"], avoid:["extra fingers or hands merging with tools","tool changing shape"]},
  {id:"video:unboxing", kind:"video", when:/\bunbox\w*|opening (a|the) box|opens the box|out of the box/i, add:["top-down or low tabletop angle on a clean surface","hands entering naturally, lid lifting in one smooth motion","soft even light, product crisp and unchanged","tissue, foam and packaging details in sharp texture"], avoid:["product appearing before the box opens","extra hands or fingers"]},
  {id:"video:toy-alive", kind:"video", when:/\b(toys?|action figures?|model train|figurine|plush(ie)?)\b.{0,60}\b(walk\w*|mov\w*|alive|stomp\w*|coming out|play\w*)\b/i, add:["camera low at toy height, shallow focus making the world feel big","slightly stepped, stop-motion-like character to the movement","real materials kept: plastic sheen, seams, paint chips","everyday objects around it as giant scenery"], avoid:["toy turning into a realistic creature","toy changing size or proportions"]},
  {id:"video:documentary-real", kind:"video", when:/\bdocumentar(y|ies)\b|\bdoc (style|segment|b-roll)|non-?profit|donors?|donation|fundrais\w*|charity|volunteers?|conservation|awareness/i, unless:/\bnature doc|\b(wildlife|whales?|animals?|birds?|hummingbirds?|jellyfish|astronauts?|space)\b/i, add:["handheld with slight natural sway, available light only","people absorbed in the work, not looking at the camera","muted, honest colour with soft contrast","close details of hands, faces and tools between wider views"], avoid:["posed smiles at camera","glossy commercial lighting"], ask:["Should it feel hopeful or sobering?"]},
  {id:"video:corporate-office", kind:"video", when:/\b(corporate|office|business meeting|meeting room|training video|about (us|page)|company (video|culture|anniversary)|keynote|handshake|hands shaking|coworkers|team meeting|presenting)\b/i, add:["bright natural window light in a clean modern space","people mid-task, natural interaction, no posing","slow slider move or gentle push-in","screens as soft glows without readable text"], avoid:["gibberish text on screens or whiteboards","stiff stock-photo poses"]},
  {id:"video:travel-broll", kind:"video", when:/\b(travel\w*|vlog|tourism|tourists?|old town|night market|vacation|hot air balloons?|cruise|road trip)\b/i, add:["wide establishing view with depth first: skyline, coast or street","people moving naturally through the scene for life and scale","golden hour or blue hour light","smooth gimbal walk or slow drone push"], avoid:["gibberish signs","crowds of identical faces"]},
  {id:"video:yoga-wellness", kind:"video", when:/\b(yoga|meditat\w*|wellness|spa|sauna|zen|mindful\w*|sun salutation|relaxing)\b/i, add:["slow continuous movement with long held poses","soft early-morning side light with gentle haze","locked-off or very slow camera, wide with space around the person","muted, warm, low-contrast palette"], avoid:["joints bending wrongly in poses","fast cuts or camera moves"]},
  {id:"video:kids-education", kind:"video", when:/\b(science (class|project|unit|show|museum|fair|presentation)|educational|biology|geography|water cycle|lesson|explainer|school project|museum|grade science|\d+(st|nd|rd|th) graders?|weather unit|teaching)\b/i, add:["subject large and centered against an uncluttered background","the process shown in clear stages, one at a time","true-to-life scale, colour and physics","steady camera so viewers can follow"], avoid:["frightening or violent framing","fantasy details that teach the wrong thing"], ask:["How old are the viewers?"]},
  {id:"video:celebration-confetti", kind:"video", when:/\b(confetti|graduat\w*|mortarboards?|caps? (thrown|in the air|toss\w*)|throwing (their )?caps|balloons?|fireworks|new year'?s?|party poppers?)\b/i, unless:/\bhot air balloons?\b/i, add:["pieces falling at different speeds and depths, some close to the lens","backlight making confetti and caps glint","slow motion at the top of the throw","cheering faces soft in the background"], avoid:["confetti falling upward","faces distorted in the crowd"]},
  {id:"video:film-look-era", kind:"video", when:/film grain|grainy|\b16mm\b|super ?8|\b8mm\b|filmic|halation|\ba24\b|\b(70s|90s|1970s|1990s) (film|movie)s?|old film|film stock|celluloid|\b(18|19)\d0s\b|\broaring 20s\b|period (piece|drama|film)|\bvictorian\b|\bspeakeasy\b|old[- ]world/i, add:["fine organic film grain over the whole frame","soft highlight roll-off with gentle halation around bright lights","slightly muted film colour, no digital oversharpening","for a past era: wardrobe, props and vehicles true to it, nothing modern"], avoid:["clean digital sharpness","heavy fake scratches or dust","modern objects slipping into a period scene"], ask:["Which decade should it look like it was shot in?"]},
  {id:"video:black-and-white", kind:"video", when:/black[- ]and[- ]white|\bmonochrome\b|\bb&w\b/i, add:["strong directional light so shapes read without colour","rich blacks, silvery midtones and clean highlights","contrast built from light and shadow, textures emphasised"], avoid:["flat grey low-contrast image"]},
  {id:"video:anime-style", kind:"video", when:/\banime\b|\bmanga\b|\bamv\b|cel[- ]shad\w*|鬼灭|动漫/i, add:["cel-shaded 2D look with clean line art and flat colour","painted backgrounds with soft detail behind crisp characters","held poses with snappy key moments","wind, speed lines or light streaks for action beats"], avoid:["drifting toward 3D or photoreal faces","line art wobbling between frames"]},
  {id:"voice:audiobook-fiction", kind:"voice", when:/\baudio ?books?\b|use ?case:? audiobook|\b(?:narrat\w*|read)\b[^.]{0,40}\b(?:novel|chapter|manuscript)\b|\bchapter (?:one|\d+) of\b/i, unless:/\bad read|commercial|radio spot|\bspot\b|trailer|\bmemoir|self[- ]help|non-?fiction|picture book|children'?s|\bkids?\b|poe(?:m|try)|\bdub|translat/i, add:["steady narrator voice with lightly differentiated character voices in dialogue","unhurried, even pace with natural breaths and longer pauses at scene breaks","emotion carried by pace and pitch changes, not theatrical shouting or sobbing","dry, close-mic studio sound with no music or reverb"], avoid:["over-acting every line","announcer or commercial cadence"], ask:["What genre and mood, and is it told in first or third person?","What age, gender and accent should the narrator have?"]},
  {id:"voice:audiobook-memoir", kind:"voice", when:/\bmemoir|personal essay|autobiograph/i, unless:/\bdub|translat/i, add:["plain, conversational delivery, like the author telling it to one listener","restraint at emotional peaks: slower and quieter rather than louder","small natural hesitations kept, no performed crying","intimate close-mic sound in a dry room"], avoid:["melodramatic swells","polished announcer tone"], ask:["Should the narrator match the author's age, gender and accent?"]},
  {id:"voice:audiobook-nonfiction", kind:"voice", when:/self[- ]help|non-?fiction|business book|\bhabits\b/i, unless:/\bdub|translat/i, add:["warm, direct mentor tone, kind but confident","a short pause after each key idea so it lands","lists and steps read with clear separation between items","steady, alive energy that doesn't sag across long sections"], avoid:["preachy, sermon-like emphasis","motivational-speaker hype"]},
  {id:"voice:audiobook-suspense", kind:"voice", when:/(?:thriller|mystery|suspense|whodunit|chase scene)[\s\S]*(?:audio ?book|novel|chapter|manuscript)|(?:audio ?book|novel|chapter|manuscript)[\s\S]*(?:thriller|mystery|suspense|whodunit|chase scene)/i, unless:/\bcozy\b|\bdub|translat/i, add:["calm, even baseline early so the tension has room to build","pace tightening and phrases clipping shorter as the scene escalates","voice dropping lower and quieter before a reveal, then a held beat","audible breath in the tense passages only"], avoid:["an ominous tone from the very first line"]},
  {id:"voice:kids-content", kind:"voice", when:/picture book|children'?s (?:book|story|stories|audiobook|chapter book|app|show|cartoon)|\bkids?'? (?:story|stories|book|app|show|cartoon|content)|storybook|fairy ?tales?|phonics|preschool|toddler|counting app|reading app|for (?:young )?kids|\b\d+ year olds\b|ages? [2-9]\s*(?:-|to)\s*\d+/i, unless:/bedtime|goodnight|sleep|\bscene\b/i, add:["bright, warm voice that sounds genuinely delighted, not performed","slower pace with clear, crisp articulation of every word","playful pitch lifts on questions and surprises, gentle tone on mistakes","short sentences with small pauses for the child to react"], avoid:["sarcasm or adult irony","sudden loud shouts or harsh, scary sounds"], ask:["What age are the listeners?"]},
  {id:"voice:kids-bedtime", kind:"voice", when:/bedtime|goodnight|good night|(?:\bkids?\b|child\w*|toddler)[\s\S]{0,60}(?:\bsleep|\bbed\b)/i, unless:/\bdub|translat/i, add:["soft, low, warm voice drifting gently downward in pitch","pace slowing little by little toward the end","long, relaxed pauses between sentences","no bright exclamations or sudden emphasis"]},
  {id:"voice:sleep-story", kind:"voice", when:/sleep (?:story|stories|app|track|session|aid)|insomnia|wind[- ]down|fall asleep|night[- ]time session/i, unless:/\bkids?\b|child|toddler|\bdub|translat/i, add:["low, grounded, warm voice: calm but not whispered or breathy","very slow pace with long pauses after each sentence","falling intonation at sentence ends, no upturns","energy and volume easing lower as the track goes on","soft close-mic sound with no harsh sibilance or mouth clicks"], avoid:["bright or upbeat inflection","heavy breathiness that distracts"]},
  {id:"voice:guided-meditation", kind:"voice", when:/meditat|mindful|breath(?:ing)? (?:exercise|track)|breathwork|relaxation|stress relief|yoga (?:studio|class intro|app|session)|affirmation/i, unless:/\bdub|translat/i, add:["settled, present voice: calm and warm, not sleepy or whispered","unhurried pace with room for a full breath after each cue","soft, invitational delivery, never commanding","even volume with no dramatic swells"], ask:["Is it meant to help people fall asleep, or stay relaxed but alert?"]},
  {id:"voice:trauma-informed-calm", kind:"voice", when:/trauma|panic attack|anxiety|\bgrief|end[- ]of[- ]life|therap(?:y|ist)|counsel/i, unless:/\bdub|translat|roleplay training|counseling students|\bscene\b/i, add:["gentle, steady voice with no authoritative edge","slow, even pace that never hurries the listener","warmth without pity or a patronizing sing-song","suggestions offered softly with falling intonation, never as orders"], avoid:["commanding or drill-like tone","forced cheerfulness"]},
  {id:"voice:asmr", kind:"voice", when:/\basmr (?:performer|voice|youtuber|track|line|roleplay|style)|an asmr\b|roleplay track|spa roleplay|campfire roleplay/i, unless:/\bdub|translat/i, add:["very close-mic intimacy, soft and breathy but every word intelligible","slow, gentle pace with relaxed pauses","warm low-mid tone, no harsh sibilance or popping plosives","quiet, dry room with no reverb"]},
  {id:"voice:radio-tv-ad", kind:"voice", when:/\bcommercial\b|\bad read|\b(?:radio|tv|television|instagram|social|local) (?:spot|ad)\b|use ?case:? ad\b|\bad for (?:a|an|my|our|the)\b|\bads?\b[^.]{0,40}\bspot\b|\d+ second (?:radio |tv |local |instagram )?(?:spot|ad)\b|\bsale\b/i, unless:/\bdub|translat|sponsor|station id|imaging (?:drops?|voice|line)/i, add:["friendly, conversational read aimed at one listener, not announced at a crowd","business name and call to action slightly slower and clearly stressed","a smile in the voice, with energy lifting toward the call to action","pace fitted to the spot length, never rushed at the end","tight, dry broadcast sound with no reverb"], avoid:["hard-sell shouting","cheesy announcer cadence"], ask:["How long is the spot, and what one thing should listeners do?","Should it feel high-energy and fun, or calm and trustworthy?"]},
  {id:"voice:luxury-ad", kind:"voice", when:/luxury|high[- ]end|upscale|perfume|fragrance|jewel|watch brand/i, unless:/\bdub|translat/i, add:["low, smooth, unhurried voice with understated confidence","few words stressed, with generous pauses between lines","soft, close-mic warmth with a hint of a smile, never excited"], avoid:["hard-sell energy","exclamation-style emphasis"]},
  {id:"voice:podcast-sponsor-read", kind:"voice", when:/sponsor|host[- ]read|podcast ad/i, unless:/\bdub|translat/i, add:["relaxed host-read feel, like recommending something to a friend","natural small hesitations and a smile, not announcer polish","product name said clearly once, with a light pause after","same energy and mic sound as the surrounding show"]},
  {id:"voice:authentic-unscripted", kind:"voice", when:/unscripted|off the cuff|not (?:sound(?:ing)? )?(?:scripted|like an? (?:ad|actor|robot|typical))|(?:genuine|authentic|real)[^.]{0,30}not (?:scripted|performed|fake|corporate|salesy|pushy|a performance)|not (?:performed|fake) (?:enthusiasm|hype|excitement)|genuine(?:ly)? (?:excited|proud|thrilled|grateful)/i, unless:/\bdub|translat/i, add:["loose, conversational rhythm with natural small pauses","stress on the meaning words only, not on every adjective","slight shifts in pace, like thinking while speaking","no sing-song upswings or announcer polish"]},
  {id:"voice:trailer-epic", kind:"voice", when:/trailer|in a world|use ?case:? trailer|hype vo/i, unless:/quiet|restrain|a24|literary|prestige|arthouse|subtle|reflective|moody|slow[- ]build|unsettling|not (?:loud|bombastic|hollywood|action|campy|overhyped)|documentar|\bdub|translat/i, add:["deep, resonant low register with close, present mic sound","short phrases separated by deliberate pauses for music hits","intensity building line by line toward the title reveal","crisp consonant attacks and a held, weighty final word"], ask:["Classic booming trailer voice, or a quieter modern one?"]},
  {id:"voice:trailer-restrained", kind:"voice", when:/trailer[\s\S]*(?:quiet|restrain|a24|literary|prestige|arthouse|moody|slow[- ]build|unsettling|reflective|not (?:loud|bombastic|hollywood|action))|(?:quiet|a24|restrain|prestige|arthouse)[\s\S]*trailer/i, unless:/\bdub|translat/i, add:["low, quiet, intimate delivery, as if speaking to one person","long silences between lines, letting the pauses carry the weight","natural speaking voice with no booming announcer resonance","intensity rising by slowing down, not by getting louder"]},
  {id:"voice:horror-narration", kind:"voice", when:/horror|haunted|creepy|\bghost|eerie|ominous|sinister|\bdread/i, unless:/not (?:too )?(?:scary|terrifying|dark)|family[- ]friendly|\bkids?\b|silly|funny|\bdub|translat/i, add:["low, hushed voice with close-mic breath","slow pace, with the last words of lines drawn out","dropping toward a whisper on the scariest lines instead of shouting","flat, still intonation with cold, sparse delivery"], avoid:["campy cackling","shouted jump-scare delivery"]},
  {id:"voice:spooky-family-fun", kind:"voice", when:/(?:spooky|halloween|witch|haunted|villain|creepy|monster)[\s\S]*(?:\bkids?\b|family[- ]friendly|not (?:too )?(?:scary|terrifying|dark)|silly|\bfun\b)|(?:\bkids?\b|family[- ]friendly|silly)[\s\S]*(?:spooky|halloween|witch|haunted|villain)/i, unless:/\bdub|translat/i, add:["theatrical, playful spookiness with exaggerated rolling vowels","cackles and drawn-out words, no growls or screams","a bright undercurrent so it reads as fun, not threat"]},
  {id:"voice:true-crime", kind:"voice", when:/true crime|cold case|unsolved|wrongful(?:ly)? (?:conviction|imprison)|\bmurder/i, unless:/\bdub|translat/i, add:["measured, low, grounded voice: serious without melodrama","facts stated plainly, with a pause after the hardest details","respectful toward victims, no relish in grim details","intimate, late-night close-mic sound"], avoid:["campy spooky voice","sensational emphasis"]},
  {id:"voice:documentary-narration", kind:"voice", when:/documentar/i, unless:/\bdub|translat|trailer/i, add:["measured, warm, authoritative narrator, never announcer-like","even pace with clear pauses between ideas","emotion understated, with extra restraint at tragic moments","natural, dry studio voice with no reverb"], ask:["Should the tone be awed, investigative, or somber?"]},
  {id:"voice:nature-documentary", kind:"voice", when:/nature (?:doc|documentar|narrat|vlog|film)|wildlife|deep sea|bioluminescen|backyard birds|attenborough|\breef\b/i, unless:/\bdub|translat/i, add:["hushed, intimate sense of wonder, slowing slightly at each reveal","soft, low-mid voice with a gentle smile on surprising facts","quiet pauses that leave room for the pictures and natural sound"]},
  {id:"voice:explainer-narration", kind:"voice", when:/explainer|educational|video essay|youtube (?:video|channel|essay|explainer)|science (?:channel|video|class)|school project|how [\w ]{1,20} (?:works?|fly|flies)|(?:channel|videos?) (?:about|covers?)/i, unless:/\bdub|translat|corporate|recall|annual report|ethics/i, add:["clear, friendly, curious tone, like explaining to a smart friend","steady medium pace with a short pause before each key term","numbers and new terms spoken slowly and clearly","natural pitch movement so the energy holds across long videos"], avoid:["monotone lecture delivery","over-hyped clickbait cadence"]},
  {id:"voice:corporate-narration", kind:"voice", when:/corporate|company (?:video|overview|narration)|about (?:us|page)|investor|pitch (?:deck|video)|product (?:demo|launch)|brand (?:video|story|film)|use ?case:? corporate|all[- ]hands|annual report|sustainability report|conference|keynote|year in review|homepage/i, unless:/\bdub|translat|layoff|recall|\bscene\b/i, add:["confident, warm mid-low voice, measured rather than salesy","medium pace with clean pauses at section changes","company and product names slightly slower and clearly stressed","conversational inflection, never sounding like reading slides"], avoid:["trailer-style hype","stiff, monotone delivery"], ask:["Who is watching: customers, investors, or employees?"]},
  {id:"voice:difficult-announcement", kind:"voice", when:/layoff|\brecall\b|retraction|correction|admit\w* [^.]{0,30}(?:mistake|error)|known limitations|whistleblow|merger/i, unless:/\bdub|translat/i, add:["plain, sincere, lower-energy delivery without corporate polish","steady pace, with a pause after each hard fact","direct accountability, never defensive or over-rehearsed","warmth at the close without forced positivity"]},
  {id:"voice:elearning-training", kind:"voice", when:/training|e-?learning|online course|\bcourse\b|onboarding|\blessons?\b|lecture|\btutor|tutorial|use ?case:? e-learning/i, unless:/\bdub|translat|emergency (?:procedure|checklist)|surgical|air traffic|\bscene\b|roleplay training/i, add:["clear, patient, friendly instructor voice","pace slightly slower than conversation, with a pause after each step","terms and numbers articulated cleanly","natural pitch variation that holds attention through long modules"], avoid:["monotone reading","condescending over-explaining"]},
  {id:"voice:safety-critical-training", kind:"voice", when:/emergency (?:procedure|checklist)|surgical|air traffic|aviation|forklift|safety (?:training|video|disclaimer)|evacuation/i, unless:/\bdub|translat/i, add:["completely steady, calm, even voice whatever the content","exact, measured pacing with crisp separation between steps","urgency shown only through clarity, never through drama","every number and term articulated in full"]},
  {id:"voice:ivr-phone-menu", kind:"voice", when:/\bivr\b|phone (?:menu|system|tree)|press (?:one|two|\d)|after[- ]hours|on hold|automated phone|voicemail greeting|menu options/i, unless:/\bdub|translat/i, add:["clear, calm, friendly voice at an even level throughout","slower pace with a full pause between menu options","option numbers and key words clearly stressed","dry, clean sound with no music, so prompts splice together seamlessly"], ask:["Should callers hear the business name first, and are there after-hours or holiday messages?"]},
  {id:"voice:public-announcement", kind:"voice", when:/airport|train station|station announcement|flight[- ]delay|\bboarding\b|\bgate\b|public address/i, unless:/\bdub|translat/i, add:["official, calm, measured announcer voice","even pitch with a slight downward finish on each line","slow, over-articulated delivery that carries in noisy spaces","dry voice so a speaker or hall effect can be added afterward"]},
  {id:"voice:ai-voice-agent", kind:"voice", when:/chatbot|\bbot\b|voice agent|ai agent|phone agent|customer (?:support|service)|call cent(?:er|re)|use ?case:? conversational|intake (?:agent|assistant)|ordering agent|support line/i, unless:/\bdub|translat|training|\bscene\b/i, add:["natural, warm conversational voice at normal speaking pace","answers starting right away, in short sentences with crisp endings","brief, sincere apologies that never sound scripted","steady, unflappable tone that stays even when the caller is upset","light, friendly prosody with no sales or announcer inflection"], avoid:["over-bubbly cheer","flat robotic intonation"]},
  {id:"voice:realtime-low-latency", kind:"voice", when:/real[- ]?time|latency|no delay|instant(?:ly|aneous)?\b|no awkward pause|\blive (?:ai|voice|interactive|host|npc|translation)|respond(?:s)? (?:to [\w' ]{0,30})?out loud/i, add:["lowest-latency streaming model, with audio streamed as text arrives","short opening words so the first sound plays almost immediately","replies phrased as short sentences that synthesize in quick chunks","fixed voice settings so the tone stays consistent between chunks"]},
  {id:"voice:calm-under-pressure-agent", kind:"voice", when:/fraud|dispatch|crisis|distress|panick|telehealth|callers? (?:are|can be|is) [^.]{0,20}(?:stressed|upset|distressed|panicked)|stressful calls|emergenc(?:y|ies) (?:calls?|line)/i, unless:/\bdub|translat|\bscene\b|line read/i, add:["low, steady, unhurried voice that never mirrors the caller's panic","calm authority with warmth, never cold or clinical","simple sentences with brief pauses for the caller to respond","no cheerful or sing-song inflection"]},
  {id:"voice:voice-assistant", kind:"voice", when:/smart (?:speaker|home|device)|home automation|voice assistant|virtual assistant|\bsiri\b|\balexa\b|ai companion|companion app|morning briefing|car assistant/i, unless:/\bdub|translat/i, add:["warm, clear mid-pitch voice: friendly but not bubbly","natural conversational pacing with relaxed sentence endings","one consistent personality across short replies","clean, dry close-mic sound that holds up on small speakers"]},
  {id:"voice:original-voice-design", kind:"voice", when:/(?:own|original|signature|branded|unique|distinct|custom|new) (?:voice|persona)|from scratch|\binvent|made[- ]up voice|nobody else|off the shelf|stock voice|from the ground up|unlike any/i, unless:/\bdub|translat/i, add:["age range, gender presentation, accent and pitch stated plainly","one memorable texture detail, like a light rasp or crisp clipped diction","personality described through delivery: pace, warmth and attitude","described by qualities only, with no real person's name"], ask:["Where will people hear it most: ads, an app, or a character?"]},
  {id:"voice:sound-alike-reference", kind:"voice", when:/(?:like|sound(?:s|ing)? like) (?:david attenborough|morgan freeman|siri|alexa|a famous|those|that)\b|\b(?:there'?s|theres) (?:a|an|this|that) [^.]{0,40}(?:narrator|voice|youtuber|dj|host|actor|actress)|\bi (?:heard|saw|watched) (?:a|an|this|that|one)\b|you know (?:that|how|those)/i, add:["the reference's qualities described directly: register, pace, warmth, accent and texture","no imitation or cloning of a specific real person's voice"], ask:["Which two or three qualities of that voice matter most to you?"]},
  {id:"voice:game-npc-character", kind:"voice", when:/\bnpc\b|video game|game character|\brpg\b|character voice|shopkeeper|tavern|companion character|use ?case:? character|visual novel|interactive fiction|\bdnd\b|d&d|escape room/i, unless:/\bdub|translat|trailer/i, add:["age, accent and attitude audible from the very first line","slightly heightened performance grounded in one clear motivation","the same voice and energy across many short lines","dry, effect-free recording so the game can process it later"], ask:["What is the character's age, attitude, and relationship to the player?"]},
  {id:"voice:old-wise-character", kind:"voice", when:/wizard|sorcerer|\bmage\b|\bdwarf|sea captain|old (?:man|woman|storyteller|irish storyteller|detective|wizard)|\belder\b|grand(?:ma|pa|father|mother)(?:'s)? (?:voice|character|energy|kitchen|tell\w*)|(?:like|as) an? (?:warm |old |sweet |wise )?grand(?:ma|pa|father|mother)|\bwise\b|\bmonk\b/i, unless:/\bdub|translat/i, add:["older voice with a weathered, slightly rough texture","slow, deliberate pace with knowing pauses","warmth underneath any gruffness","long, rounded vowels and relaxed sentence endings"]},
  {id:"voice:villain", kind:"voice", when:/villain|antagonist|boss (?:fight|dialogue)|menac|\bthreat|taunt/i, unless:/silly|not[- ](?:too )?scary|\bkids?\b|\bcute\b|\bdub|translat/i, add:["quiet, controlled menace: slow, precise and low in volume","smooth, almost polite delivery with cold weight on key words","tension built through stillness and pauses, not shouting"], ask:["Truly frightening, or fun-scary for a broad audience?"]},
  {id:"voice:cute-creature-mascot", kind:"voice", when:/mascot|cartoon|creature|talking (?:dog|cat|animal|rooster)|cute voice|sidekick|puppet|imaginary friend/i, unless:/\bdub|translat/i, add:["bright, higher voice with a bouncy rhythm","exaggerated but clear articulation","cheerful, laugh-ready tone that never turns shrill","short, punchy line reads with playful pitch jumps"]},
  {id:"voice:robot-ai-character", kind:"voice", when:/\brobot (?:co[- ]?host|character|companion|sidekick|voice|that)|little robot|\bandroid\b|ship (?:computer|ai)|emotionless|\bai (?:character|narrator|co[- ]?host)/i, unless:/\bdub|translat|not (?:a |like a )?robot|robot feel|like a robot/i, add:["precise, even articulation with slightly clipped sentence endings","mostly level pitch, with small controlled inflections for personality","dry, deadpan timing on any jokes"]},
  {id:"voice:podcast-radio-intro", kind:"voice", when:/podcast intro|intro voice|station id|imaging (?:drops?|voice|line)|radio (?:station|dj)|\bdj\b|donation alert|channel intro|show intro/i, unless:/\bdub|translat/i, add:["punchy, compact delivery that fits in a few seconds","tight, dry close-mic sound with strong presence","a short beat before the show or station name, then a clear hit on it"], ask:["How many seconds, and what attitude: booming, smooth, or deadpan?"]},
  {id:"voice:blog-article-read", kind:"voice", when:/\bblog\b|\barticle|read (?:it |this |them )?(?:out loud|aloud)|audio version|\bebook|text to speech|newsletter/i, unless:/\bdub|translat/i, add:["relaxed, friendly conversational read, like a host talking to one listener","headings and lists turned into natural spoken transitions","steady medium pace with clean pauses between sections","the same voice and level across every piece"]},
  {id:"voice:audio-guide", kind:"voice", when:/audio (?:guide|tour|display)|museum|exhibit|tasting room|self[- ]guided/i, unless:/\bdub|translat|use ?case:? (?:ad|trailer|audiobook|corporate|e-learning|meditation|character|conversational)/i, add:["warm, knowledgeable guide voice, like a friendly docent","medium-slow pace with a pause between facts","names, dates and places articulated carefully","the same voice and level across every stop"]},
  {id:"voice:fitness-coach", kind:"voice", when:/fitness|workout|gym'?s (?:instagram|ad|reel)|for (?:a|my|our) gym|boot ?camp|exercise class/i, unless:/\bdub|translat|\bscene\b/i, add:["energetic, forward-driving voice with breath and punch","short, clipped cues, with countdowns rhythmic and exact","firm but supportive, never insulting","energy rising on the final push of each set"]},
  {id:"voice:sports-announcer", kind:"voice", when:/commentat|stadium|play[- ]by[- ]play|highlight reel|esports|fantasy football|match events|sports (?:announcer|caster|podcast)/i, unless:/\bdub|translat/i, add:["big, projected voice that rises in pitch on big plays","fast, rhythmic delivery that stretches the key word","reactions varied in intensity from play to play"]},
  {id:"voice:news-weather-anchor", kind:"voice", when:/news ?(?:anchor|segment|report|reader|caster)|newscast|\banchor\b|weather (?:forecast|readout|report|app)|daily forecast/i, unless:/\bdub|translat|parody|caricature|satire/i, add:["crisp, neutral broadcast diction at a steady pace","even pitch, with stress on the one key fact in each sentence","authoritative but human, with slight warmth on lighter items"]},
  {id:"voice:noir-detective", kind:"voice", when:/\bnoir\b|detective|hard[- ]?boiled|private eye/i, unless:/\bdub|translat|\bcozy\b/i, add:["low, gravelly, world-weary voice with dry wit","slow, laconic pacing with a wry downturn at line ends","close, intimate inner-monologue feel"]},
  {id:"voice:memorial-tribute", kind:"voice", when:/memorial|tribute|eulogy|funeral|in memory|celebration of life|passed away|losing (?:a|my|our) (?:parent|mother|father|mom|dad|friend|grand)|condolence/i, unless:/\bdub|translat|use ?case:? (?:ad|trailer|audiobook|corporate|e-learning|meditation|character|conversational)/i, add:["soft, warm, unhurried voice with quiet dignity","pauses after names and key memories","restraint at emotional moments, no theatrical crying","a gentle smile in the lighter memories"], ask:["Should it feel mournful, or like a celebration of their life?"]},
  {id:"voice:personal-celebration", kind:"voice", when:/wedding|anniversary|birthday|graduation|engagement video|proposal video/i, unless:/\bdub|translat|\bscene\b|use ?case:? (?:ad|trailer|audiobook|corporate|e-learning|meditation|character|conversational)/i, add:["warm, close, personal voice, like a close friend speaking","relaxed pace with smiles audible on the happy lines","natural and unpolished rather than announcer-smooth"]},
  {id:"voice:nonprofit-donor", kind:"voice", when:/nonprofit|non-profit|\bdonors?\b|donation page|donate|fundrais|charity/i, unless:/\bdub|translat|alert|use ?case:? (?:ad|trailer|audiobook|corporate|e-learning|meditation|character|conversational)/i, add:["heartfelt, sincere voice with quiet warmth","gratitude spoken plainly, never pleading or guilt-tripping","impact numbers read clearly, with a brief pause after each","a hopeful lift on the closing line"]},
  {id:"voice:comedic-timing", kind:"voice", when:/comed|funny|(?<!sounding )sarcas|dry (?:wit|humou?r)|witty|sketch|parody|satire|\bjokes?\b/i, unless:/\bdub|translat|not funny/i, add:["a short beat of silence before the punchline","punchline delivered crisply, slightly quicker than the setup","stress on the one funny word, not the whole line","the character fully believing what they say"], ask:["Dry and deadpan, or big and over the top?"]},
  {id:"voice:layered-emotion-line", kind:"voice", when:/trying (?:not )?to (?:sound|stay|be|hide|hold|play|seem|remain|keep)|but (?:clearly|actually|secretly|you can (?:tell|hear))|underneath|holding back|\bhiding|two emotions|mixed emotions|both (?:be )?(?:genuinely )?present|at (?:the same time|once)|layered|subtext|cracks? (?:exactly|once|into)/i, unless:/\bdub|translat/i, add:["surface emotion and hidden emotion named separately in the acting direction","surface tone held steady for most of the line","hidden feeling leaking through small cues: a tight breath, a catch, a slight waver"], avoid:["playing the hidden emotion openly","exaggerated, cartoonish tells"], ask:["Should the mask slip anywhere, and on which word?"]},
  {id:"voice:line-read-direction", kind:"voice", when:/line read|make it sound|needs? (?:this |it )?to sound|(?:want|need) a [\w ]{0,40}line\b|\bline (?:where|for|thats|that's)|acting direction|director'?s notes|voice acting/i, unless:/\bdub|translat/i, add:["acting direction naming the emotion, its cause, and who is being addressed","voice cues made specific: breath, pace, pitch and volume","natural, conversational performance rather than a theatrical reading"], ask:["What just happened right before this line, and who is it spoken to?"]},
  {id:"voice:language-accent", kind:"voice", when:/\b(?:spanish|french|german|portuguese|italian|japanese|korean|mandarin|cantonese|hindi|arabic|polish|dutch|swedish|turkish|russian)\b|\baccent\b|southern us|scottish|\birish\b|australian|english,? \(?(?:uk|indian|british)/i, unless:/\bdub|translat|exaggerated|parody|caricature|flavou?red|old[- ]timey|1940s|1950s|salty/i, add:["a native speaker's natural accent for the stated language and region, not put on","a multilingual model suited to the target language","names and loanwords pronounced the way local speakers say them","regional rhythm and vowel sounds consistent across the whole read"]},
  {id:"voice:pronunciation-jargon", kind:"voice", when:/jargon|terminology|technical terms|pronunc|acronym|legal speech|medical terms|scientific names/i, add:["unusual names and terms given phonetic spellings or a pronunciation dictionary","acronyms marked as spelled out or spoken as words","dense jargon slowed slightly, with stress on the key noun"]},
  {id:"voice:dub-video-general", kind:"voice", when:/\bdub|translate (?:my|our|this)|(?:translate|convert)\w* [^.]{0,40}(?:into|to) (?:english|spanish|french|german)|english (?:version|track|audio|language track)|language track/i, add:["each speaker's own voice kept through per-speaker voice cloning","pacing, pauses and emotional intensity matched to the original, line by line","translation fitted to the original timing, with lip sync on close-ups","original background music and sound effects kept under the new voices","natural target-language phrasing rather than word-for-word translation"], ask:["Keep the original speakers' voices, or use new voices?","Should slang, jokes and cultural references be localized for the new audience?"]},
  {id:"voice:dub-comedy", kind:"voice", when:/(?:\bdub|translat)[\s\S]*(?:stand ?up|comed|joke|sarcas|deadpan|\bcamp\b)|(?:stand ?up|comed)[\s\S]*\bdub/i, add:["jokes adapted so each punchline lands at the same moment as the original","the comedian's pauses before punchlines kept exact","the same energy level: dry stays dry, fast stays fast","culture-specific references swapped for equivalents the new audience gets"]},
  {id:"voice:dub-sensitive-testimony", kind:"voice", when:/(?:\bdub|translat)[\s\S]*(?:testimon|refugee|\bwar\b|survivor|trauma|civilian|archiv|oral history|grandmother|grandfather|stutter|speech impediment|dignity|elderly|human rights|prayer)|(?:testimon|survivor|oral history|grandmother|grandfather)[\s\S]*\bdub/i, add:["faithful translation with nothing softened, added or dramatized","the speaker's own voice kept, emotion neither amplified nor flattened","hesitations, stutters, breaks and silences preserved as spoken","subdued delivery following the original speaker's pauses"]},
  {id:"voice:dub-drama-acting", kind:"voice", when:/(?:\bdub|translat)[\s\S]*(?:drama|\bfilm\b|anime|telenovela|\bscene\b|crying|movie|series|monologue)|(?:drama|anime|telenovela|\bfilm\b)[\s\S]*\bdub/i, add:["emotional peaks matched: cries, breaks and shouts at the original intensity","each character keeping one distinct, consistent voice across episodes","overlapping dialogue kept as separate speakers talking over each other","lip-sync timing held on close-ups"]},
  {id:"voice:dub-creator-vlog", kind:"voice", when:/(?:\bdub|translat)[\s\S]*(?:vlog|youtube|stream|let'?s play|channel|tiktok|tutorial|cooking video|recipe video|my (?:own )?voice|sound(?:ing)? like me)|(?:vlog|youtube|stream)[\s\S]*\bdub/i, add:["the creator's own cloned voice, so it still sounds like them","casual target-language phrasing, the way they would really say it","original energy kept, including excitement, laughs and asides"]},
  {id:"voice:dub-podcast-interview", kind:"voice", when:/(?:\bdub|translat)[\s\S]*(?:podcast|interview|webinar|lecture|conversation)|(?:podcast|interview|webinar|lecture)[\s\S]*\bdub/i, add:["each speaker separated and keeping their own voice","natural conversational back-and-forth timing","laughs, fillers and pauses kept where they carry meaning"]}
];
/** @type {Record<string, {default: string, facts: {when: RegExp, say: string}[]}>} */
const AI_FACTS = {
  "midjourney": {default: "Its --sref style code reuses one image's look, so every picture in a set or campaign matches.", facts: [{when: /\b(series|set of|consistent|matching|same (look|style)|campaign|collection|cohesive)/i, say: "Its --sref style code reuses one image's look, so every picture in the set matches without re-describing the style."}, {when: /\b(fashion|editorial|lookbook|outfit|runway)/i, say: "Fashion imagery is a listed strength; one named light and one lens steer it better than stacked adjectives."}, {when: /\b(concept art|fantasy|sci-?fi|painterly|painting|moody|atmospher|cinematic|album (art|cover)|book cover)/i, say: "It weights the first clause most and reads one lighting and one lens line as direction, giving a painterly, cinematic frame."}, {when: /\b(without|avoid|exclude|keep out|leave out|don'?t want)/i, say: "Its --no flag pushes an element out of the frame, working exactly like a negative weight of -0.5."}, {when: /\b(banner|panorama|ultra-?wide|21:9|header)/i, say: "It renders ratios up to 21:9, so a wide banner or panorama is composed for that shape from the start."}]},
  "gptimage": {default: "It follows a labelled brief closely and renders the exact quoted words inside the picture, in almost any script.", facts: [{when: /\b(text|words?|headline|caption|title|label|lettering|says|slogan|quote)/i, say: "Put the exact copy in quotes and it letters those words legibly, with placement and contrast stated on their own line."}, {when: /\b(infographic|diagram|chart|layout|magazine|editorial|menu|flyer|poster)/i, say: "It reads a labelled, structured brief better than a paragraph, so infographics and magazine layouts land section by section."}, {when: /\b(edit|replace|swap|retouch|same person|keep (the|my|her|his) face|my photo)/i, say: "Its identity-preserving edits change what you ask for while the person in the photo stays recognisable."}, {when: /\b(arabic|hebrew|chinese|japanese|korean|hindi|russian|greek|multilingual|languages?)/i, say: "Multilingual scripts are a listed strength, so non-Latin lettering comes out as real characters."}, {when: /\b(4k|3840|high[- ]res|wallpaper|large screen)/i, say: "It outputs up to 3840x2160, so a wallpaper or large display gets full 4K; custom edges must be multiples of 16."}]},
  "nanobanana": {default: "It reasons about the picture before rendering, so charts, maps and diagrams come out factually correct.", facts: [{when: /\b(infographic|chart|diagram|map|accurate|correct|factual|educational|science|ratio|data)/i, say: "It reasons first and is search-grounded, so asking for mathematically correct ratios measurably improves a chart."}, {when: /\b(same (character|person|people|kid|family)|consistent|cast|characters|family|team|group photo|likeness)/i, say: "It holds likeness for up to five people across reference images, so a recurring cast stays recognisable."}, {when: /\b(4k|high[- ]res|print|large|wallpaper)/i, say: "It renders natively at 4K; set image_size to 4K with a capital K, because lowercase 4k is ignored."}, {when: /\b(edit|tweak|adjust|refine|change (the|it)|step by step)/i, say: "It edits conversationally over several turns, so you refine one image step by step instead of starting over."}, {when: /\b(text|words|labels?|signs?|multilingual|languages?)/i, say: "It renders legible multilingual text inside the image, so labels on a diagram or sign read correctly."}]},
  "flux": {default: "It rewards long, dense, specific prompts with photoreal skin and material texture.", facts: [{when: /\b(product|packshot|e-?commerce|catalog|catalogue|bottle|packaging|mockup)/i, say: "Its Mistral-3 text encoder follows multi-part instructions, so a detailed product brief returns real-looking materials and correct spatial layout."}, {when: /\b(reference|refs|same (product|character|person)|consistent|multiple images)/i, say: "It takes up to 10 reference images, keeping a product or character consistent across shots."}, {when: /\b(photo|photoreal|realistic|real[- ]looking|skin|portrait|texture|material|fabric)/i, say: "Detail is rewarded rather than diluted, so describing skin, fabric and surface texture closely yields convincing photorealism."}, {when: /\b(local|offline|free|my (own )?(gpu|computer|pc)|open[- ]source|self-host)/i, say: "FLUX.2 [klein] at 4B is Apache 2.0 and runs in about 8GB of VRAM, so it runs free on a home GPU."}, {when: /\b(steps|guidance|cfg|fine control|dials?)/i, say: "Pick [flex] when you need steps and guidance dials; [pro] and [max] deliberately hide them."}]},
  "sdxl": {default: "It gives a true negative field, (word:1.2) weighting and the deepest LoRA and ControlNet ecosystem for exact control.", facts: [{when: /\b(pose|controlnet|sketch|depth map|outline|line ?art|match (this|my) (pose|layout))/i, say: "ControlNet lets a pose, depth map or sketch steer the composition, so figures land where you put them."}, {when: /\b(train|lora|fine-?tune|my (own )?(character|style|face)|custom (model|style))/i, say: "Its LoRA ecosystem lets you train your own character or style and combine several in one image."}, {when: /\b(offline|local|private|no internet|my (own )?(gpu|computer|pc)|self-host)/i, say: "It runs fully offline on your own machine, so nothing you make leaves your computer."}, {when: /\b(without|avoid|exclude|keep out|don'?t want|negative)/i, say: "It has a real, separate negative prompt field, so unwanted elements are pushed out directly."}, {when: /\b(emphasi[sz]e|more of|stronger|weight|priority)/i, say: "(word:1.2) weights strengthen one concept; two moderate weights beat one above 1.5, which starts frying the image."}, {when: /\b(1080|full hd|1920|widescreen|16:9)/i, say: "Render at its 1344x768 bucket and upscale; generating 1920x1080 directly is the classic SDXL mistake."}]},
  "ideogram": {default: "It renders in-image text at about 0.97 OCR accuracy, the highest measured, so words come out spelled right.", facts: [{when: /\b(logo|wordmark|brand|packaging|label|can design|box design)/i, say: "Logos and packaging are listed strengths; one keep-out line stops it drifting into a sheet of logo variants."}, {when: /\b(exact (position|placement)|bounding box|in the (top|bottom|corner)|layout|placement)/i, say: "Its JSON prompt takes bounding boxes on a 0-1000 canvas, so each text block sits in an exact position."}, {when: /\b(as written|don'?t (change|rewrite)|exactly what i (say|wrote)|literal)/i, say: "Sending json_prompt turns Magic Prompt off, so the model renders your wording as written instead of a rewrite."}, {when: /\b(poster|flyer|banner|headline|typograph|lettering|title|text|words|slogan)/i, say: "Its text rendering scores about 0.97 OCR accuracy, so headlines and small copy come out spelled correctly."}, {when: /\b(open[- ]weights?|local|self-host|download)/i, say: "Ideogram 4.0 has open weights, so it can run on your own hardware."}]},
  "firefly": {default: "Every output carries Content Credentials and the training data is indemnified, so images are safe to hand to a client.", facts: [{when: /\b(client|commercial|business|brand|ads?\b|advert|marketing|stock|copyright|licens)/i, say: "Its training data is indemnified and each image carries Content Credentials, so client work has documented provenance."}, {when: /\b(photoshop|illustrator|adobe|creative cloud)/i, say: "It round-trips with Photoshop and Illustrator, so a generated image drops straight into your Adobe files."}, {when: /\b(without|avoid|exclude|keep out|leave out|don'?t want)/i, say: "It has a real Exclude field, rare at this tier, so unwanted elements are listed apart from the description."}, {when: /\b(vertical|9:16|stories|reels?|tiktok|phone wallpaper)/i, say: "For vertical 9:16, use Firefly Image 4 or 4 Ultra, because Image 5 has no vertical ratio."}]},
  "recraft": {default: "It exports genuine SVG with real paths that open and edit in Figma and Illustrator.", facts: [{when: /\b(vector|svg|scal|print large|signs?|billboard|vinyl|cutter|embroider|sticker)/i, say: "It outputs true SVG paths, so the design stays sharp at any size, from a sticker to a building sign."}, {when: /\b(logo|wordmark|brand mark|monogram|emblem)/i, say: "Its logos come out as editable SVG paths, so you can adjust curves and colours in Figma or Illustrator."}, {when: /\b(icons?|pictograms?)/i, say: "Icon sets are a listed strength, and SVG output lets each icon scale cleanly from favicon to hero size."}, {when: /\b(brand colou?rs?|hex|rgb|exact colou?rs?|pantone|brand kit)/i, say: "Its controls.colors takes explicit RGB values, which matches brand colours far more accurately than naming them."}, {when: /\b(illustration|flat|clip ?art|graphic)/i, say: "Vector illustration is a core strength, so flat graphics come out as clean editable shapes, not pixels."}]},
  "seedream": {default: "It renders ten-plus languages natively with correct script direction and diacritics, including Arabic, Hebrew and Thai.", facts: [{when: /\b(hebrew|arabic|persian|farsi|urdu|rtl|right[- ]to[- ]left)/i, say: "It writes right-to-left scripts in the correct direction, so Hebrew or Arabic lettering reads properly instead of reversed."}, {when: /\b(thai|vietnamese|diacritics?|accents?|multilingual|languages?|bilingual)/i, say: "It handles diacritics across ten-plus languages natively, so accented or Thai text keeps its marks."}, {when: /\b(infographic|chart|diagram|information|data)/i, say: "Complex information visualisation is a listed strength; state the spatial arrangement and reading order and it follows them."}, {when: /\b(edit|retouch|fix|pixel)/i, say: "It does pixel-level editing, so one part of an image changes without regenerating the rest."}, {when: /\b(texture|photoreal|realistic|material)/i, say: "It renders photorealistic textures; request 1.5K rather than 1K, since it looks better at the same cost."}]},
  "qwenimage": {default: "It renders text as small as ten pixels legibly in one pass, built for dense layouts with many text regions.", facts: [{when: /\b(math|maths|equations?|formula|latex|academic|scientific)/i, say: "It renders multi-line maths notation from LaTeX, so equations in a paper mockup come out as real formulas."}, {when: /\b(chinese|mandarin|cantonese|hanzi)/i, say: "It is the strongest option for dense Chinese text, among twelve languages it renders natively."}, {when: /\b(ui|app screen|dashboard|interface|website mockup|wireframe)/i, say: "Nested UI designs are a listed strength; describe every region and its contents and it lays them out in one image."}, {when: /\b(newspaper|magazine page|infographic|grid|dense|lots of text|small text|many labels)/i, say: "It accepts up to 4500 tokens of layout description and renders dense pages in one pass, legible down to ten pixels."}, {when: /\b(without|avoid|exclude|keep out|leave out|don'?t want)/i, say: "It has a dedicated negative_prompt field, so unwanted elements are excluded apart from the layout description."}]},
  "leonardo": {default: "It trains personal models and character LoRAs, so the same character or style repeats across many images.", facts: [{when: /\b(same character|recurring|mascot|my character|consistent character|character sheet)/i, say: "A Character Reference image, at strength LOW to HIGH, keeps your character's look across new images better than extra words."}, {when: /\b(train|my (own )?style|custom model|fine-?tune|lora)/i, say: "It trains custom models and character LoRAs on your own images, which is the main reason to choose it."}, {when: /\b(sketch|doodle|drawing|real-?time|canvas)/i, say: "Its Realtime Canvas turns a rough sketch into an image as you draw."}, {when: /\b(game|sprites?|assets?|concept art|rpg|tiles?)/i, say: "Game and concept-art asset pipelines are a listed strength, with trained models keeping a whole asset set in one style."}, {when: /\b(lots of|many images|batch|hundreds|volume|bulk)/i, say: "It is cost-efficient at volume, and Fast mode at 1440x1440 is Leonardo's own recommended sweet spot."}]},
  "generic-image": {default: "Name one lens, one light and one colour grade; every 2026 image model rewards those, and almost none reward 'masterpiece'.", facts: [{when: /\b(stable diffusion|sd ?1\.5|older model|clip|tags?)/i, say: "Older CLIP-based models want comma tags while newer language-encoder models want prose, so match the grammar to the model."}, {when: /\b(without|avoid|exclude|keep out|don'?t want|negative)/i, say: "Check whether the model has a negative field; if not, describe the wanted state positively in the main prompt."}, {when: /\b(text|words|headline|title|caption|label)/i, say: "Quote the exact words to render, so the model treats them as copy to letter rather than part of the scene."}, {when: /\b(brand colou?rs?|hex|exact colou?rs?|palette)/i, say: "Hex codes beat colour names when the brand matters, so give exact values for brand colours."}, {when: /\b(banner|header|thumbnail|instagram|story|print|poster)/i, say: "Say where the image will be used, because that changes framing, crop and safety margins."}, {when: /\b(lighting|light|mood|atmosphere)/i, say: "Pick one or two lighting setups; stacking more dilutes each one."}]},
  "veo": {default: "It generates synced dialogue, sound effects and ambience in the same pass as the picture.", facts: [{when: /\b(talk|talking|dialogue|speak|says|conversation|lip|interview|lines?)/i, say: "Write dialogue in quotes and it generates lip-synced speech; under about fifteen words per eight seconds keeps sync."}, {when: /\b(sound|audio|sfx|ambien|noise|music)/i, say: "It creates SFX and ambience natively, each on its own labelled line, so the clip arrives with matching sound."}, {when: /\b(vertical|9:16|reels?|tiktok|youtube shorts?|stories)/i, say: "It outputs native 9:16 as well as 16:9, so a vertical Reel or Short is framed for the phone."}, {when: /\b(4k|1080|high[- ]res|crisp|sharp)/i, say: "It delivers clean 1080p and 4K on eight-second clips."}, {when: /\b(realistic|physics|real[- ]world|believable|plausib)/i, say: "Physical plausibility is a listed strength, so objects fall, splash and collide believably."}]},
  "kling": {default: "It plans several shots in one generation and binds elements, so a character keeps the same identity across cuts.", facts: [{when: /\b(same character|consistent|identity|mascot|recurring|keep (her|his|their|the) face)/i, say: "Element binding locks a character's identity; without it, identity drifts badly past about eight seconds."}, {when: /\b(shots|scenes?|cuts?|sequence|story|trailer|multi-?shot)/i, say: "It plans several shots per generation from a shot list, so a short sequence comes out already cut."}, {when: /\b(motion transfer|dance|copy (the|this) (dance|move)|mimic|reference video)/i, say: "It does motion transfer, so the movement from a reference performance drives your character."}, {when: /\b(camera move|dolly|orbit|crane|tracking shot|pan)/i, say: "Its Master Shots camera presets are more stable than prompted camera language when the move matters."}, {when: /\b(spanish|chinese|japanese|french|german|korean|hindi|non-english|languages?)/i, say: "Non-English dialogue is a listed strength, so characters can speak your audience's language on screen."}, {when: /\b(4k|high[- ]res|15 ?s|fifteen seconds)/i, say: "It outputs 4K, with clips up to 15 seconds."}]},
  "seedance": {default: "It generates up to thirty seconds in one continuous take, the longest of any major model.", facts: [{when: /\b(30|thirty|one take|continuous|uncut|single shot|20 ?s|twenty seconds|long clip)/i, say: "It runs up to 30 seconds in one take; budget the prompt across the whole timeline so later seconds don't drift."}, {when: /\b(products?|e-?commerce|skus?|shop|store|catalog|listing)/i, say: "Product and multi-SKU e-commerce video is a listed strength, with omni reference keeping each item consistent."}, {when: /\b(same (character|person|product)|consistent|references?|identity)/i, say: "Omni reference holds identity across many reference images, so a person or product looks the same throughout."}, {when: /\b(edit|extend|longer|continue|change (the|my) video)/i, say: "It edits and extends video natively, so you lengthen or change a clip instead of regenerating it."}, {when: /\b(4k|1080|high[- ]res)/i, say: "Use mode std for high resolution, because Fast mode caps at 720p."}]},
  "runway": {default: "It follows complex sequenced instructions closely and captures subtle facial emotion.", facts: [{when: /\b(sequence|step by step|in order|and then|first .{1,40} then)/i, say: "Its adherence on sequenced instructions is best-in-class, so 'she turns, pauses, then smiles' plays in that order."}, {when: /\b(emotion|facial|face|expression|cry|crying|smile|actor|performance|close-?up)/i, say: "Facial nuance is a listed strength, so close-ups carry small emotional shifts convincingly."}, {when: /\b(animate|bring .{0,20}to life|from (my|this|an?) (photo|image|picture|still)|image[- ]to[- ]video)/i, say: "For image-to-video, describe only what changes; re-describing what is already in the image creates conflict."}, {when: /\b(vertical|9:16|reels?|tiktok|stories)/i, say: "Vertical 9:16 works through image-to-video: generate a still first, then animate it."}, {when: /\b(styli[sz]ed|animation|anime|cartoon|photoreal)/i, say: "It covers both photoreal and stylised looks, a listed strength."}]},
  "hailuo": {default: "It renders facial micro-expressions and natural physics, with camera moves written inline as [pan] or [zoom].", facts: [{when: /\b(emotion|facial|face|expression|subtle|micro)/i, say: "Facial micro-expression is its listed strength, so small shifts like a held-back smile read on screen."}, {when: /\b(camera|pan|zoom|static|tripod)/i, say: "It accepts inline bracketed camera instructions like [pan], [zoom] and [static], placed where the move happens."}, {when: /\b(logo|brand|text|sign|product name)/i, say: "Text and brand rendering is a listed strength, so a logo or sign stays legible in motion."}, {when: /\b(motion transfer|copy (the|this) (dance|move)|reference video|video[- ]to[- ]video)/i, say: "Its video-to-video motion transfer drives your subject with the movement from a reference clip."}, {when: /\b(physics|water|splash|falling|cloth|fabric)/i, say: "Natural physics is a listed strength, so water, fabric and falling objects move believably."}, {when: /\b(detailed|lots of detail|complex scene|long description)/i, say: "It accepts prompts up to 7000 characters, so a detailed scene description fits whole."}]},
  "luma": {default: "It places up to sixteen keyframes per clip, so you lock exactly when each action happens.", facts: [{when: /\b(beat|music video|timing|sync|rhythm|pacing)/i, say: "Sixteen keyframes let you pin action changes on the beat, so moves land in time with the music."}, {when: /\b(hdr|exr|aces|colou?r grad|post[- ]production|davinci|resolve|nuke|vfx|compositing)/i, say: "It exports native 16-bit HDR as ACES EXR, so footage drops into a colour-managed grading pipeline."}, {when: /\b(story|sequence|events?|narrative|and then)/i, say: "Its reasoning mode plans event sequences, so narrative prose like 'X happens, then Y' beats keyword stacks."}, {when: /\b(20 ?s|twenty seconds|longer clip|1080)/i, say: "It renders up to 20 seconds at 1080p in one clip."}, {when: /\b(drafts?|iterat|test versions|quick previews?)/i, say: "Draft mode lets you iterate first and master only the take you keep, avoiding 4K HDR renders of every attempt."}]},
  "ltx": {default: "It has genuinely open weights and native 4K, so you can run it on your own hardware.", facts: [{when: /\b(sports?|48 ?fps|50 ?fps|frame ?rate|fps|pal|broadcast)/i, say: "It exposes 48 and 50fps, the only model here that does, which suits sports and PAL broadcast."}, {when: /\b(local|self-host|offline|open[- ]source|my (own )?(gpu|server|computer))/i, say: "Its open weights run locally or self-hosted, so long productions cost nothing per clip at scale."}, {when: /\b(lip ?sync|talking|dialogue|speak)/i, say: "It does lip sync, so spoken lines match mouth movement."}, {when: /\b(fix|redo|retake|one (bad )?(shot|beat|part)|replace a section)/i, say: "Retake regenerates a 2-16 second segment, so one bad beat is fixed without reshooting the whole clip."}, {when: /\b(shot list|storyboard|several shots|scenes|short film|episode)/i, say: "LTX Studio is built around a shot list with @Element references, so a short film is planned shot by shot."}]},
  "higgsfield": {default: "It offers sixty-three named camera presets, so a move like Bullet Time or Crash Zoom In is reliable rather than prompted.", facts: [{when: /\b(bullet time|crash zoom|snorricam|dolly|orbit|whip pan|yo-?yo|camera move)/i, say: "Named presets like Bullet Time, Crash Zoom In and Snorricam give that exact move; most need an uploaded start image."}, {when: /\b(ads?\b|advert|commercial|marketing|promo|ugc)/i, say: "Ad and marketing formats are a listed strength, with named camera moves that repeat reliably across product shots."}, {when: /\b(exactly|literal|follow (my|the) prompt|creative freedom|loose)/i, say: "Its cfg_scale dial runs 0 to 1: about 0.3 gives creative latitude, about 0.8 gives literal adherence."}, {when: /\b(speed ramp|slow[- ]?mo|ramp)/i, say: "It supports speed ramps, so action can shift from slow motion into real time within a shot."}, {when: /\b(compare|different models|which model|many models|several models)/i, say: "It is an aggregator, giving access to many video models behind one interface."}]},
  "wan": {default: "Wan 2.6 has open weights for local use, while 2.7's Thinking Mode plans the composition before generating.", facts: [{when: /\b(local|offline|open[- ]source|self-host|my (own )?(gpu|computer|pc))/i, say: "Wan 2.6 has open weights, so it runs on your own machine; 2.7 is API-only."}, {when: /\b(meaning|symbolic|metaphor|intent|story)/i, say: "2.7's Thinking Mode builds a compositional blueprint first, so stating what the scene means steers it."}, {when: /\b(styli[sz]ed|experimental|abstract|surreal|weird|artsy)/i, say: "Stylised and experimental output is a listed strength, suited to abstract or surreal clips."}, {when: /\b(languages?|multilingual|chinese|spanish|audio|voice)/i, say: "Multilingual audio is a listed strength, with speech across twelve languages."}]},
  "mjvideo": {default: "It animates a Midjourney still and keeps the Midjourney look in every frame.", facts: [{when: /\b(loop|looping|seamless|gif|repeat|motion graphic)/i, say: "Looping motion graphics are a listed strength, so a short repeating animation keeps Midjourney's styling."}, {when: /\b(nothing moves|more motion|dynamic|energetic|action)/i, say: "Set --motion high; the default --motion low gives near-still results."}, {when: /\b(follow (my|the) prompt|exactly|literal|less styli[sz]ed|raw)/i, say: "--raw turns off the house styling, so the video follows your prompt rather than Midjourney's taste."}, {when: /\b(longer|21 seconds|twenty-one|extend)/i, say: "Extend four times at about four seconds each to reach twenty-one seconds."}, {when: /\b(animate|bring .{0,20}to life|my midjourney|from (my|this) image)/i, say: "Describe only the motion in five to twenty-five words, and let the still carry the look."}]},
  "generic-video": {default: "Describe motion over time rather than a still image; that is the top failure mode on every video model.", facts: [{when: /\b(camera|dolly|orbit|pan|tilt|crane|drone)/i, say: "Use one camera move per shot; stacking dolly, orbit and tilt produces mush on every model."}, {when: /\b(cinematic|film look|movie look)/i, say: "'Cinematic' alone does nothing in 2026; name the shot, lens and light instead."}, {when: /\b(animate|from (my|this|an?) (photo|image|picture|still)|image[- ]to[- ]video)/i, say: "For image-to-video, delete everything that re-describes the still and keep only what changes."}, {when: /\b(sound|audio|dialogue|talk|speak|sfx)/i, say: "Write dialogue in quotes, then SFX, then ambience, and delete that block if your model makes no audio."}, {when: /\b(without|avoid|exclude|keep out|leave out|don'?t want)/i, say: "Keep exclusions in a separate negative block, and delete it if your model has no negative field."}]},
  "el-tts": {default: "Its v3 model reads inline audio tags like [whispers] and [sighs], so delivery is directed inside the script itself.", facts: [{when: /\b(clon\w*|in (?:his|her|my|their|our|\w+'?s) (?:own )?voice|voicemails?|recordings? of (?:him|her|me|them)|copy of (?:my|his|her) (?:own )?voice)/i, say: "Instant Voice Cloning builds a voice from a minute or two of clean recordings (Professional Voice Cloning wants 30 minutes or more). Only clone a voice with that person's permission."}, {when: /\b(audiobook|narrat|chapter|long[- ]form|podcast)/i, say: "Long-form narration is a listed strength; give it full paragraphs, since inputs under 250 characters come out inconsistent."}, {when: /\b(dialogue|conversation|two (people|voices|speakers)|multi-?speaker|interview)/i, say: "It renders multi-speaker dialogue in a single pass, so a two-person scene needs no stitching."}, {when: /\b(whisper|sigh|laugh|sarcas|emotion|angry|excited|character|acting)/i, say: "v3 reads inline tags like [whispers], [sighs] and [sarcastic], so the acting is written into the line."}, {when: /\b(languages?|spanish|french|german|hindi|arabic|multilingual|translat)/i, say: "It speaks seventy-plus languages, so one script can be voiced for several audiences."}, {when: /\b(pronounc|brand name|ipa)/i, say: "On v3, inline IPA between forward slashes fixes how a brand name or unusual word is pronounced."}, {when: /\b(pauses?|emphasis|stress|slow down|hesitat)/i, say: "Ellipses add hesitation, dashes add short pauses and CAPITALS add stress, giving direct control over pacing."}]},
  "el-voicedesign": {default: "It invents an original voice from a written description, so the narrator does not sound like a stock voice.", facts: [{when: /\b(reverb|echo|room|hall|cave|phone effect|radio effect)/i, say: "It models the voice, not the room, so add reverb or phone effects in the mix afterwards."}, {when: /\b(brand voice|mascot|signature voice|unique voice|original voice|our voice)/i, say: "It designs a brand voice from a description, so it does not sound like a stock voice anyone can pick."}, {when: /\b(character|villain|hero|wizard|robot|creature|game|npc)/i, say: "Original characters are a listed strength; give a persona in two to five words plus two or three emotion adjectives."}, {when: /\b(accent|dialect|british|american|australian|irish|scottish|southern|locale)/i, say: "Naming the native language and exact dialect first, not just 'accent', is the documented first step."}, {when: /\b(broadcast|studio|professional|high quality)/i, say: "Naming a rung of its quality ladder, like Studio or Broadcast, genuinely changes the output."}]},
  "el-dubbing": {default: "It dubs finished video into ninety-plus languages while keeping the original voices and the background sound.", facts: [{when: /\b((several|multiple|many|two|three) (people|speakers|voices)|interview|panel|podcast|overlap)/i, say: "It handles up to 32 speakers and overlapping speech, so interviews and panels dub correctly."}, {when: /\b(background|music bed|ambien|keep the music|sound effects)/i, say: "It keeps the background bed, so music and effects stay intact without remixing the video."}, {when: /\b(performance|emotion|tone|acting|same voice|sound like)/i, say: "Raise speaker similarity (0 to 10, default 7) when the original performance is the point."}, {when: /\b(translat|dub|another language|spanish|french|german|portuguese|japanese|hindi|locali[sz])/i, say: "It dubs into ninety-plus languages and keeps the original voices, so speakers still sound like themselves."}, {when: /\b(feature|film|movie|hours?|course|long video)/i, say: "The API takes files up to 3GB, and the app handles up to 180 minutes."}]},
  "cartesia": {default: "It starts speaking in under 90ms, built for realtime voice agents that must answer without a pause.", facts: [{when: /\b(order numbers?|phone numbers?|numbers|codes?|alphanumeric|serial|tracking|digits)/i, say: "Alphanumerics like order and phone numbers are a listed strength, so they are read out correctly."}, {when: /\b(brand names?|pronounc|ipa)/i, say: "Custom pronunciation dictionaries with IPA overrides reliably fix how brand names are said."}, {when: /\b(clone|my (own )?voice|copy (a|my) voice)/i, say: "It clones a voice from about 10 seconds of audio."}, {when: /\b(bilingual|switch(ing)? languages|code[- ]?switch|spanglish|mixed languages?)/i, say: "It handles code-switching, so sentences that mix two languages are read without breaking voice."}, {when: /\b(agent|assistant|bot|realtime|real[- ]time|live|calls?|phone|telephon|ivr|customer service)/i, say: "First audio arrives in under 90ms, so a phone or voice agent answers without an awkward gap."}, {when: /\b(consistent|same every time|predictable|speed|volume)/i, say: "Emotion, speed and volume are API parameters rather than prompt text, so delivery is repeatable."}]},
  "hume": {default: "It takes short acting instructions like 'frightened, rushed' as their own input and performs the line that way.", facts: [{when: /\b(child|kids|crowd|audience|students|bedtime)/i, say: "Naming the audience, like 'speaking to a child', shapes the delivery directly."}, {when: /\b(mid-?line|changes? (tone|mood)|shifts?)/i, say: "Direction can change mid-line, so a sentence can start calm and end frightened."}, {when: /\b(emotion|scared|frightened|angry|sad|melanchol|nervous|dramatic)/i, say: "Precise emotions like 'melancholy' or 'frustrated' steer delivery better than 'sad', and short directions beat paragraphs."}, {when: /\b(character|villain|game|npc|role|voice acting|acting)/i, say: "Character work is a listed strength; acting directions under about 100 characters change how each line is performed."}, {when: /\b(fast|slow|speed|pace)/i, say: "Speed runs 0.5 to 2.0 and is non-linear, so 2.0 is not double speed."}]},
  "generic-voice": {default: "Punctuation is prosody on every modern engine: ellipses hesitate, dashes clip and capitals stress.", facts: [{when: /\b(short|one line|single line|greeting|notification)/i, say: "Very short inputs come out unstable on many engines; give a full paragraph and trim the audio afterwards."}, {when: /\b(whisper|sigh|laugh|audio tags?)/i, say: "Bracketed audio tags are an ElevenLabs v3 convention; strip them unless your engine documents them."}, {when: /\b(accent|dialect|british|american|australian|locale)/i, say: "Name the exact dialect, not just the language, so the voice matches the region."}, {when: /\b(audiobook|narrat|commercial|trailer|e-?learning|ivr|meditation|asmr)/i, say: "State what the read is for, like audiobook or IVR, so pace and energy fit the use."}]},
  "el-sfx": {default: "It generates one sound effect per call, 0.5 to 30 seconds long, as a clean element you layer in an editor.", facts: [{when: /\b(loop|seamless|repeat|endless|forever|ambien|background)/i, say: "It has a seamless loop option, so an ambience bed or engine hum can play forever without an audible seam."}, {when: /\b(ui|button|click|notification|menu|coin|pickup|game sound)/i, say: "UI sounds and one-shots are listed strengths, so each button click or coin pickup comes as its own clean file."}, {when: /\b(footsteps?|foley|door|punch|impact|crash|hit|whoosh|swoosh)/i, say: "Foley, impacts and whooshes are listed strengths, and phrasing like 'professionally recorded footsteps on grass' improves results."}, {when: /\b(drums?|beat|bpm|stabs?|riff|musical)/i, say: "Musical one-shots work well, like '90s hip-hop drum loop, 90 BPM', with tempo and key stated."}, {when: /\b(exact|precise|literal|specific sound)/i, say: "Raise prompt_influence from its loose 0.3 default toward 0.8 when the sound must match your words literally."}, {when: /\b(scene|several sounds|multiple sounds|soundscape)/i, say: "Generate each element separately and layer them, as its docs recommend, rather than one multi-event prompt."}]},
  "generic-sfx": {default: "Name the source, the material it hits, the space it happens in and how the tail behaves.", facts: [{when: /\b(scene|sequence|several sounds|multiple sounds|soundscape)/i, say: "Generate one event per call and layer them in an editor; that holds on every sound model."}, {when: /\b(room|hall|cave|outdoors?|indoors?|echo|reverb|space)/i, say: "State the space, from bone-dry booth to cathedral, because the room shapes the reverb tail."}, {when: /\b(loop|seamless|repeat|ambien|background)/i, say: "Ask for a seamless loop when the sound must repeat, and check your tool offers that setting."}, {when: /\b(close|mic|recorded|realistic|foley)/i, say: "Naming the capture, like a shotgun mic or binaural pair, changes how close and real the sound feels."}]},
  "el-music": {default: "It responds audibly to studio terms like sidechained, close-mic'd, tape saturation and plate reverb.", facts: [{when: /\b(background|underscore|bed|youtube|podcast|vlog)/i, say: "Underscore and beds are a listed strength, and lines like 'no melody, just drums' keep a loop out of the voice's way."}, {when: /\b(fix (the|one) part|section|inpaint|edit)/i, say: "Section editing regenerates one part of a track while the rest stays as it is."}, {when: /\b(transition|switch(es)? (to|from)|genre change|morph)/i, say: "It handles mid-track genre transitions, so a song can move from one style into another."}, {when: /\b(lyrics (start|begin)|timing|at \d+ seconds|timed)/i, say: "Timing directives like 'lyrics begin at 15 seconds' work, so you place events in the track."}, {when: /\b(full song|songs?|5 minutes|five minutes|structure|verse|chorus)/i, say: "It makes structured full songs up to five minutes long, so a track can build through its sections."}, {when: /\b(provenance|c2pa|credentials|ai[- ]generated label)/i, say: "C2PA credentials are optional, so you can attach provenance when a client needs it."}]},
  "suno": {default: "It has separate Style and Lyrics fields plus an Exclude Styles box, the reliable way to keep an element out.", facts: [{when: /\b(without|avoid|exclude|don'?t want|leave out|no (drums|guitar|vocals|autotune|synths?))/i, say: "The Exclude Styles box removes elements reliably; negatives typed in the Style field are ignored."}, {when: /\b(persona|same (voice|singer)|custom model|my style)/i, say: "Personas and custom models keep a singer's voice and style consistent across songs."}, {when: /\b(weird|experimental|strange|unusual)/i, say: "The Weirdness slider, 50% by default, pushes it toward stranger choices; Style Influence sets how strictly it obeys."}, {when: /\b(lyrics|vocals?|sing|singer|songs?|chorus|verse|rap)/i, say: "Metatags like [Verse 1], [Chorus] and [Bridge] in the Lyrics field set the structure of a full vocal song."}, {when: /\b(quick|fast|several versions|variations|ideas|demo)/i, say: "Fast iteration is a listed strength, so you can hear several versions of a song idea quickly."}]},
  "lyria": {default: "It writes three-minute songs with full structure, timed with [MM:SS] timestamp prompts.", facts: [{when: /\b(scor|to picture|video|film|trailer|cuts?|sync|timed|timestamp)/i, say: "[MM:SS] timestamp tags assign musical changes to exact moments, so the score hits your video's cuts."}, {when: /\b(image|photo|picture|pdf|mood ?board)/i, say: "It takes an image or PDF as input, so music can be generated from a reference picture or brief."}, {when: /\b(provenance|watermark|c2pa|synthid|ai[- ]generated|disclos)/i, say: "Every output carries SynthID and C2PA credentials, so its AI origin can be verified."}, {when: /\b(lyrics|vocals?|sing|singer)/i, say: "It sings timed lyrics, so you can place each line at a specific timestamp."}, {when: /\b(full song|3 minutes|three minutes|structure)/i, say: "Lyria 3 Pro makes three-minute songs, while the non-Pro tiers stop at thirty seconds."}]},
  "stableaudio": {default: "Its audio inpainting regenerates a chosen span of an existing track and leaves the rest untouched.", facts: [{when: /\b(fix|redo|replace|one (part|section)|span|inpaint|edit)/i, say: "Audio inpainting regenerates just the bad span, so you fix one section without redoing the whole track."}, {when: /\b(brand|jingle|sonic logo|corporate|company)/i, say: "Brand and production sound is what it is built for, using Stability's order: style, instruments, mood, details."}, {when: /\b(80s|90s|70s|retro|vintage|era|decade)/i, say: "Naming an era, like '80s gated reverb', does real work here and changes the production sound."}, {when: /\b(bpm|tempo|house|techno|disco|ballad|dubstep)/i, say: "Stability publish tempo bands, like 120-140 BPM for disco and techno, so stating BPM sets the genre's pace."}, {when: /\b(loops?|bed|background|ambient)/i, say: "Loops and beds are a listed strength, suited to background music under video or apps."}]},
  "generic-music": {default: "Give a short style line plus the arrangement narrated in order, which every music model reads well.", facts: [{when: /\b(bpm|tempo|key|major|minor)/i, say: "State BPM and key as numbers and letters, like 92 BPM in D minor, rather than 'fast' or 'sad'."}, {when: /\b(chorus|verse|bridge|intro|outro|structure)/i, say: "Section tags like [Chorus] are a Suno and ElevenLabs convention, so check your tool before pasting them."}, {when: /\b(without|avoid|exclude|keep out|leave out|don'?t want)/i, say: "Put unwanted instruments in an exclude field if your tool has one, not in the style line."}, {when: /\b(builds?|arrangement|drop|starts? with)/i, say: "Narrate the arrangement in order, 'start with... then bring in...', so the track develops as planned."}]},
  "claude": {default: "Place long material first and the question last; Anthropic measure up to 30% better results on complex inputs that way.", facts: [{when: /\b(refactor|codebase|multi-?file|code review|review my code|large project)/i, say: "Multi-file refactors and precise code review are listed strengths, backed by a 1M-token context that holds a whole codebase."}, {when: /\b(decks?|slides?|presentation|powerpoint)/i, say: "Documents and decks are a listed strength, so it drafts structured slide content and reports."}, {when: /\b(documents?|pdfs?|reports?|contracts?|papers?|transcripts?|summari[sz]e|book)/i, say: "Put the long documents at the top and the question at the end; Anthropic measure up to 30% better answers."}, {when: /\b(agent|autonomous|long[- ]running|automat)/i, say: "Long-horizon autonomy is a listed strength, so it stays on task across a long multi-step job."}, {when: /\b(examples?|format|consistent|template|style guide)/i, say: "Three to five examples in <example> tags, including an edge case, lock the output format reliably."}, {when: /\b(short|brief|concise|one paragraph|tl;?dr)/i, say: "It is verbose by default, so ask for short output in words; effort settings do not shorten the answer."}]},
  "gpt": {default: "It works best with a pruned prompt in Identity, Instructions, Examples, Context order; OpenAI measured 10-15% gains from simplifying.", facts: [{when: /\b(browse|web|search|look up|current|latest|news)/i, say: "Knowledge work with browsing is a listed strength, so it checks current information as it works."}, {when: /\b(security|cyber|vulnerab|pentest|exploit|ctf)/i, say: "Cybersecurity is a listed strength, useful for reviewing code and systems for vulnerabilities."}, {when: /\b(computer use|click|fill (in|out)|operate|navigate (the|a) (site|website|app))/i, say: "Computer use is a listed strength, so it can operate apps and websites step by step."}, {when: /\b(design|ui|layout|visual)/i, say: "Design judgment is a listed strength, so it gives useful critique on layouts and interfaces."}, {when: /\b(rules?|system prompt|instructions|policy|guidelines)/i, say: "State each rule exactly once; OpenAI found repetition lowers scores, and pruning cut tokens by 41-66%."}, {when: /\b(hard|complex|tricky|ambiguous)/i, say: "As a reasoning model it wants goals, not steps, like briefing a senior co-worker."}]},
  "gemini": {default: "It handles huge multimodal context, so long documents, images and video can be read in one request.", facts: [{when: /\b(video|image|photo|screenshot|audio|multimodal|recording)/i, say: "Its huge multimodal context takes videos, images and documents together, so they are analysed in one request."}, {when: /\b(only (use|from)|grounded|no made[- ]up|hallucinat|stick to)/i, say: "Adding 'rely only on facts directly mentioned in the provided context' keeps its answers grounded in your material."}, {when: /\b(pdf|documents?|contracts?|reports?|spreadsheet|extract)/i, say: "Document comprehension is a listed strength; put the documents first and the specific ask at the very end."}, {when: /\b(cheap|budget|cost|affordable|bulk|automat)/i, say: "Price and performance on coding and agents is its listed strength, suited to high-volume automation."}, {when: /\b(detailed|conversational|friendly|chatty|long answer)/i, say: "Its default output is terse, so ask explicitly for a detailed or conversational answer."}]},
  "grok": {default: "It calls tools cheaply with a 500k-token context window, suited to agent workflows.", facts: [{when: /\b(current|latest|today|recent|news|this (week|month|year)\b)|\b2026/i, say: "Its knowledge stops at February 2026, so turn on server-side search for anything current."}, {when: /\b(agent|tools?|function call|api calls?|automat|workflow)/i, say: "Agentic tool calling is a listed strength, with a 500k-token window to hold the tool results."}, {when: /\b(long|large|big) (documents?|files?|codebases?|context)/i, say: "Its 500k-token window holds a large file or codebase; staying under 200k tokens avoids the doubled price."}, {when: /\b(cheap|budget|cost|affordable)/i, say: "Cheap coding is a listed strength; set prompt_cache_key so repeat requests reuse cached input."}]},
  "deepseek": {default: "It costs about an order of magnitude less per token than peers and ships MIT-licensed weights you can self-host.", facts: [{when: /\b(cheap|budget|cost|affordable|bulk|batch|thousands)/i, say: "Off-peak hours run at half price, so scheduling batch jobs then cuts cost by 50%."}, {when: /\b(self-host|local|offline|open[- ]source|own server|private)/i, say: "Its weights are MIT-licensed, so you can run it on your own servers."}, {when: /\b(very long|book|whole|entire|full) (outputs?|documents?|reports?|files?|code|chapters?)/i, say: "It writes up to 384k output tokens, so a very long document or file comes out in one response."}, {when: /\b(prefill|start (the|its) (answer|response)|force (the|a) format|json)/i, say: "It still supports prefilling, so you can start its reply yourself and lock the output format."}, {when: /\b(code|coding|program|script|bugs?)/i, say: "Coding is a listed strength at about an order of magnitude below peer prices."}]},
  "generic-text": {default: "Specify the output format exactly; it is the single strongest lever across every vendor's guide.", facts: [{when: /\b(format|table|json|list|bullets?|template|structure)/i, say: "Spell out the exact output format, like a table with named columns; every vendor guide ranks this strongest."}, {when: /\b(paste|document|email|data|text below|article|transcript)/i, say: "Wrap pasted material in delimiters, which reduces misattribution and prompt-injection risk on every model."}, {when: /\b(step by step|reason|think|logic|math|puzzle)/i, say: "Use the model's own reasoning setting instead of 'think step by step', which is largely obsolete on 2026 frontier models."}, {when: /\b(local|offline|ollama|llama|open[- ]source|private)/i, say: "It works with any chat model, including local ones, because it uses nothing vendor-specific."}]},
  "claudecode": {default: "It works through explore, plan, implement, commit, and checks itself against a runnable test or build.", facts: [{when: /\b(tests?|build|ci\b|failing|passes|verify)/i, say: "Given a check that exits 0, like tests or a build, it can tell done from nearly done."}, {when: /\b(migrat|upgrade|rename|across (the|all)|every file|many files)/i, say: "Parallel fan-out migrations are a listed strength, so one change is applied across many files in parallel."}, {when: /\b(understand|explain|onboard|new to (the|this) (code|repo)|how does|where is)/i, say: "Codebase questions and onboarding are listed strengths, so it reads the repo and explains how the parts connect."}, {when: /\b(review|second opinion|audit|double[- ]check)/i, say: "A subagent review in fresh context catches gaps that the same session tends to miss."}, {when: /\b(feature|from scratch|new (app|project)|spec)/i, say: "For big features it interviews you, writes SPEC.md, then builds from that plan in a fresh session."}, {when: /\b(rules|conventions|always|remember|claude\.md)/i, say: "A lean CLAUDE.md carries project rules into every session, so conventions persist without repeating them."}]},
  "cursor": {default: "It plans before building, and its official fix for wrong output is to refine the plan rather than patch the code.", facts: [{when: /\b(monorepo|packages|frontend and backend|different (folders|parts)|scoped rules)/i, say: "Glob-scoped .mdc rules apply only to matching paths, so each part of a monorepo gets its own conventions."}, {when: /\b(rules?|conventions|style guide|always use)/i, say: "Rules must be .mdc files inside .cursor/rules/; a plain .md file there silently does nothing."}, {when: /\b(this file|component|this function|these files|reference)/i, say: "Reference files with @filename instead of pasting them, so it reads the current version directly."}, {when: /\b(quick|small|tweak|fix|in (my|the) editor|inline)/i, say: "Fast in-editor iteration is its listed strength, so small edits happen right where the code is."}, {when: /\b(feature|plan|several steps)/i, say: "Plan mode suits medium features: agree the plan, build, and fix the plan rather than patching bad output."}]},
  "copilot": {default: "It reads short repo-wide instructions plus path-scoped .instructions.md files, so conventions apply exactly where they belong.", facts: [{when: /\b(monorepo|large (repo|codebase)|many (teams|folders)|different (folders|parts))/i, say: "Path-scoped .instructions.md files with applyTo frontmatter give each folder its own rules in a large monorepo."}, {when: /\b(conventions?|team|standards?|style guide|consistent)/i, say: "Repo-wide conventions are its listed strength; keep instructions short, self-contained and broadly applicable."}, {when: /\b(models?|claude|gpt|gemini|switch)/i, say: "It offers broad model choice, so you can switch the underlying model for each task."}]},
  "codex": {default: "It reads AGENTS.md and lets you set effort, with the official rule to use the lowest level that works.", facts: [{when: /\b(ambiguous|hard|deep|analy|architecture|tricky)/i, say: "For ambiguous, high-value work, Sol handles deep analysis, while everyday tasks fit Terra."}, {when: /\b(repeat|extract|same task|routine)/i, say: "Luna suits repeatable extraction, keeping routine jobs at the lowest effort that works."}, {when: /\b(other models?|local model|open[- ]source|own model|ollama|any model)/i, say: "It points at any model implementing Chat Completions or Responses, not only OpenAI's."}, {when: /\b(rules|conventions|agents\.md|instructions)/i, say: "It reads AGENTS.md, so project rules written once apply to every task."}, {when: /\b(parallel|many agents|huge|massive)/i, say: "Ultra spawns parallel agents for big jobs, though its cost grows non-linearly."}]},
  "devin": {default: "It runs well-scoped tasks asynchronously, judged against measurable success criteria you set.", facts: [{when: /\b(background|while i|overnight|async|hand off|delegate)/i, say: "Async remote work is its listed strength, so it works on the task while you do something else."}, {when: /\b(done when|success|criteria|acceptance)/i, say: "Measurable success criteria are one of its four prompt components, giving it a clear finish line."}, {when: /\b(existing pattern|same pattern|follow|match (the|our))/i, say: "Pointing it at an existing pattern to follow is a documented prompt component, so new code matches yours."}, {when: /\b(procedure|every time|recurring|process|playbook)/i, say: "Playbooks store procedures it repeats, and Knowledge holds standards that persist across tasks."}, {when: /\b(rules|conventions|windsurf|config)/i, say: "Rules files cap at 6,000 characters global and 12,000 per workspace file; longer ones silently truncate."}]},
  "generic-code": {default: "Write project rules in AGENTS.md, the closest cross-tool standard: Cursor, Codex, Copilot and Devin Desktop all read it.", facts: [{when: /\b(tests?|done|verify|check)/i, say: "Make the success criterion a command that can be run, like a test; one that cannot be checked is not a criterion."}, {when: /\b(rules|conventions|agents\.md|instructions|config)/i, say: "Put project rules in AGENTS.md, which Cursor, Codex, Copilot and Devin Desktop all read."}, {when: /\b(don'?t touch|leave|only change|careful)/i, say: "State what is out of scope, because the leave-alone line is the highest-value line in agent prompting."}]},
  "v0": {default: "It builds Next.js, React and Tailwind apps for Vercel and can be called headlessly from your own product or CI.", facts: [{when: /\b(next\.?js|react|tailwind|vercel|shadcn)/i, say: "Next.js, React and Tailwind on Vercel is its sweet spot; requests off that stack degrade."}, {when: /\b(api|ci\b|pipeline|automat|headless|programmatic|from (my|our) (app|product))/i, say: "Its headless API lets your own product or CI generate apps, each one a chat that keeps its own state."}, {when: /\b(continue|iterate|keep working|follow[- ]up|same app)/i, say: "Each app is a chat holding its own state, so follow-up requests build on what it already made."}, {when: /\b(skills?|several features|many features|all at once)/i, say: "Each request is capped at three skills, so split bigger asks across several requests."}]},
  "lovable": {default: "Its Plan mode agrees the build before Build mode makes one slice at a time, which avoids prompting too early.", facts: [{when: /\b(don'?t (touch|change|break)|keep|already works|working)/i, say: "A leave-alone clause stops it rewriting working parts, and is the single highest-value instruction in this tool."}, {when: /\b(full[- ]?stack|login|database|accounts|backend|auth|users)/i, say: "Full-stack apps built incrementally are its listed strength, adding pieces like login and data one slice at a time."}, {when: /\b(colou?rs?|fonts?|look|style|design|spacing|buttons?)/i, say: "The preview toolbar changes looks directly, so visual tweaks don't need a new prompt."}, {when: /\b(idea|plan|not sure|figure out|brainstorm)/i, say: "Plan mode explores the idea before any code is written, which Lovable say avoids its most common mistake."}]},
  "bolt": {default: "It bills by token, and Plan Mode agrees the plan before building, the cheapest way to avoid wasted builds.", facts: [{when: /\b(don'?t (touch|change)|lock|protect|keep (the|my)|already works)/i, say: "File locking is the reliable way to stop unwanted edits, so finished files stay untouched."}, {when: /\b(design|style|nicer|pretty|fonts?|spacing|layout)/i, say: "It responds to real design vocabulary like font weight, line height, padding and radius, not 'make it nicer'."}, {when: /\b(prototype|first draft|quick|mvp|compare)/i, say: "Fast first drafts are its listed strength; compare three opening prompts, since the first one shapes the architecture."}, {when: /\b(budget|cheap|cost|tokens|credits)/i, say: "Because it bills by token, Plan Mode and file locking work as cost controls that cut wasted rebuilds."}]},
  "base44": {default: "It comes with a managed backend, auth and hosting, so an app has logins and stored data from the start.", facts: [{when: /\b(login|sign[- ]?in|accounts?|users?|auth)/i, say: "Auth is built in and managed, so user sign-in works without setting up a separate service."}, {when: /\b(database|data|records|track|inventory|crm|list of)/i, say: "Describe the entities and their relationships first; the data model is what screens and logic hang off."}, {when: /\b(internal tool|dashboard|admin|team tool|small business|tracker)/i, say: "Internal tools and small products are its listed strength, where handled auth, data and hosting beat framework control."}, {when: /\b(host|deploy|publish|online)/i, say: "Hosting is included, so the app goes live without configuring a separate server."}, {when: /\b(sdk|cli|developer)/i, say: "It has an SDK and CLI, so developers can work with the app outside the chat."}]},
  "generic-app": {default: "Build one scoped slice at a time and say what to leave alone, the rules every app builder shares.", facts: [{when: /\b(whole app|entire app|everything|complete app|full app)/i, say: "A prompt describing a whole app produces an app-shaped demo; one slice at a time produces working features."}, {when: /\b(don'?t (touch|change|break)|keep|already works)/i, say: "State what to leave alone, so working parts are not rewritten during the next change."}, {when: /\b(data|database|users|accounts|records)/i, say: "Name the data each slice works with; every builder in this category recommends it."}, {when: /\b(plan|idea|start|begin)/i, say: "Plan first, then build; every builder in this category recommends agreeing scope before code."}]},
  "perplexity": {default: "It searches the web for every answer and cites sources, so you get a grounded answer rather than a list of links.", facts: [{when: /\b(current|latest|today|recent|news|this (week|month|year)\b)|\b2026/i, say: "search_recency_filter limits sources to the last day, week, month or year, so the answer reflects current events."}, {when: /\b(sources?|only from|trusted|official|sites?|domains?|academic)/i, say: "search_domain_filter allows or blocks up to 20 domains, so answers draw only on sources you trust."}, {when: /\b(broad|wide|thorough|many sources|comprehensive|in[- ]depth)/i, say: "Raising search_context_size pulls in more evidence, a real quality dial for broad questions."}, {when: /\b(cite|citations?|references|evidence|fact[- ]check|verify)/i, say: "It is search-grounded by construction, so each claim comes with the citation it rests on."}]},
  "notebooklm": {default: "It answers only from the sources you upload, with citations back to your own documents.", facts: [{when: /\b(quote|exact|verify|proof|evidence)/i, say: "Ask it to quote the passage it relies on before answering, which turns a summary into something checkable."}, {when: /\b(don'?t make up|only (from|use)|no outside|stick to|accurate)/i, say: "It refuses to go beyond your sources, so it hedges rather than inventing facts that aren't in them."}, {when: /\b(my (notes|documents|files|pdfs|sources)|these (documents|files|pdfs)|uploaded|class notes|textbook|study)/i, say: "It stays grounded in the 50 to 600 sources you add, citing the passage in your documents behind each answer."}, {when: /\b(long session|all day|many questions|lots of questions)/i, say: "Its limit is chat queries per day, not tokens, so plan long study sessions around the daily cap."}]},
  "deepresearch": {default: "It plans, searches and iterates across many sources, then delivers a cited document rather than a quick answer.", facts: [{when: /\bgemini/i, say: "Gemini's Deep Research is single-turn and runs up to 120 minutes, so put every requirement in the first prompt."}, {when: /\b(decide|decision|choose|should (i|we)|compare|which)/i, say: "Naming the decision the research feeds changes what it prioritises more than any other line."}, {when: /\b(current|latest|today|recent|news|this (week|month|year)\b)|\b2026/i, say: "Name the exact date range, because all three tools are weak on very recent events otherwise."}, {when: /\b(hypothes|competing|uncertain|confidence)/i, say: "Claude's documented research pattern tracks competing hypotheses and confidence levels, so uncertain questions get weighed answers."}, {when: /\b(files?|uploaded|pdfs?|documents?)/i, say: "Say that instructions inside source files are data, not commands, because sources can carry prompt injection."}, {when: /\b(report|brief|literature|review|market|analysis)/i, say: "Long multi-source questions are its listed strength, producing a cited document in the structure you fix up front."}]},
  "generic-research": {default: "Name the decision the research feeds, so it produces an argument for that choice rather than a summary.", facts: [{when: /\b(current|latest|today|recent|news|this (week|month|year)\b)|\bsince\b/i, say: "Pin the date range; every research tool is weak on very recent events unless you do."}, {when: /\b(missing|unknown|no data|gaps?|unsure|not sure)/i, say: "Say what to do when evidence is missing, so gaps are flagged instead of filled with guesses."}, {when: /\b(report|structure|sections|format|table)/i, say: "Fix the output structure up front, so findings arrive in the sections you need."}, {when: /\b(scope|region|country|industry|market)/i, say: "State the scope, like region and time frame, so the search stays on your question."}]}
};
export { RECIPES, AI_FACTS };
